window.DQ=window.DQ||{};DQ["shabbat"]={"a":[["בְּיוֹם שִׁשִּׁי בַּמִּדְבָּר – כַּמָּה מָן לָקְטוּ בְּנֵי יִשְׂרָאֵל?",["סַל אֶחָד, כְּמוֹ בְּכָל יוֹם","פִּי שְׁנַיִם – לֶחֶם מִשְׁנֶה","לֹא לָקְטוּ בִּכְלָל"],1,"בְּיוֹם שִׁשִּׁי יָרַד מָן כָּפוּל – גַּם בִּשְׁבִיל שַׁבָּת. בְּשַׁבָּת עַצְמָהּ לֹא יָרַד מָן, וְהַמָּן שֶׁנִּשְׁמַר לְשַׁבָּת לֹא הִתְקַלְקֵל.","פֶּרֶק א׳, הֲלָכָה ז׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["שַׁמַּאי הַזָּקֵן מָצָא בְּאֶמְצַע הַשָּׁבוּעַ מַאֲכָל מְשֻׁבָּח. מָה עָשָׂה בּוֹ?",["אָכַל אוֹתוֹ מִיָּד","נָתַן אוֹתוֹ לַשָּׁכֵן","שָׁמַר אוֹתוֹ לְשַׁבָּת"],2,"שַׁמַּאי שָׁמַר אֶת הַטּוֹב בְּיוֹתֵר לְשַׁבָּת, וְאִם מָצָא טוֹב מִמֶּנּוּ – אָכַל אֶת הָרִאשׁוֹן וְשָׁמַר אֶת הַמְשֻׁבָּח. כָּךְ כָּל יָמָיו אָכַל לִכְבוֹד שַׁבָּת.","פֶּרֶק ב׳, הֲלָכָה א׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["אֵיזֶה בֶּגֶד מַתְאִים לִלְבֹּשׁ בְּשַׁבָּת?",["חֻלְצָה לְבָנָה וַחֲגִיגִית","בִּגְדֵי עֲבוֹדָה מְלֻכְלָכִים","חֻלְצַת סְפּוֹרְט מְקֻמֶּטֶת"],0,"בִּגְדֵי שַׁבָּת נָאִים וּנְקִיִּים מִבִּגְדֵי הַחוֹל, כִּי הֵם לִכְבוֹד הַשַּׁבָּת. גַּם מִי שֶׁנִּמְצָא לְבַדּוֹ לוֹבֵשׁ בֶּגֶד חֲגִיגִי.","פֶּרֶק ב׳, הֲלָכָה ד׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["אֵיךְ מִתְרַחֲצִים לִכְבוֹד שַׁבָּת?",["רַק שׁוֹטְפִים אֶת הַיָּדַיִם","בְּמַיִם חַמִּים, בְּעוֹד מוֹעֵד","בְּרִיצָה, כְּשֶׁהַשֶּׁמֶשׁ שׁוֹקַעַת"],1,"מִצְוָה לִרְחֹץ אֶת כָּל הַגּוּף בְּמַיִם חַמִּים. לֹא מִתְרַחֲצִים סָמוּךְ מִדַּי לַשַּׁבָּת, כְּדֵי שֶׁלֹּא נָבוֹא לְחַלֵּל אוֹתָהּ.","פֶּרֶק ב׳, הֲלָכָה ה׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["רָבָא הָיָה רֹאשׁ יְשִׁיבָה גָּדוֹל. מָה עָשָׂה בְּעַצְמוֹ לִכְבוֹד שַׁבָּת?",["שָׁלַח אֶת הַתַּלְמִידִים לְהָכִין","יָשַׁב וְחִכָּה שֶׁיָּכִינוּ לוֹ","מָלַח דָּגִים בְּיָדָיו"],2,"גַּם גְּדוֹלֵי הַדּוֹר הִשְׁתַּתְּפוּ בְּעַצְמָם בַּהֲכָנוֹת: רָבָא מָלַח דָּגִים, וְרַבָּה וְרַב יוֹסֵף בִּקְּעוּ עֵצִים. זֶה כְּבוֹדוֹ שֶׁל אָדָם – לְהִתְכּוֹנֵן לַשַּׁבָּת.","פֶּרֶק ב׳, הֲלָכָה ו׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["יוֹם שִׁשִּׁי, שָׁעָה לִפְנֵי שַׁבָּת, וְנָתָן רָעֵב. מָה מַתְאִים לוֹ לֶאֱכֹל?",["פְּרִי אוֹ מְעַט עוּגָה","אֲרוּחָה גְּדוֹלָה עִם לֶחֶם","מְסִבָּה עִם הַרְבֵּה מַאֲכָלִים"],0,"בְּשָׁלֹשׁ הַשָּׁעוֹת שֶׁלִּפְנֵי שַׁבָּת לֹא אוֹכְלִים אֲרוּחָה עִם לֶחֶם, כְּדֵי לֶאֱכֹל בְּתֵאָבוֹן אֶת סְעוּדַת לֵיל שַׁבָּת. מְעַט פֵּרוֹת אוֹ עוּגָה – אֶפְשָׁר.","פֶּרֶק ב׳, הֲלָכָה ז׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["בְּאֵיזֶה רֶגַע נִכְנֶסֶת הַשַּׁבָּת?",["בַּצָּהֳרַיִם","כְּשֶׁיּוֹצְאִים הַכּוֹכָבִים","בִּשְׁקִיעַת הַחַמָּה"],2,"הַשַּׁבָּת נִכְנֶסֶת בִּשְׁקִיעַת הַחַמָּה. הַזְּמַן שֶׁאַחֲרֶיהָ, עַד צֵאת הַכּוֹכָבִים, הוּא סָפֵק – וּבְסָפֵק שֶׁל תּוֹרָה מַחְמִירִים. וְעוֹד מוֹסִיפִים מְעַט לִפְנֵי הַשְּׁקִיעָה – תּוֹסֶפֶת שַׁבָּת.","פֶּרֶק ג׳, הֲלָכוֹת א׳–ב׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["בְּמוֹצָאֵי שַׁבָּת – מָתַי הַשַּׁבָּת יוֹצֵאת?",["שְׁלֹשָׁה כּוֹכָבִים קְטַנִּים","כּוֹכָב גָּדוֹל אֶחָד","הַשֶּׁמֶשׁ רַק שָׁקְעָה"],0,"הַשַּׁבָּת יוֹצֵאת בְּצֵאת הַכּוֹכָבִים. כְּדֵי לֹא לִטְעוֹת, מְחַכִּים לִשְׁלֹשָׁה כּוֹכָבִים קְטַנִּים הַקְּרוֹבִים זֶה לָזֶה. הַיּוֹם בּוֹדְקִים בְּלוּחַ הַזְּמַנִּים.","פֶּרֶק ג׳, הֲלָכָה ב׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["אֵיפֹה עִקַּר מִצְוַת נֵרוֹת שַׁבָּת?",["בַּחַלּוֹן, מוּל הָרְחוֹב","עַל שֻׁלְחַן הַסְּעוּדָה","בַּמַּחְסָן שֶׁבֶּחָצֵר"],1,"עִקַּר הַמִּצְוָה בִּמְקוֹם הַסְּעוּדָה – כְּדֵי לֶאֱכֹל לְאוֹר הַנֵּרוֹת, וּלְכַבֵּד וּלְעַנֵּג אֶת הַשַּׁבָּת. בַּחַלּוֹן מוּל הָרְחוֹב מַדְלִיקִים נֵרוֹת חֲנֻכָּה.","פֶּרֶק ד׳, הֲלָכָה ב׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["לְאַבְרָהָם יֵשׁ מְעַט כֶּסֶף לִכְבוֹד שַׁבָּת. מָה יִקְנֶה רִאשׁוֹן?",["בַּקְבּוּק יַיִן","נֵרוֹת לְשַׁבָּת","כִּכַּר לֶחֶם"],2,"קֹדֶם לֶחֶם – כְּדֵי שֶׁלֹּא יִצְטָרֵךְ לָצוּם בְּשַׁבָּת. אַחַר כָּךְ נֵרוֹת, וְרַק בַּסּוֹף יַיִן – כִּי אֶפְשָׁר לְקַדֵּשׁ גַּם עַל הַלֶּחֶם.","פֶּרֶק ד׳, הֲלָכָה א׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["כַּמָּה נֵרוֹת נָהֲגוּ לְהַדְלִיק לְשַׁבָּת, כְּנֶגֶד ״זָכוֹר״ וְ״שָׁמוֹר״?",["שְׁנֵי נֵרוֹת","חֲנֻכִּיָּה שְׁלֵמָה","נֵר אֶחָד קָטָן"],0,"מִן הַדִּין מַסְפִּיק נֵר אֶחָד, וְנָהֲגוּ לְהַדְלִיק שְׁנַיִם – כְּנֶגֶד ״זָכוֹר״ וְ״שָׁמוֹר״. יֵשׁ מוֹסִיפִים עוֹד נֵרוֹת לִבְנֵי הַבַּיִת.","פֶּרֶק ד׳, הֲלָכָה ג׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["אִמָּא הִתְעַכְּבָה בַּדֶּרֶךְ, וְהַשְּׁקִיעָה מִתְקָרֶבֶת. מָה עוֹשִׂים?",["מְחַכִּים לָהּ גַּם אַחֲרֵי הַשְּׁקִיעָה","נִשְׁאָרִים בְּלִי נֵרוֹת","אַבָּא מַדְלִיק בִּזְמַן"],2,"אִם הָאֵם מִתְעַכֶּבֶת וְהַשְּׁקִיעָה קְרֵבָה – אַבָּא אוֹ אֶחָד הַיְּלָדִים מַדְלִיק. אָסוּר לְהִכָּנֵס לְסָפֵק חִלּוּל שַׁבָּת.","פֶּרֶק ד׳, הֲלָכָה ב׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["מָה הַדֶּרֶךְ הַטּוֹבָה לְבַלּוֹת שַׁבָּת אַחַר הַצָּהֳרַיִם?",["יְשֵׁנִים כָּל הַיּוֹם","לוֹמְדִים תּוֹרָה עִם אַבָּא","מְדַבְּרִים עַל קְנִיּוֹת לַשָּׁבוּעַ"],1,"״לֹא נִתְּנוּ שַׁבָּתוֹת אֶלָּא לַעֲסֹק בָּהֶם בְּדִבְרֵי תוֹרָה״. שֵׁינָה הִיא עֹנֶג – אֲבָל לֹא כָּל הַיּוֹם. וּבְשַׁבָּת לֹא מְדַבְּרִים עַל עִנְיְנֵי חוֹל.","פֶּרֶק ה׳, הֲלָכוֹת א׳–ג׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["אַחֲרֵי עֲמִידָה שֶׁל לֵיל שַׁבָּת – אֵיךְ אוֹמְרִים ״וַיְכֻלּוּ״?",["כָּל הַצִּבּוּר, בַּעֲמִידָה וּבְקוֹל","בִּישִׁיבָה וּבְלַחַשׁ","רַק הַחַזָּן, לְבַדּוֹ"],0,"כָּל הַצִּבּוּר חוֹזֵר וְאוֹמֵר ״וַיְכֻלּוּ״ בְּקוֹל רָם וּבַעֲמִידָה – וּמֵעִיד יַחַד שֶׁה׳ בָּרָא אֶת הָעוֹלָם.","פֶּרֶק ה׳, הֲלָכָה י״ב","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["בְּסוֹף תְּפִלַּת שַׁבָּת – אֶל מִי נָהֲגוּ לָלֶכֶת וְלוֹמַר ״שַׁבָּת שָׁלוֹם״?",["אֶל הַגַּבַּאי, לְבַקֵּשׁ עֲלִיָּה","אֶל הַחֲנוּת שֶׁבַּשְּׁכוּנָה","אֶל רַב בֵּית הַכְּנֶסֶת"],2,"מִצְוָה לְהַקְבִּיל פְּנֵי רַבּוֹ. מִי שֶׁגָּר קָרוֹב מַקְבִּיל אֶת פְּנֵי הָרַב בְּכָל שַׁבָּת, וּבַאֲמִירַת ״שַׁבָּת שָׁלוֹם״ מְכַבְּדִים אוֹתוֹ וּמִתְקַשְּׁרִים לַתּוֹרָה.","פֶּרֶק ה׳, הֲלָכָה ט״ו","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["בְּשַׁבָּת הָרַב דּוֹרֵשׁ בְּבֵית הַכְּנֶסֶת. אֵיךְ הוֹלְכִים לִשְׁמֹעַ?",["בַּהֲלִיכָה אִטִּית מְאוֹד","בְּרִיצָה וּבְשִׂמְחָה","לֹא הוֹלְכִים – יוֹשְׁבִים לֶאֱכֹל"],1,"בְּשַׁבָּת בְּדֶרֶךְ כְּלָל לֹא מְמַהֲרִים, אֲבָל לִדְבַר תּוֹרָה – רָצִים: ״לְעוֹלָם יָרוּץ אָדָם לִדְבַר הֲלָכָה, וַאֲפִלּוּ בְּשַׁבָּת״. וּבִזְמַן הַדְּרָשָׁה לֹא קוֹבְעִים סְעוּדָה.","פֶּרֶק ה׳, הֲלָכָה ד׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["עַל אֵיזוֹ כּוֹס רָאוּי לְקַדֵּשׁ?",["כּוֹס סְדוּקָה וּשְׁבוּרָה","גָּבִיעַ שָׁלֵם וְנָקִי","כּוֹס מְלֻכְלֶכֶת"],1,"כּוֹס שֶׁל בְּרָכָה צְרִיכָה לִהְיוֹת שְׁלֵמָה וּנְקִיָּה – מִבִּפְנִים וּמִבַּחוּץ. וְאִם שָׁתוּ מִמֶּנָּה – שׁוֹטְפִים אוֹתָהּ.","פֶּרֶק ו׳, הֲלָכָה ו׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["עַל אֵיזֶה מַשְׁקֶה מְקַדְּשִׁים בְּלֵיל שַׁבָּת?",["כּוֹס חָלָב","מִיץ תַּפּוּזִים","יַיִן אוֹ מִיץ עֲנָבִים"],2,"תִּקְּנוּ לְקַדֵּשׁ עַל יַיִן – הַמַּשְׁקֶה הֶחָשׁוּב, הַמְּזִין וְהַמְשַׂמֵּחַ. אֶפְשָׁר גַּם עַל מִיץ עֲנָבִים, שֶׁכָּשֵׁר לְקִדּוּשׁ.","פֶּרֶק ו׳, הֲלָכוֹת ג׳–ד׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["אֵין יַיִן בַּבַּיִת בְּלֵיל שַׁבָּת. עַל מָה יְקַדֵּשׁ אַבָּא?",["עַל הַחַלּוֹת","עַל כּוֹס קוֹלָה","עַל כּוֹס קָפֶה"],0,"מִי שֶׁאֵין לוֹ יַיִן – מְקַדֵּשׁ בַּלַּיְלָה עַל הַפַּת. מַשְׁקֶה רָגִיל כְּמוֹ קוֹלָה אוֹ קָפֶה אֵינוֹ מַתְאִים לְקִדּוּשׁ הַלַּיְלָה.","פֶּרֶק ו׳, הֲלָכָה ג׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["אַבָּא חָזַר מִבֵּית הַכְּנֶסֶת צָמֵא מְאוֹד. מָה מֻתָּר לוֹ לִפְנֵי הַקִּדּוּשׁ?",["לִשְׁתּוֹת כּוֹס מַיִם","לִטְעֹם מִן הַסָּלָט","לִשְׁטֹף אֶת הַפֶּה"],2,"מִשֶּׁנִּכְנְסָה הַשַּׁבָּת אָסוּר לֶאֱכֹל וְלִשְׁתּוֹת לִפְנֵי הַקִּדּוּשׁ – אֲפִלּוּ מַיִם. לִשְׁטֹף אֶת הַפֶּה – מֻתָּר. וְהָעֵצָה הַטּוֹבָה: לְקַדֵּשׁ מִיָּד!","פֶּרֶק ו׳, הֲלָכָה ט׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["מָה עוֹשִׂים לַחַלּוֹת בִּשְׁעַת הַקִּדּוּשׁ?",["פּוֹרְסִים אוֹתָן מֵרֹאשׁ","מְכַסִּים אוֹתָן בְּכִסּוּי","מַחְזִירִים אוֹתָן לַמְּקָרֵר"],1,"מְכַסִּים אֶת הַחַלּוֹת, כִּי בְּדֶרֶךְ כְּלָל הַלֶּחֶם קוֹדֵם לַיַּיִן, וְעַכְשָׁו מְבָרְכִים קֹדֶם עַל הַיַּיִן. וְעוֹד – זֵכֶר לַמָּן שֶׁהָיָה מְכֻסֶּה בְּטַל.","פֶּרֶק ו׳, הֲלָכָה ח׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["עַל מָה מְבָרְכִים ״הַמּוֹצִיא״ בִּסְעוּדַת שַׁבָּת?",["שְׁתֵּי חַלּוֹת שְׁלֵמוֹת","חַלָּה אַחַת","פְּרוּסוֹת מִשַּׂקִּית"],0,"בּוֹצְעִים עַל לֶחֶם מִשְׁנֶה – שְׁתֵּי כִּכָּרוֹת שְׁלֵמוֹת, זֵכֶר לַמָּן הַכָּפוּל. אוֹחֲזִים אֶת שְׁתֵּיהֶן בִּשְׁעַת הַבְּרָכָה.","פֶּרֶק ז׳, הֲלָכָה ג׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["שַׁבָּת בַּבֹּקֶר, אַחֲרֵי הַתְּפִלָּה וְהַקִּדּוּשׁ. מָה נָכוֹן?",["לְהִתְעַנּוֹת עַד הָעֶרֶב","לֶאֱכֹל סְעוּדָה בְּשִׂמְחָה","לֶאֱכֹל עַד שֶׁהַבֶּטֶן כּוֹאֶבֶת"],1,"אָסוּר לְהִתְעַנּוֹת בְּשַׁבָּת. אוֹכְלִים בְּשִׂמְחָה וּבְהַרְחָבָה – אֲבָל לֹא יוֹתֵר מִדַּי, כְּדֵי שֶׁיִּהְיֶה כֹּחַ לִלְמֹד תּוֹרָה.","פֶּרֶק ז׳, הֲלָכָה ב׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["מוֹצָאֵי שַׁבָּת. מָה עוֹשִׂים לִכְבוֹד ״מְלַוֶּה מַלְכָּה״?",["פּוֹשְׁטִים מִיָּד אֶת בִּגְדֵי הַשַּׁבָּת","אוֹכְלִים בַּעֲמִידָה לְיַד הַמְּקָרֵר","עוֹרְכִים שֻׁלְחָן עִם מַפָּה"],2,"מְלַוִּים אֶת הַשַּׁבָּת כְּמוֹ מַלְכָּה: עוֹרְכִים שֻׁלְחָן עִם מַפָּה, נִשְׁאָרִים בְּבִגְדֵי שַׁבָּת, וְאוֹכְלִים לְכַתְּחִלָּה לֶחֶם וְתַבְשִׁיל.","פֶּרֶק ז׳, הֲלָכוֹת ז׳–ח׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["עַל אֵיזֶה נֵר מְבָרְכִים בַּהַבְדָּלָה לְכַתְּחִלָּה?",["נֵר נְשָׁמָה בְּכוֹס","נֵר קָלוּעַ עִם כַּמָּה פְּתִילוֹת","נוּרַת חַשְׁמַל"],1,"לְכַתְּחִלָּה מְבָרְכִים עַל ״אֲבוּקָה״ – נֵר קָלוּעַ שֶׁאוֹרוֹ רַב. נֵר נְשָׁמָה הוּדְלַק לְכָבוֹד וְלֹא כְּדֵי לְהָאִיר, וְעַל נוּרַת חַשְׁמַל רַבִּים אוֹמְרִים שֶׁאֵין מְבָרְכִים.","פֶּרֶק ח׳, הֲלָכָה ו׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["מָה נוֹהֲגִים לַעֲשׂוֹת לְאוֹר נֵר הַהַבְדָּלָה?",["מַבִּיטִים בַּצִּפָּרְנַיִם","קוֹרְאִים סֵפֶר","מְכַבִּים מִיָּד, בְּלִי לְהִסְתַּכֵּל"],0,"צָרִיךְ לֵהָנוֹת מֵאוֹר הַנֵּר, וְלָכֵן מַבִּיטִים לְאוֹרוֹ בַּצִּפָּרְנַיִם וּבְכַף הַיָּד. גַּם הַשּׁוֹמְעִים מִתְקָרְבִים כְּדֵי לִרְאוֹת אֶת הָאוֹר.","פֶּרֶק ח׳, הֲלָכָה ו׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["עַל אֵיזֶה רֵיחַ מְבָרְכִים בַּהַבְדָּלָה?",["מְטַהֵר אֲוִיר לַשֵּׁרוּתִים","דֵּאוֹדוֹרַנְט נֶגֶד זֵעָה","קֻפְסַת בְּשָׂמִים עִם צִפֹּרֶן"],2,"מְבָרְכִים עַל בְּשָׂמִים שֶׁנּוֹעֲדוּ לְרֵיחַ טוֹב. עַל רֵיחַ שֶׁנּוֹעַד לְהַעֲבִיר רֵיחַ רַע – בַּשֵּׁרוּתִים אוֹ נֶגֶד זֵעָה – אֵין מְבָרְכִים.","פֶּרֶק ח׳, הֲלָכָה ה׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["אַחֲרֵי הַפְּסוּקִים – עַל מָה מְבָרְכִים רִאשׁוֹנָה בַּהַבְדָּלָה?",["עַל הַבְּשָׂמִים","עַל הַיַּיִן","עַל הַנֵּר"],1,"הַסֵּדֶר: יַיִן, בְּשָׂמִים, נֵר, וּבַסּוֹף ״הַמַּבְדִּיל״. עוֹלִים מֵחוּשׁ הַטַּעַם לְרֵיחַ, לִרְאִיָּה – וְעַד הַשֵּׂכֶל שֶׁמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל.","פֶּרֶק ח׳, הֲלָכָה ב׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["עַל אֵיזֶה מַשְׁקֶה אִי אֶפְשָׁר לַעֲשׂוֹת הַבְדָּלָה?",["מִיץ עֲנָבִים","כּוֹס מַיִם","גָּבִיעַ יַיִן"],1,"מַבְדִּילִים עַל יַיִן אוֹ מִיץ עֲנָבִים, וּכְשֶׁאֵין – עַל ״חֲמַר מְדִינָה״, מַשְׁקֶה חָשׁוּב שֶׁמְּכַבְּדִים בּוֹ אוֹרְחִים. עַל מַיִם אֵין מַבְדִּילִים, כִּי הֵם לֹא מַשְׁקֶה שֶׁל כָּבוֹד.","פֶּרֶק ח׳, הֲלָכָה ד׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["מֵאֵיזוֹ עֲבוֹדָה לָמְדוּ חֲכָמִים מָה הֵן הַמְּלָאכוֹת הָאֲסוּרוֹת בְּשַׁבָּת?",["עֲבוֹדַת הַפֶּרֶךְ בְּמִצְרַיִם","בִּנְיַן מִגְדַּל בָּבֶל","בִּנְיַן הַמִּשְׁכָּן בַּמִּדְבָּר"],2,"לְיַד פָּרָשַׁת הַמִּשְׁכָּן נֶאֱמַר ״אַךְ אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ״. כָּל מְלָאכָה שֶׁהָיְתָה בַּמִּשְׁכָּן – אֲסוּרָה בְּשַׁבָּת, וְהֵן ל״ט מְלָאכוֹת.","פֶּרֶק ט׳, הֲלָכָה ב׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["אֵיזוֹ פְּעֻלָּה מֻתֶּרֶת בְּשַׁבָּת?",["כְּתִיבָה בְּמַחְבֶּרֶת","סִדּוּר כִּסְאוֹת בַּבַּיִת","דְּפִיקַת מַסְמֵר בַּקִּיר"],1,"הַתּוֹרָה אָסְרָה מְלֶאכֶת יְצִירָה כְּמוֹ בַּמִּשְׁכָּן, וְלֹא כָּל מַאֲמָץ. הַעֲבָרַת כִּסְאוֹת בְּתוֹךְ הַבַּיִת אֵינָהּ מְלָאכָה, אֲבָל כְּתִיבָה וּבְנִיָּה בַּקִּיר – מְלָאכוֹת.","פֶּרֶק ט׳, הֲלָכָה א׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["מָה עוֹשֶׂה הַחֲמוֹר שֶׁל יְהוּדִי בְּשַׁבָּת?",["נָח בַּמִּרְעֶה","סוֹחֵב שַׂקִּים","מוֹשֵׁךְ עֲגָלָה"],0,"״לֹא תַעֲשֶׂה כָל מְלָאכָה... וְשׁוֹרְךָ וַחֲמֹרְךָ״ – אָסוּר לְהַעֲבִיד בְּהֵמוֹת בְּשַׁבָּת, וְגַם הֵן נָחוֹת.","פֶּרֶק ט׳, הֲלָכָה י׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["אֵיזוֹ פְּעֻלָּה הִיא מְלֶאכֶת בִּשּׁוּל, הָאֲסוּרָה בְּשַׁבָּת?",["טִגּוּן בֵּיצָה בְּמַחֲבַת","חִתּוּךְ עוּגָה לִפְרוּסוֹת","מְזִיגַת מִיץ קַר"],0,"טִגּוּן הוּא סוּג שֶׁל בִּשּׁוּל, וְהוּא אָסוּר מִן הַתּוֹרָה – גַּם אִם הָאֵשׁ כְּבָר כְּבוּיָה וְרַק הַמַּחֲבַת חַמָּה. חִתּוּךְ עוּגָה וּמְזִיגַת מִיץ – מֻתָּרִים.","פֶּרֶק י׳, הֲלָכָה ב׳","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["אֵיזֶה מַאֲכָל מֻתָּר לְחַמֵּם בְּשַׁבָּת, בַּדֶּרֶךְ הַמֻּתֶּרֶת?",["תַּפּוּחַ אֲדָמָה חַי","אֹרֶז שֶׁלֹּא בֻּשַּׁל","שְׁנִיצֶל מְטֻגָּן"],2,"הַשְּׁנִיצֶל כְּבָר טֻגַּן לִפְנֵי שַׁבָּת, וְאֵין בִּשּׁוּל אַחַר בִּשּׁוּל. לְחַמֵּם תַּפּוּחַ אֲדָמָה חַי אוֹ אֹרֶז שֶׁלֹּא בֻּשַּׁל – זֶה בִּשּׁוּל מַמָּשׁ.","פֶּרֶק י׳, הֲלָכוֹת ג׳, י״ח","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["קוּגֶל מְבֻשָּׁל הִתְקָרֵר. אֵיפֹה מֻתָּר לְחַמֵּם אוֹתוֹ בְּשַׁבָּת?",["עַל אֵשׁ גְּלוּיָה שֶׁל הַגָּז","עַל גַּבֵּי מֵיחַם חַם","בְּתוֹךְ תַּנּוּר אֲפִיָּה חַם"],1,"עַל גַּבֵּי מֵיחַם אוֹ סִיר שֶׁעוֹמְדִים עַל הָאֵשׁ אֵין דֶּרֶךְ לְבַשֵּׁל, וְלָכֵן מֻתָּר. עַל אֵשׁ גְּלוּיָה אוֹ בְּתוֹךְ תַּנּוּר חַם – זֶה נִרְאֶה כְּבִשּׁוּל.","פֶּרֶק י׳, הֲלָכוֹת י״ח, כ״א","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["מִי שֶׁרוֹצֶה תֵּה בְּשַׁבָּת – לְאָן אָסוּר בְּשׁוּם אֹפֶן לְהַכְנִיס שַׂקִּית תֵּה?",["לְתוֹךְ הַמֵּיחַם עַצְמוֹ","לְכוֹס שֶׁמִּלְּאוּ מִן הַמֵּיחַם","לְכוֹס שֶׁמָּזְגוּ מִכּוֹס אַחֶרֶת"],0,"הַמֵּיחַם הוּא כְּלִי רִאשׁוֹן, וְהַתֵּה מִתְבַּשֵּׁל בּוֹ – אָסוּר לְכֻלֵּי עָלְמָא. בַּכּוֹס שֶׁמִּלְּאוּ מִן הַמֵּיחַם (כְּלִי שֵׁנִי) יֵשׁ חוֹשְׁשִׁים, וּבַסֵּפֶר מוּבָא שֶׁבְּכוֹס שְׁלִישִׁית מֻתָּר. רַבִּים מְכִינִים תַּמְצִית תֵּה מִלִּפְנֵי שַׁבָּת.","פֶּרֶק י׳, הֲלָכוֹת ז׳–ח׳","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["חַמִּין שֶׁעוֹד לֹא גָּמַר לְהִתְבַּשֵּׁל. עַל מָה יַשְׁאִירוּ אוֹתוֹ מִלִּפְנֵי שַׁבָּת?",["עַל פְּלָטָה חַשְׁמַלִּית","עַל אֵשׁ גָּז גְּלוּיָה","עַל הַפְּלָטָה, עָטוּף בִּשְׂמִיכָה"],0,"בַּפְּלָטָה הָאֵשׁ מְכֻסָּה, וְאֵין חֲשָׁשׁ שֶׁיַּגְבִּירוּ אוֹתָהּ. עַל אֵשׁ גְּלוּיָה – חוֹשְׁשִׁים שֶׁיַּגְבִּירוּ. וְסִיר שֶׁעַל הַפְּלָטָה אָסוּר לַעֲטֹף כֻּלּוֹ, כִּי הַפְּלָטָה מוֹסִיפָה לוֹ חֹם.","פֶּרֶק י׳, הֲלָכוֹת ט״ז, כ״ג","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["סִיר הַחַמִּין עוֹמֵד עַל הַפְּלָטָה. מָה אָסוּר לַעֲשׂוֹת?",["לְהָרִיחַ אֶת הָרֵיחַ הַטּוֹב","לְעַרְבֵּב אֶת הַתַּבְשִׁיל בְּכַף","לָקַחַת מַיִם חַמִּים מִן הַמֵּיחַם"],1,"עִרְבּוּב בְּסִיר שֶׁעַל הָאֵשׁ נִרְאֶה כְּבִשּׁוּל, וְאִם הַתַּבְשִׁיל עוֹד לֹא מוּכָן – הוּא גַּם מְזָרֵז אֶת הַבִּשּׁוּל. לָקַחַת מַיִם מִן הַמֵּיחַם שֶׁעַל הַפְּלָטָה – מֻתָּר לְכָל הַדֵּעוֹת.","פֶּרֶק י׳, הֲלָכָה י״ב","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["קוּגֶל לוֹהֵט יָצָא עַכְשָׁו מִן הַסִּיר. מָה לֹא מְפַזְּרִים עָלָיו עַד שֶׁיִּצְטַנֵּן?",["פְּרוּסוֹת מְלָפְפוֹן חָמוּץ","פְּרוּסוֹת עַגְבָנִיָּה","אַבְקַת פַּפְּרִיקָה"],2,"תַּבְלִינִים חַיִּים כְּמוֹ פַּפְּרִיקָה מִתְבַּשְּׁלִים עַל הַקּוּגֶל הַלּוֹהֵט, וְהַבִּשּׁוּל מוֹעִיל לָהֶם. בִּמְלָפְפוֹן חָמוּץ וּבִירָקוֹת – אֵין כַּוָּנָה לְבַשֵּׁל, וּמֻתָּר.","פֶּרֶק י׳, הֲלָכָה י׳","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["רוֹצִים שֶׁיִּהְיוּ מַיִם חַמִּים גַּם מְאֻחָר יוֹתֵר בְּשַׁבָּת. מָה מֻתָּר לַעֲשׂוֹת?",["לְמַלֵּא תֶּרְמוֹס מִן הַמֵּיחַם","לַעֲטֹף קֻמְקוּם חַם בִּשְׂמִיכָה","לְהַעֲמִיד קֻמְקוּם עַל הָאֵשׁ"],0,"הַכְנָסַת מַיִם חַמִּים לְתֶרְמוֹס אֵינָהּ הַטְמָנָה. אֲבָל לַעֲטֹף כְּלִי חַם בְּשַׁבָּת – אָסוּר, וּלְחַמֵּם מַיִם קָרִים עַל הָאֵשׁ – זֶה בִּשּׁוּל.","פֶּרֶק י׳, הֲלָכוֹת ד׳, כ״ב","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["בּוֹטְנִים מְעֹרָבִים בִּקְלִפּוֹת. מָה מֻתָּר לַעֲשׂוֹת כְּדֵי לֶאֱכֹל עַכְשָׁו?",["לְהוֹצִיא אֶת הַקְּלִפּוֹת מִן הַקְּעָרָה","לָקַחַת בּוֹטְנִים בַּיָּד וְלֶאֱכֹל","לְנַעֵר אֶת הַכֹּל דֶּרֶךְ רֶשֶׁת"],1,"לוֹקְחִים אֶת הָאֹכֶל מִתּוֹךְ הַפְּסֹלֶת, בַּיָּד, כְּדֵי לֶאֱכֹל עַכְשָׁו – וְזוֹ דֶּרֶךְ אֲכִילָה. הוֹצָאַת הַקְּלִפּוֹת הִיא הוֹצָאַת פְּסֹלֶת, וְרֶשֶׁת הִיא כְּלִי בֵּרוּר.","פֶּרֶק י״א, הֲלָכָה ב׳","בּוֹרְרִים אֶת הַטּוֹב"],["קְלִפַּת בֵּיצָה נָפְלָה לְתוֹךְ סָלַט בֵּיצִים. אֵיךְ מוֹצִיאִים אוֹתָהּ?",["אֶת הַקְּלִפָּה לְבַדָּהּ, בָּאֶצְבָּעוֹת","בְּכַף מְחֹרֶרֶת שֶׁמְּסַנֶּנֶת","יַחַד עִם מְעַט סָלָט"],2,"הַקְּלִפָּה הִיא פְּסֹלֶת, וְאָסוּר לְהוֹצִיא אוֹתָהּ לְבַדָּהּ. כְּשֶׁמּוֹצִיאִים אוֹתָהּ עִם מְעַט בֵּיצָה – מוֹצִיאִים אֹכֶל מִתּוֹךְ אֹכֶל, וְאֵין בָּזֶה אִסּוּר.","פֶּרֶק י״א, הֲלָכָה ה׳","בּוֹרְרִים אֶת הַטּוֹב"],["בְּקֻפְסָה אַחַת הִתְעָרְבוּ שְׁנֵי סוּגִים שֶׁל קֻבִּיּוֹת מִשְׂחָק. מָה מֻתָּר לַעֲשׂוֹת בְּשַׁבָּת?",["לִבְחֹר אֶת הַסּוּג שֶׁמְּשַׂחֲקִים בּוֹ עַכְשָׁו","לְמַיֵּן לִשְׁתֵּי קֻפְסָאוֹת נִפְרָדוֹת","לְהוֹצִיא אֶת הַקֻּבִּיּוֹת שֶׁלֹּא צְרִיכִים"],0,"לָקַחַת אֶת הַקֻּבִּיּוֹת שֶׁמְּשַׂחֲקִים בָּהֶן עַכְשָׁו – זוֹ דֶּרֶךְ מִשְׂחָק. מִיּוּן לִשְׁתֵּי קֻפְסָאוֹת, אוֹ הוֹצָאַת מָה שֶׁלֹּא צְרִיכִים – זֶה בּוֹרֵר.","פֶּרֶק י״א, הֲלָכָה ט״ז","בּוֹרְרִים אֶת הַטּוֹב"],["מָתַי מֻתָּר לְקַלֵּף תַּפּוּז בְּשַׁבָּת?",["בְּלֵיל שַׁבָּת, לַאֲרוּחָה שֶׁל מָחָר","מִיָּד לִפְנֵי שֶׁאוֹכְלִים אוֹתוֹ","בַּבֹּקֶר, לַסְּעוּדָה הַשְּׁלִישִׁית"],1,"קְלִיפַת פְּרִי כְּדֵי לֶאֱכֹל אוֹתוֹ עַכְשָׁו הִיא דֶּרֶךְ אֲכִילָה. קְלִיפָה כְּדֵי לֶאֱכֹל אַחֲרֵי זְמַן רַב – הִיא דֶּרֶךְ מְלָאכָה, וַאֲסוּרָה.","פֶּרֶק י״א, הֲלָכָה ח׳","בּוֹרְרִים אֶת הַטּוֹב"],["בְּאֵיזֶה כְּלִי אָסוּר לְהִשְׁתַּמֵּשׁ בְּשַׁבָּת לַהֲכָנַת אֹכֶל?",["סַכִּין לַחֲתִיכַת יְרָקוֹת","מַזְלֵג לִמְעִיכַת בָּנָנָה","פּוּמְפִּיָּה (מְגָרֶדֶת)"],2,"הַפּוּמְפִּיָּה נוֹעֲדָה לִטְחִינָה, וְאָסוּר לְהִשְׁתַּמֵּשׁ בָּהּ. בְּסַכִּין מֻתָּר לַחְתֹּךְ יְרָקוֹת לְסָלָט סָמוּךְ לַסְּעוּדָה, וּבְמַזְלֵג מֻתָּר לִמְעֹךְ בָּנָנָה לִפְנֵי הָאֲכִילָה.","פֶּרֶק י״ב, הֲלָכָה ב׳","בּוֹרְרִים אֶת הַטּוֹב"],["אֵיפֹה מֻתָּר לִסְחֹט לִימוֹן בְּשַׁבָּת?",["עַל סָלַט יְרָקוֹת","לְתוֹךְ כּוֹס רֵיקָה","לְתוֹךְ קַנְקַן מַיִם"],0,"כְּשֶׁסּוֹחֲטִים עַל סָלָט, הַמִּיץ עוֹבֵר מִמַּאֲכָל לְמַאֲכָל, וְאֵינוֹ נַעֲשֶׂה מַשְׁקֶה. סְחִיטָה לְכוֹס רֵיקָה אוֹ לְמַיִם – עוֹשָׂה מַשְׁקֶה, וַאֲסוּרָה.","פֶּרֶק י״ב, הֲלָכָה ח׳","בּוֹרְרִים אֶת הַטּוֹב"],["מָה מֻתָּר לְפוֹרֵר בְּשַׁבָּת?",["גּוּשׁ אֲדָמָה יָבֵשׁ","פְּרוּסַת לֶחֶם","פּוֹלֵי קָפֶה"],1,"לֶחֶם כְּבָר נִטְחַן לְקֶמַח לִפְנֵי שֶׁנֶּאֱפָה, וְלָכֵן מֻתָּר לְפוֹרֵר אוֹתוֹ. גּוּשׁ אֲדָמָה וּפוֹלֵי קָפֶה הִתְגַּבְּשׁוּ בַּטֶּבַע, וּפִרּוּרָם הוּא טְחִינָה.","פֶּרֶק י״ב, הֲלָכָה א׳","בּוֹרְרִים אֶת הַטּוֹב"],["רוֹצִים לֶאֱכֹל עַכְשָׁו רַק אֶת הַמָּרָק, בְּלִי הַיְּרָקוֹת הַקְּטַנִּים שֶׁבּוֹ. מָה מֻתָּר?",["לְהַטּוֹת אֶת הַסִּיר וְלִשְׁפֹּךְ מָרָק לַקְּעָרָה","לִשְׁפֹּךְ אֶת הַמָּרָק דֶּרֶךְ מְסַנֶּנֶת","לְסַנֵּן דֶּרֶךְ רֶוַח צַר בַּמִּכְסֶה"],0,"מִי שֶׁרוֹצֶה אֶת הַמָּרָק – הַמָּרָק הוּא הָאֹכֶל, וּשְׁפִיכָתוֹ הִיא הוֹצָאַת אֹכֶל מִן הַפְּסֹלֶת. אֲבָל מְסַנֶּנֶת אוֹ מִכְסֶה שֶׁמְּשַׁמֵּשׁ כִּמְסַנֶּנֶת – הֵם בֵּרוּר בִּכְלִי.","פֶּרֶק י״א, הֲלָכָה י״ב","בּוֹרְרִים אֶת הַטּוֹב"],["מָה מֻתָּר לַעֲשׂוֹת בְּשַׁבָּת?",["לְנַגֵּב יָדַיִם בְּמַגֶּבֶת","לִסְחֹט מַגֶּבֶת רְטֻבָּה","לְהָסִיר כֶּתֶם בְּמַיִם"],0,"נִגּוּב הַיָּדַיִם מְלַכְלֵךְ אֶת הַמַּגֶּבֶת וְאֵינוֹ מְנַקֶּה אוֹתָהּ, וְלָכֵן מֻתָּר. סְחִיטָה וַהֲסָרַת כֶּתֶם הֵם חֵלֶק מִן הַכִּבּוּס, וַאֲסוּרִים מִן הַתּוֹרָה.","פֶּרֶק י״ג, הֲלָכוֹת ג׳–ד׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["נִשְׁפַּךְ דְּלִי מַיִם עַל הָרִצְפָּה הַמְרֻצֶּפֶת. מָה מֻתָּר לַעֲשׂוֹת?",["לִסְפֹּג בִּסְפוֹג וְלִסְחֹט לַדְּלִי","לִגְרֹף אֶת הַמַּיִם בְּמַגָּב","לִשְׁטֹף אֶת כָּל הָרִצְפָּה בְּסַבּוֹן"],1,"מַיִם רַבִּים שֶׁנִּשְׁפְּכוּ עַל הָרִצְפָּה מֻתָּר לִגְרֹף בְּמַגָּב. סְפוֹג שֶׁסּוֹחֲטִים – אָסוּר, וּשְׁטִיפַת רִצְפָּה בְּמַיִם – אֲסוּרָה.","פֶּרֶק י״ג, הֲלָכָה ה׳; פֶּרֶק ט״ו, הֲלָכָה ט׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["אֵיזֶה נְיַר טוּאָלֶט מְכִינִים לְשַׁבָּת?",["דַּפִּים שֶׁנִּקְרְעוּ לִפְנֵי שַׁבָּת","גָּלִיל שָׁלֵם שֶׁקּוֹרְעִים בְּשַׁבָּת","גָּלִיל וּמִסְפָּרַיִם לְיָדוֹ"],0,"קְרִיעַת נְיַר טוּאָלֶט מִן הַגָּלִיל אֲסוּרָה מִן הַתּוֹרָה, וְגַם חִתּוּךְ בְּמִסְפָּרַיִם. לָכֵן מְכִינִים לִפְנֵי שַׁבָּת דַּפִּים קְרוּעִים.","פֶּרֶק י״ג, הֲלָכָה י״א","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["אֵיזֶה קֶשֶׁר מֻתָּר לִקְשֹׁר בְּשַׁבָּת?",["קֶשֶׁר כָּפוּל מְהֻדָּק בַּשַּׂקִּית","עֲנִיבָה בִּשְׂרוֹךְ הַנַּעַל","הִדּוּק קֶשֶׁר הַצִּיצִית"],1,"עֲנִיבָה נִפְתַּחַת בִּמְשִׁיכָה אַחַת, וְאֵינָהּ נֶחְשֶׁבֶת קֶשֶׁר. קֶשֶׁר כָּפוּל מְהֻדָּק – אָסוּר, וְקֶשֶׁר הַצִּיצִית הוּא קֶשֶׁר קָבוּעַ שֶׁאָסוּר לְהַדֵּק.","פֶּרֶק י״ג, הֲלָכוֹת י״ג–ט״ו","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["מָה מֻתָּר לִרְחֹץ בְּמַיִם חַמִּים בְּשַׁבָּת?",["אֶת כָּל הַגּוּף בְּאַמְבַּטְיָה","אֶת הַפָּנִים וְהַיָּדַיִם","שְׂחִיָּה בִּבְרֵכָה מְחֻמֶּמֶת"],1,"חֲכָמִים גָּזְרוּ שֶׁלֹּא לִרְחֹץ אֶת רֹב הַגּוּף בְּחַמִּים, אֲבָל פָּנִים וְיָדַיִם – מֻתָּר. וּשְׂחִיָּה אֲסוּרָה בְּשַׁבָּת.","פֶּרֶק י״ד, הֲלָכוֹת ח׳–ט׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["מָה אָסוּר מִן הַתּוֹרָה בְּשַׁבָּת?",["לְהַגְבִּיר אֶת אֵשׁ הַגָּז","לְהִסְתַּכֵּל בְּנֵרוֹת שַׁבָּת","לִלְבֹּשׁ סְוֶדֶר צֶמֶר"],0,"בְּשַׁבָּת גַּם הַגְבָּרַת אֵשׁ קַיֶּמֶת אֲסוּרָה מִן הַתּוֹרָה. לְהִסְתַּכֵּל בַּנֵּרוֹת – מֻתָּר, וּמִסְּוֶדֶר צֶמֶר יוֹצְאִים נִיצוֹצוֹת בְּלִי כַּוָּנָה, וְאֵין בָּזֶה אִסּוּר.","פֶּרֶק ט״ז, הֲלָכָה ב׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["הַנֵּרוֹת דּוֹלְקִים, וְרוּחַ חֲזָקָה מַתְחִילָה לִנְשֹׁב מֵהַחַלּוֹן הַפָּתוּחַ. מָה מֻתָּר?",["לִפְתֹּחַ עוֹד חַלּוֹן מוּל הַנֵּרוֹת","לִסְגֹּר אֶת הַחַלּוֹן","לְכַבּוֹת אֶת הַנֵּרוֹת"],1,"בִּסְגִירַת הַחַלּוֹן לֹא עוֹשִׂים דָּבָר בַּנֵּר עַצְמוֹ – רַק מוֹנְעִים מִן הָרוּחַ לְכַבּוֹת אוֹתוֹ. פְּתִיחַת חַלּוֹן מוּל הַנֵּרוֹת וְכִבּוּי הַנֵּרוֹת – אֲסוּרִים.","פֶּרֶק ט״ז, הֲלָכָה ד׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["לְאוֹר מָה מֻתָּר לְיוֹסֵף לִקְרֹא סֵפֶר לְבַדּוֹ בְּלֵיל שַׁבָּת?",["נֵר שֶׁמֶן עִם פְּתִילָה","פָּנָס שֶׁהוּא מַדְלִיק עַכְשָׁו","נוּרָה חַשְׁמַלִּית שֶׁדּוֹלֶקֶת"],2,"אוֹר הַנּוּרָה אֵינוֹ נֶחְלָשׁ, וְאֵין חֲשָׁשׁ שֶׁיַּטֶּה אוֹתָהּ – לָכֵן מֻתָּר לִקְרֹא לְאוֹרָהּ לְבַד. לְאוֹר נֵר שֶׁמֶן – רַק עִם חָבֵר. וּלְהַדְלִיק פָּנָס – אָסוּר.","פֶּרֶק ט״ז, הֲלָכָה ג׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["בְּאֶמְצַע סְעוּדַת שַׁבָּת הַטֶּלֶפוֹן מְצַלְצֵל. מָה עוֹשִׂים?",["מַמְשִׁיכִים בַּסְּעוּדָה, וְלֹא עוֹנִים","עוֹנִים וּמְדַבְּרִים בְּקִצּוּר","לוֹחֲצִים עַל כַּפְתּוֹר הַהַשְׁתָּקָה"],0,"אָסוּר לְהַפְעִיל מַכְשִׁירִים חַשְׁמַלִּיִּים בְּשַׁבָּת, וְאָסוּר לְדַבֵּר בְּטֶלֶפוֹן. גַּם לְחִיצָה עַל כַּפְתּוֹר כְּדֵי לְהַשְׁתִּיק – הִיא הַפְעָלָה שֶׁל הַמַּכְשִׁיר.","פֶּרֶק י״ז, הֲלָכוֹת ב׳–ג׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["שְׁעוֹן הַשַּׁבָּת עוֹמֵד לְכַבּוֹת אֶת הָאוֹר, וְדָוִד רוֹצֶה לְהַמְשִׁיךְ לִלְמֹד. מָה אָסוּר לוֹ לַעֲשׂוֹת?",["לְהַדְלִיק נוּרָה נוֹסֶפֶת","לַעֲבֹר לִלְמֹד בַּחֶדֶר הַמּוּאָר","לָשֶׁבֶת לִלְמֹד לְיַד הַחַלּוֹן"],0,"הַדְלָקַת נוּרָה הִיא מְלָאכָה – אֲסוּרָה. לַעֲבֹר לְחֶדֶר שֶׁהָאוֹר בּוֹ דּוֹלֵק אוֹ לִלְמֹד לְאוֹר הַיּוֹם – מֻתָּר. וְכָךְ שׁוֹמְרִים עַל הַשַּׁבָּת וְגַם מַמְשִׁיכִים לִלְמֹד תּוֹרָה.","פֶּרֶק י״ז, הֲלָכָה ו׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["אֵיזֶה מְקָרֵר מֻתָּר לִפְתֹּחַ בְּשַׁבָּת?",["שֶׁהַנּוּרָה בּוֹ נִדְלֶקֶת בִּפְתִיחָה","שֶׁהַנּוּרָה שֶׁלּוֹ נֻתְּקָה לִפְנֵי שַׁבָּת","שֶׁיֵּשׁ לוֹ מָסָךְ שֶׁנִּדְלָק בִּנְגִיעָה"],1,"כְּשֶׁפְּתִיחַת הַמְּקָרֵר אֵינָהּ מַדְלִיקָה וְאֵינָהּ מְכַבָּה דָּבָר – מֻתָּר לִפְתֹּחַ. מְקָרֵר שֶׁהַנּוּרָה בּוֹ נִדְלֶקֶת אוֹ שֶׁמָּסָךְ נִדְלָק בּוֹ – אָסוּר.","פֶּרֶק י״ז, הֲלָכוֹת ח׳–ט׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["מָה אָסוּר לַעֲשׂוֹת בְּשַׁבָּת?",["לְצַיֵּר בָּאֶצְבַּע עַל אֵדִים בַּחַלּוֹן","לְקַפֵּל פִּנָּה שֶׁל דַּף בַּסֵּפֶר","לְסַדֵּר קֻבִּיּוֹת בְּצוּרָה שֶׁל אוֹת"],0,"צִיּוּר עַל אֵדִים הוּא כְּתִיבָה זְמַנִּית, וַחֲכָמִים אָסְרוּ אוֹתָהּ. קִפּוּל פִּנַּת הַדַּף הוּא סִימָן בְּלִי כְּתִיבָה, וְסִדּוּר קֻבִּיּוֹת – הֵן כְּבָר הָיוּ קַיָּמוֹת, וְרַק מְקָרְבִים אוֹתָן.","פֶּרֶק י״ח, הֲלָכָה ד׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["מָה מֻתָּר לַעֲשׂוֹת בַּגִּנָּה בְּשַׁבָּת?",["לָשֶׁבֶת עַל הַדֶּשֶׁא","לְהַשְׁקוֹת אֶת הָעֲצִיץ","לִקְטֹף תַּפּוּחַ מֵהָעֵץ"],0,"עַל דֶּשֶׁא רַךְ מֻתָּר לָשֶׁבֶת. הַשְׁקָיָה אֲסוּרָה מִשּׁוּם זוֹרֵעַ, וּקְטִיפָה – מִשּׁוּם קוֹצֵר.","פֶּרֶק י״ט, הֲלָכוֹת ד׳, ו׳, ח׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["הַכַּדּוּר נִתְקַע בֵּין עַנְפֵי הָעֵץ. מָה עוֹשִׂים בְּשַׁבָּת?",["מְנַעְנְעִים אֶת הָעֵץ","מְטַפְּסִים עַל הָעֵץ","מַשְׁאִירִים וּמְחַכִּים"],2,"אָסוּר לְהִשְׁתַּמֵּשׁ בָּעֵץ בְּשַׁבָּת: לֹא מְטַפְּסִים וְלֹא מְנַעְנְעִים כְּדֵי לְהוֹרִיד מִמֶּנּוּ כַּדּוּר. אִם הַכַּדּוּר יִפֹּל מֵעַצְמוֹ – אֶפְשָׁר לְשַׂחֵק בּוֹ.","פֶּרֶק י״ט, הֲלָכָה ז׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["צִפּוֹר נִכְנְסָה הַבַּיְתָה דֶּרֶךְ הַחַלּוֹן. מָה נָכוֹן לַעֲשׂוֹת?",["סוֹגְרִים מַהֵר אֶת הַחַלּוֹן","נוֹתְנִים לָהּ לָצֵאת","תּוֹפְסִים אוֹתָהּ בַּיָּדַיִם"],1,"סְגִירַת הַחַלּוֹן אַחֲרֵי הַצִּפּוֹר הִיא צֵידָה, וְגַם תְּפִיסָה בַּיָּדַיִם. מְגָרְשִׁים אוֹתָהּ הַחוּצָה, וְרַק אַחַר כָּךְ סוֹגְרִים.","פֶּרֶק כ׳, הֲלָכָה ז׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["יֵשׁ נְמָלִים עַל הַשְּׁבִיל. אֵיךְ עוֹבְרִים בְּשַׁבָּת?",["מְדַלְּגִים מֵעֲלֵיהֶן","דּוֹרְכִים עֲלֵיהֶן בְּכַוָּנָה","מְרַסְּסִים עֲלֵיהֶן"],0,"אָסוּר לַהֲרֹג בְּשַׁבָּת אֲפִלּוּ נְמָלָה. לָכֵן מְדַלְּגִים מֵעֲלֵיהֶן, וְאִם יֵשׁ הַרְבֵּה – עוֹקְפִים.","פֶּרֶק כ׳, הֲלָכָה ח׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["לְמִי מֻתָּר לָתֵת אֹכֶל בְּשַׁבָּת?",["לַדְּבוֹרִים בַּכַּוֶּרֶת","לְיוֹנֵי הַשּׁוֹבָךְ","לֶחָתוּל הָרָעֵב"],2,"נוֹתְנִים אֹכֶל לְחַיּוֹת שֶׁתְּלוּיוֹת בָּנוּ, וְגַם לְחָתוּל רָעֵב. דְּבוֹרִים וְיוֹנֵי שׁוֹבָךְ מִסְתַּדְּרוֹת לְבַד, וְזוֹ טִרְחָה מְיֻתֶּרֶת.","פֶּרֶק כ׳, הֲלָכָה ג׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["אֵין עֵרוּב. אֵיךְ מֻתָּר לְהָבִיא לְסַבָּא חֻלְצָה?",["בְּשַׂקִּית בַּיָּד","לָבוּשׁ עַל הַחֻלְצָה","מֻנָּחַת עַל הַכָּתֵף"],1,"בֶּגֶד שֶׁלּוֹבְשִׁים הוּא חֵלֶק מִן הַגּוּף, וְיֵשׁ שֶׁלּוֹבְשִׁים שְׁתֵּי חֻלְצוֹת. אֲבָל חֻלְצָה בַּיָּד אוֹ עַל הַכָּתֵף הִיא מַשָּׂא.","פֶּרֶק כ״א, הֲלָכָה י׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["בְּאֵיזֶה מֵהֶם מֻתָּר לָצֵאת לָרְחוֹב בִּמְקוֹם שֶׁאֵין עֵרוּב?",["מִשְׁקְפֵי רְאִיָּה","מִשְׁקְפֵי שֶׁמֶשׁ","כַּדּוּר בַּיָּד"],0,"מִשְׁקְפֵי רְאִיָּה מְשַׁמְּשִׁים אֶת הַגּוּף כָּל הַזְּמַן. מִשְׁקְפֵי שֶׁמֶשׁ מוֹרִידִים בַּצֵּל וְנוֹשְׂאִים בַּיָּד, וְכַדּוּר הוּא סְתָם מַשָּׂא.","פֶּרֶק כ״א, הֲלָכָה י״ב","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["קִבַּלְנוּ בְּשַׁבָּת זֵר פְּרָחִים שֶׁעוֹד לֹא נִפְתְּחוּ. אֵיפֹה נָנִיחַ אוֹתוֹ?",["בַּאֲגַרְטָל עִם מַיִם","בָּאֲדָמָה שֶׁבַּגִּנָּה","בַּאֲגַרְטָל בְּלִי מַיִם"],2,"מַיִם יַעַזְרוּ לַפְּרָחִים הַסְּגוּרִים לִפְרֹחַ, וְזֶה כְּמוֹ זוֹרֵעַ. לָכֵן מַנִּיחִים אֶת הַזֵּר בַּאֲגַרְטָל רֵיק.","פֶּרֶק י״ט, הֲלָכָה ט׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["לְאָן מִצְוָה לָרוּץ בְּשַׁבָּת?",["לְאִמּוּן רִיצָה בַּפַּארְק","לִרְאוֹת אֶת הַשָּׂדֶה שֶׁלּוֹ","לַתְּפִלָּה בְּבֵית הַכְּנֶסֶת"],2,"לְצֹרֶךְ מִצְוָה, כְּמוֹ תְּפִלָּה אוֹ שִׁעוּר, מִצְוָה לָרוּץ. רִיצָה לְאִמּוּן הִיא עֻבְדִּין דְּחֹל, וְלָלֶכֶת לַשָּׂדֶה כְּדֵי לְתַכְנֵן עֲבוֹדָה – אָסוּר.","פֶּרֶק כ״ב, הֲלָכוֹת ז׳–ט׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["מָה מֻתָּר לְהַגִּיד לְחָבֵר בְּשַׁבָּת?",["מָחָר אֵלֵךְ לְסַבָּא","מָחָר אֶסַּע לְסַבָּא","מָחָר אֶקְנֶה כַּדּוּר"],0,"הֲלִיכָה מֻתֶּרֶת בְּשַׁבָּת, וְלָכֵן מֻתָּר לְדַבֵּר עָלֶיהָ. נְסִיעָה וּקְנִיָּה אֲסוּרוֹת, וְאָסוּר גַּם לְדַבֵּר עֲלֵיהֶן.","פֶּרֶק כ״ב, הֲלָכָה י׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["אֵיזֶה חֵפֶץ מֻתָּר לְטַלְטֵל בְּשַׁבָּת?",["טֶלֶפוֹן נַיָּד","סֵפֶר תְּהִלִּים","מַטְבְּעוֹת כֶּסֶף"],1,"סְפָרִים מֻתָּר לְטַלְטֵל תָּמִיד. כֶּסֶף הוּא מֻקְצֶה, וְטֶלֶפוֹן הוּא כְּלִי שֶׁעוֹשִׂים בּוֹ מְלָאכָה אֲסוּרָה, וְאָסוּר לְהָזִיז אוֹתוֹ סְתָם.","פֶּרֶק כ״ג, הֲלָכוֹת ד׳, ח׳–ט׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["אֵין מַפְצֵחַ. בְּמָה מֻתָּר לְפַצֵּחַ אֱגוֹז בְּשַׁבָּת?",["בְּאֶבֶן מִן הֶחָצֵר","בְּמַצְלֵמָה כְּבֵדָה","בְּפַטִּישׁ"],2,"פַּטִּישׁ מֻתָּר לְהָזִיז לְצֹרֶךְ מֻתָּר, כְּמוֹ פִּצּוּחַ אֱגוֹז, כְּשֶׁאֵין כְּלִי אַחֵר. אֶבֶן אֵינָהּ רְאוּיָה לְשׁוּם דָּבָר, וּמַצְלֵמָה יְקָרָה – שְׁתֵּיהֶן מֻקְצֶה גַּם לְצֹרֶךְ זֶה.","פֶּרֶק כ״ג, הֲלָכוֹת ג׳–ד׳, ז׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["מָה מֵאֵלֶּה אָסוּר לַעֲשׂוֹת בְּשַׁבָּת?",["לִמְדֹּד אֶת הַגֹּבַהּ","לִקְרֹא סֵפֶר עַל חַיּוֹת","לָשִׁיר זְמִירוֹת"],0,"מְדִידָה הִיא מַעֲשֶׂה שֶׁל חֹל, וְלָכֵן לֹא מוֹדְדִים גֹּבַהּ וְלֹא שׁוֹקְלִים. סֵפֶר שֶׁל חָכְמָה וּזְמִירוֹת – מֻתָּרִים וְאַף מְשַׂמְּחִים אֶת הַשַּׁבָּת.","פֶּרֶק כ״ב, הֲלָכוֹת ו׳, י״ב","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["בְּשַׁבָּת רָאִיתָ מַטְבֵּעַ עַל הָרִצְפָּה בַּמִּסְדְּרוֹן. מָה מֻתָּר לַעֲשׂוֹת?",["לְהָרִים בַּיָּד","לְהַזִּיז בָּרֶגֶל לַצַּד","לְהַכְנִיס לַכִּיס"],1,"כֶּסֶף הוּא מֻקְצֶה, וְאָסוּר לָקַחַת אוֹתוֹ בַּיָּד. אֲבָל מֻתָּר לְהָזִיז אוֹתוֹ בָּרֶגֶל, כְּדֵי שֶׁלֹּא יֵאָבֵד.","פֶּרֶק כ״ג, הֲלָכָה י״ד","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["אַחֲרֵי הַסְּעוּדָה נִשְׁאֲרוּ קְלִפּוֹת עַל הַשֻּׁלְחָן. מָה עוֹשִׂים?",["מַשְׁאִירִים עַד מוֹצָאֵי שַׁבָּת","מְכַסִּים בְּמַגֶּבֶת","מְפַנִּים בַּיָּד לַפַּח"],2,"קְלִפּוֹת הֵן מֻקְצֶה, אֲבָל כְּשֶׁהֵן מַפְרִיעוֹת וּמְלַכְלְכוֹת – חֲכָמִים הִתִּירוּ לְפַנּוֹת אוֹתָן בַּיָּד לַפַּח.","פֶּרֶק כ״ג, הֲלָכָה י״ב","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["אַתָּה עוֹמֵד לִפְנֵי דֶּלֶת סְגוּרָה וְרוֹצֶה שֶׁיִּפְתְּחוּ. מָה מֻתָּר?",["לִדְפֹּק בַּיָּד עַל הַדֶּלֶת","לְנַגֵּן בַּחֲצוֹצְרָה","לִלְחֹץ עַל פַּעֲמוֹן חַשְׁמַלִּי"],0,"דְּפִיקָה עַל הַדֶּלֶת הִיא קוֹל שֶׁאֵינוֹ מוּזִיקָה, וּמֻתֶּרֶת. נְגִינָה אֲסוּרָה, וּפַעֲמוֹן חַשְׁמַלִּי – הַפְעָלַת חַשְׁמַל.","פֶּרֶק כ״ב, הֲלָכָה י״ז","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["לְפִי הָרַב מֶלָמֵד, בְּאֵיזֶה מִשְׂחָק מֻתָּר לִילָדִים לְשַׂחֵק בְּשַׁבָּת?",["צִיּוּר בְּטוּשִׁים","פָּאזֶל","פְּלַסְטֶלִינָה"],1,"לְפִי הָרַב מֶלָמֵד, הָרוֹצִים לְהָקֵל לִילָדִים בְּפָאזֶל – רַשָּׁאִים, אַף שֶׁרֹב פּוֹסְקֵי זְמַנֵּנוּ אוֹסְרִים, וּלְגָדוֹל נָכוֹן לְהַחְמִיר. צִיּוּר הוּא כְּתִיבָה, וּבִפְלַסְטֶלִינָה מוֹרְחִים וְעוֹשִׂים צוּרוֹת – וְהִיא גַּם מֻקְצֶה.","פֶּרֶק כ״ד, הֲלָכָה ז׳; פֶּרֶק י״ח, הֲלָכָה ד׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["עַל מָה מֻתָּר לְיֶלֶד קָטָן לִרְכֹּב בְּשַׁבָּת?",["אוֹפַנַּיִם עִם גַּלְגַּלֵּי עֵזֶר","מְכוֹנִית עַל סוֹלְלוֹת","תְּלַת אוֹפַן"],2,"תְּלַת אוֹפַן הוּא צַעֲצוּעַ שֶׁל קְטַנִּים בִּלְבַד, וְאֵינוֹ עֻבְדִּין דְּחֹל. אוֹפַנַּיִם אֲסוּרִים גַּם עִם גַּלְגַּלֵּי עֵזֶר, וּצְעָצוּעַ עַל סוֹלְלוֹת אָסוּר.","פֶּרֶק כ״ד, הֲלָכוֹת ח׳, י׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["הָאוֹר כָּבָה, וְאָחִיךָ הַקָּטָן רָץ לְהַדְלִיק אוֹתוֹ בִּשְׁבִיל אַבָּא. מָה עוֹשִׂים?",["עוֹצְרִים אוֹתוֹ בַּעֲדִינוּת","אוֹמְרִים לוֹ תּוֹדָה","מַרְאִים לוֹ אֵיפֹה הַמֶּתֶג"],0,"\"לֹא תַעֲשֶׂה כָל מְלָאכָה אַתָּה וּבִנְךָ\" – אָסוּר שֶׁיֶּלֶד יַעֲשֶׂה מְלָאכָה בִּשְׁבִיל הַגְּדוֹלִים, וְחוֹבָה לַעֲצֹר אוֹתוֹ.","פֶּרֶק כ״ד, הֲלָכָה ד׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["מָה מֻתָּר לִילָדִים לַעֲשׂוֹת בְּשַׁבָּת?",["לְנַפֵּחַ בָּלוֹן","לְהָרִיץ מְכוֹנִית קְפִיץ שְׁקֵטָה","לְתוֹפֵף עַל תֹּף צַעֲצוּעַ"],1,"מְכוֹנִית קְפִיץ שֶׁאֵינָהּ מְצַפְצֶפֶת וְאֵינָהּ מְאִירָה – מֻתֶּרֶת. בָּלוֹן לֹא מְנַפְּחִים, שֶׁמָּא יִקְשְׁרוּ, וְתֹף הוּא כְּלִי נְגִינָה.","פֶּרֶק כ״ד, הֲלָכָה ח׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["אֵיפֹה מֻתָּר לִילָדִים קְטַנִּים לְשַׂחֵק בְּכַדּוּר קָטָן?",["עַל הַדֶּשֶׁא בַּגִּנָּה","בְּמִגְרַשׁ כַּדּוּרֶגֶל","עַל רִצְפַּת הַבַּיִת"],2,"כַּדּוּר שֶׁל קְטַנִּים מֻתָּר בַּבַּיִת אוֹ עַל רִצְפָּה מְרֻצֶּפֶת. עַל אֲדָמָה וְדֶשֶׁא – שֶׁמָּא יַשְׁווּ גֻּמּוֹת, וְכַדּוּרֶגֶל אָסוּר לְגַמְרֵי.","פֶּרֶק כ״ד, הֲלָכָה ט׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["אֵיךְ מֻתָּר לִבְנוֹת \"אֹהֶל\" מִשְּׂמִיכָה בְּשַׁבָּת?",["קֹדֶם מוֹתְחִים שְׂמִיכָה, אַחַר כָּךְ כִּסְאוֹת","קֹדֶם כִּסְאוֹת, אַחַר כָּךְ שְׂמִיכָה","קוֹשְׁרִים אֶת הַשְּׂמִיכָה לָעֵץ"],0,"פְּרִישַׂת שְׂמִיכָה עַל כִּסְאוֹת עוֹמְדִים הִיא עֲשִׂיַּת אֹהֶל. כְּשֶׁמּוֹתְחִים אוֹתָהּ קֹדֶם בָּאֲוִיר וּמַכְנִיסִים כִּסְאוֹת תַּחְתֶּיהָ – זֶה שִׁנּוּי, וּמֻתָּר. וּבָעֵץ אָסוּר לְהִשְׁתַּמֵּשׁ.","פֶּרֶק כ״ד, הֲלָכוֹת ז׳–ח׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["יוֹסִי בֶּן שֵׁשׁ חוֹלֶה וְיֵשׁ לוֹ חֹם. מָה מֻתָּר לְאַבָּא לָתֵת לוֹ בְּשַׁבָּת?",["רַק כּוֹס מַיִם","אֶת הַתְּרוּפָה שֶׁלּוֹ","כְּלוּם, עַד מוֹצָאֵי שַׁבָּת"],1,"לְקָטָן מֻתָּר לָתֵת תְּרוּפוֹת בְּשַׁבָּת, גַּם בְּמִחוּשׁ קַל. וּכְשֶׁהוּא חוֹלֶה – וַדַּאי שֶׁדּוֹאֲגִים לוֹ.","פֶּרֶק כ״ד, הֲלָכָה ו׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["נֶהָג עוֹצֵר בְּשַׁבָּת וְשׁוֹאֵל אֵיךְ מַגִּיעִים לְמָקוֹם. מָה עוֹשִׂים?",["מַסְבִּירִים לוֹ אֶת הַדֶּרֶךְ","מַצְבִּיעִים לוֹ עַל הַכִּוּוּן","מִתְנַצְּלִים בְּנִימוּס"],2,"אָסוּר לַעֲזֹר לְמִי שֶׁעוֹבֵר עֲבֵרָה, וְגַם אָסוּר לְדַבֵּר בְּשַׁבָּת עַל מְלָאכוֹת אֲסוּרוֹת. מִתְנַצְּלִים בְּנִימוּס וּמַסְבִּירִים שֶׁבְּשַׁבָּת לֹא מַדְרִיכִים.","פֶּרֶק כ״ו, הֲלָכָה ט׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["בְּשַׁבָּת סָבָא הִרְגִּישׁ פִּתְאוֹם רַע מְאוֹד, וְנִרְאֶה שֶׁהוּא בְּסַכָּנָה. מָה עוֹשִׂים?",["מַזְעִיקִים עֶזְרָה מִיָּד","מְחַכִּים לְמוֹצָאֵי שַׁבָּת","הוֹלְכִים קֹדֶם לִשְׁאֹל רַב"],0,"פִּקּוּחַ נֶפֶשׁ דּוֹחֶה שַׁבָּת – מַזְעִיקִים עֶזְרָה מִיָּד. מִי שֶׁמִּתְעַכֵּב כְּדֵי לִשְׁאֹל רַב בִּשְׁעַת סַכָּנָה – כְּאִלּוּ שׁוֹפֵךְ דָּם.","פֶּרֶק כ״ז, הֲלָכוֹת א׳–ב׳","וָחַי בָּהֶם"],["קִבַּלְתָּ מַכָּה בָּרֶגֶל, וְהִיא מַתְחִילָה לְהִתְנַפֵּחַ. מָה מֻתָּר לַעֲשׂוֹת בְּשַׁבָּת?",["לִמְרֹחַ מִשְׁחָה וּלְהַחֲלִיק","לַחְתֹּךְ תַּחְבֹּשֶׁת בְּמִסְפָּרַיִם","לָשִׂים קֶרַח עַל הַמַּכָּה"],2,"קֶרַח עַל מַכָּה אֵינוֹ \"תְּרוּפָה\", וּמֻתָּר. מְרִיחַת מִשְׁחָה וַחֲלָקָתָהּ – אֲסוּרָה, וְכֵן חִתּוּךְ תַּחְבֹּשֶׁת.","פֶּרֶק כ״ח, הֲלָכוֹת ח׳–ט׳, י״ב","וָחַי בָּהֶם"],["יֵשׁ לְךָ שְׂרִיטָה קְטַנָּה בָּאֶצְבַּע. מָה מֻתָּר?",["לַחְתֹּךְ פְּלַסְטֵר מִגָּלִיל","לְהַדְבִּיק פְּלַסְטֵר מוּכָן","לִכְתֹּב שֵׁם עַל הַפְּלַסְטֵר"],1,"הַדְבָּקַת פְּלַסְטֵר עַל הַגּוּף מֻתֶּרֶת, כִּי הוּא רַק מֵגֵן. חִתּוּךְ – אָסוּר, וְלָכֵן מְכִינִים פְּלַסְטֵרִים חֲתוּכִים לִפְנֵי שַׁבָּת.","פֶּרֶק כ״ח, הֲלָכָה ט׳","וָחַי בָּהֶם"],["אָחִיךָ חוֹלֶה וּמַרְגִּישׁ חַם. מָה מֻתָּר לַעֲשׂוֹת בְּשַׁבָּת?",["לִמְדֹּד חֹם בְּמַדְחֹם רָגִיל","לִשְׁקֹל אוֹתוֹ בְּמִשְׁקָל","לִמְדֹּד אֶת גָּבְהוֹ"],0,"מְדִידוֹת אֲסוּרוֹת בְּשַׁבָּת, אֲבָל לְצֹרֶךְ רְפוּאָה מֻתָּר לִמְדֹּד חֹם בְּמַדְחֹם שֶׁאֵינוֹ חַשְׁמַלִּי.","פֶּרֶק כ״ח, הֲלָכָה י״א","וָחַי בָּהֶם"],["אֵיזוֹ \"צוּרַת הַפֶּתַח\" כְּשֵׁרָה לָעֵרוּב?",["חוּט בְּצַד הָעַמּוּד","חוּט שֶׁשּׁוֹקֵעַ נָמוּךְ מְאוֹד","חוּט מָתוּחַ מֵעַל הָעַמּוּדִים"],2,"צוּרַת הַפֶּתַח הִיא כְּמוֹ דֶּלֶת: הַמַּשְׁקוֹף מֻנָּח מֵעַל הַמְּזוּזוֹת. חוּט בְּצַד הָעַמּוּד, אוֹ חוּט נָמוּךְ מֵעֲשָׂרָה טְפָחִים – פּוֹסְלִים אֶת הָעֵרוּב.","פֶּרֶק כ״ט, הֲלָכוֹת ב׳–ג׳","וָחַי בָּהֶם"],["צָרִיךְ לְהַזְעִיק אַמְבּוּלַנְס לְחוֹלֶה מְסֻכָּן, וְיֵשׁ שָׁם כַּמָּה אֲנָשִׁים. מִי יַזְעִיק?",["יֶלֶד קָטָן","אִישׁ מְבֻגָּר מִיִּשְׂרָאֵל","רַק שָׁכֵן גּוֹי"],1,"אֶת הַהַצָּלָה עוֹשִׂים גְּדוֹלֵי יִשְׂרָאֵל, וְלֹא מְחַפְּשִׂים גּוֹי אוֹ קָטָן – שֶׁמָּא יִתְרַשְּׁלוּ, וְשֶׁמָּא יַחְשְׁבוּ שֶׁאָסוּר לִיהוּדִי לְהַצִּיל.","פֶּרֶק כ״ז, הֲלָכָה ד׳","וָחַי בָּהֶם"],["צָרִיךְ לְהָבִיא אֶת סָבָא לְבֵית חוֹלִים בְּשַׁבָּת, לְטִפּוּל רָגִיל. לְאָן נוֹסְעִים?",["לְבֵית חוֹלִים מְפֹאָר וְרָחוֹק","לְבֵית חוֹלִים בְּעִיר אַחֶרֶת","לְבֵית הַחוֹלִים הַקָּרוֹב"],2,"נוֹסְעִים לְבֵית הַחוֹלִים הַקָּרוֹב, כְּדֵי שֶׁלֹּא לְהוֹסִיף חִלּוּלֵי שַׁבָּת. רַק כְּשֶׁיֵּשׁ סִבָּה רְפוּאִית אֲמִתִּית מֻתָּר לִנְסֹעַ לְרָחוֹק יוֹתֵר.","פֶּרֶק כ״ז, הֲלָכָה ז׳","וָחַי בָּהֶם"],["בְּשַׁבָּת רָאִיתָ תִּיק חָשׁוּד שֶׁמִּישֶׁהוּ הִשְׁאִיר בַּתַּחֲנָה. מָה עוֹשִׂים?",["מִתְרַחֲקִים וּמוֹדִיעִים לִמְבֻגָּר","פּוֹתְחִים וּבוֹדְקִים מָה בִּפְנִים","מְחַכִּים לְמוֹצָאֵי שַׁבָּת"],0,"חֵפֶץ חָשׁוּד הוּא סַכָּנַת נְפָשׁוֹת, וּצְרִיכִים לְהַזְעִיק אֶת הַמִּשְׁטָרָה גַּם בְּשַׁבָּת. יֶלֶד מִתְרַחֵק וּמוֹדִיעַ מִיָּד לִמְבֻגָּר.","פֶּרֶק כ״ז, הֲלָכָה ט״ז","וָחַי בָּהֶם"]],"b":[["חֲכָמִים אָמְרוּ שֶׁכְּנֶסֶת יִשְׂרָאֵל הִיא ״בֶּן הַזּוּג״ שֶׁל הַשַּׁבָּת. מָה הַכַּוָּנָה?",["הַשַּׁבָּת נִבְרְאָה רַק אַחֲרֵי שֶׁיִּשְׂרָאֵל קִבְּלוּ תּוֹרָה","יִשְׂרָאֵל הֵם שֶׁמְּגַלִּים לָעוֹלָם אֶת קְדֻשַּׁת הַשַּׁבָּת","כָּל עַם קִבֵּל יוֹם מְנוּחָה מְיֻחָד מִשֶּׁלּוֹ","יִשְׂרָאֵל עוֹבְדִים קָשֶׁה יוֹתֵר מִכָּל הָעַמִּים"],1,"הַשַּׁבָּת קְדוֹשָׁה מִבְּרִיאַת הָעוֹלָם, אֲבָל עַד שֶׁבָּאוּ יִשְׂרָאֵל לֹא הָיָה מִי שֶׁיְּגַלֶּה אֶת קְדֻשָּׁתָהּ וּבִרְכָתָהּ. לָכֵן הִיא ״אוֹת בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל״.","פֶּרֶק א׳, הֲלָכוֹת ב׳, ד׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["בִּנְיַן הַמִּשְׁכָּן, מְקוֹם הַשְּׁכִינָה, הָיָה מִצְוָה גְּדוֹלָה. לָמָּה בְּכָל זֹאת הִפְסִיקוּ אוֹתוֹ בְּשַׁבָּת?",["כִּי הַבּוֹנִים הָיוּ עֲיֵפִים מְאוֹד וְהָיוּ צְרִיכִים לָנוּחַ","כִּי בְּשַׁבָּת לֹא הָיוּ חֳמָרִים לְבִנְיַן הַמִּשְׁכָּן","כִּי מֹשֶׁה רַבֵּנוּ לֹא הָיָה בַּמַּחֲנֶה בְּשַׁבָּת","כְּדֵי שֶׁלֹּא יִשְׁכְּחוּ אֶת הַמַּטָּרָה הַפְּנִימִית שֶׁל הַמִּשְׁכָּן"],3,"גַּם מְלֶאכֶת קֹדֶשׁ צְרִיכָה נְשָׁמָה. אִלּוּ בָּנוּ בְּלִי הַפְסָקָה, הָיוּ עֲלוּלִים לִשְׁכֹּחַ לָמָּה בּוֹנִים – וְהַמִּשְׁכָּן הָיָה נִשְׁאָר גּוּף בְּלִי נְשָׁמָה. מִכָּאן לָמַדְנוּ אֶת ל״ט הַמְּלָאכוֹת.","פֶּרֶק א׳, הֲלָכָה י׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["עֶרֶב שַׁבָּת. הַתַּבְשִׁיל נִשְׂרַף, וְהַשֻּׁלְחָן עוֹד לֹא עָרוּךְ. מָה דּוֹרֵשׁ כְּבוֹד הַשַּׁבָּת?",["לִשְׁמֹר עַל שָׁלוֹם בַּבַּיִת וְלֹא לִכְעֹס","לְבַטֵּל אֶת הַסְּעוּדָה, כִּי בְּלִי מַטְעַמִּים אֵין עֹנֶג","לְהָעִיר לְמִי שֶׁאָשֵׁם, כְּדֵי שֶׁיִּזָּהֵר בַּשָּׁבוּעַ הַבָּא","לִדְחוֹת אֶת קַבָּלַת הַשַּׁבָּת עַד שֶׁהַכֹּל יִהְיֶה מוּכָן"],0,"כְּבוֹד הַשַּׁבָּת הוּא שֶׁבְּנֵי הַמִּשְׁפָּחָה יִהְיוּ בְּשָׁלוֹם. ״טוֹב אֲרֻחַת יָרָק וְאַהֲבָה שָׁם״ – אֲרוּחָה פְּשׁוּטָה בְּאַהֲבָה טוֹבָה מִסְּעוּדָה מְפֹאֶרֶת עִם רִיב. וְאֶת הַשַּׁבָּת אִי אֶפְשָׁר לִדְחוֹת – הִיא נִכְנֶסֶת בִּזְמַנָּהּ.","פֶּרֶק ב׳, הֲלָכוֹת ב׳, ה׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["בְּיוֹם שִׁשִּׁי מְכַוֵּן אַבָּא שְׁעוֹן שַׁבָּת שֶׁיַּדְלִיק אֶת הָאוֹר בַּלַּיְלָה. הַאִם מֻתָּר?",["אָסוּר, כִּי לְפִי הַהֲלָכָה גַּם הַכֵּלִים צְרִיכִים לִשְׁבֹּת","מֻתָּר, רַק אִם הָאוֹר יִדָּלֵק לִפְנֵי שְׁקִיעַת הַחַמָּה","מֻתָּר, כִּי בְּשַׁבָּת עַצְמָהּ אַבָּא אֵינוֹ עוֹשֶׂה דָּבָר","אָסוּר, אֶלָּא אִם כֵּן יְבַקֵּשׁ מִגּוֹי לְכַוֵּן אוֹתוֹ"],2,"אִסּוּרֵי שַׁבָּת חָלִים עַל מַעֲשִׂים שֶׁאָדָם עוֹשֶׂה בְּשַׁבָּת. הַהֲלָכָה כְּבֵית הִלֵּל: הַכֵּלִים אֵינָם צְרִיכִים לִשְׁבֹּת, וְלָכֵן מֻתָּר לְכַוֵּן בְּעֶרֶב שַׁבָּת שָׁעוֹן שֶׁיִּפְעַל מֵעַצְמוֹ בְּשַׁבָּת.","פֶּרֶק ב׳, הֲלָכָה ט׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["מִשְׁפָּחָה רוֹצָה לָטוּס בְּיוֹם שִׁשִּׁי, וְהַטִּיסָה תִּמָּשֵׁךְ גַּם לְתוֹךְ הַשַּׁבָּת. הַטַּיָּס אֵינוֹ יְהוּדִי. מָה הַדִּין?",["מֻתָּר, כִּי הַטַּיָּס הוּא שֶׁעוֹשֶׂה אֶת הַמְּלָאכָה","אָסוּר, כִּי זוֹ נְסִיעָה שֶׁל חוֹל שֶׁפּוֹגַעַת בַּשַּׁבָּת","מֻתָּר, אִם יְקַבְּלוּ אֶת הַשַּׁבָּת בָּאֲוִיר בִּזְמַנָּהּ","אָסוּר, רַק אִם הַמָּטוֹס שַׁיָּךְ לְחֶבְרָה יְהוּדִית"],1,"אָסוּר לַעֲלוֹת בְּיוֹם שִׁשִּׁי עַל מָטוֹס אוֹ רַכֶּבֶת שֶׁיִּמָּשְׁכוּ בְּשַׁבָּת – גַּם כְּשֶׁהַטַּיָּס אֵינוֹ יְהוּדִי: יוֹצְאִים מִתְּחוּם שַׁבָּת, אֵין שָׁם עֹנֶג שַׁבָּת, וְזוֹ נְסִיעָה שֶׁל חוֹל שֶׁמְּזַלְזֶלֶת בִּכְבוֹד הַשַּׁבָּת.","פֶּרֶק ב׳, הֲלָכָה י״ב","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["אִמָּא כְּבָר הִדְלִיקָה נֵרוֹת וְקִבְּלָה שַׁבָּת, וְאָז רָאֲתָה שֶׁהָאוֹר בַּמִּסְדְּרוֹן כָּבוּי. מָה הִיא יְכוֹלָה לַעֲשׂוֹת?",["לְהַדְלִיק בְּעַצְמָהּ, כִּי עוֹד לֹא שָׁקְעָה הַחַמָּה","לְהַשְׁאִיר חֹשֶׁךְ, כִּי אָסוּר לְבַקֵּשׁ מֵאַף אֶחָד","לְהַדְלִיק בְּעַצְמָהּ, וּלְקַבֵּל אֶת הַשַּׁבָּת שׁוּב אַחַר כָּךְ","לְבַקֵּשׁ מֵאַבָּא, שֶׁעוֹד לֹא קִבֵּל שַׁבָּת, לְהַדְלִיק"],3,"מִי שֶׁקִּבֵּל עָלָיו שַׁבָּת – אָסוּר בִּמְלָאכָה, גַּם לִפְנֵי הַשְּׁקִיעָה. אֲבָל מֻתָּר לוֹ לְבַקֵּשׁ מִיְּהוּדִי שֶׁעוֹד לֹא קִבֵּל שַׁבָּת, כְּמוֹ אַבָּא לִפְנֵי תְּפִלַּת מִנְחָה, שֶׁיַּעֲשֶׂה זֹאת בִּשְׁבִילוֹ.","פֶּרֶק ג׳, הֲלָכָה ד׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["שִׁירָה רוֹצָה לְהִתְפַּלֵּל מִנְחָה בְּעֶרֶב שַׁבָּת, וְגַם לְהַדְלִיק נֵרוֹת. מָה נָכוֹן לְכַתְּחִלָּה?",["לְהַדְלִיק קֹדֶם, וְאַחַר כָּךְ לְהִתְפַּלֵּל מִנְחָה שֶׁל חוֹל","לְהִתְפַּלֵּל מִנְחָה קֹדֶם, וְאַחַר כָּךְ לְהַדְלִיק נֵרוֹת","לְדַלֵּג עַל מִנְחָה, וּלְהִתְפַּלֵּל עַרְבִית פַּעֲמַיִם בַּלַּיְלָה","לְהַדְלִיק קֹדֶם, וּלְהִתְפַּלֵּל מִנְחָה שֶׁל שַׁבָּת בִּמְקוֹמָהּ"],1,"בְּהַדְלָקַת הַנֵּרוֹת הָאִשָּׁה מְקַבֶּלֶת שַׁבָּת – וְאֵיךְ תִּתְפַּלֵּל אַחַר כָּךְ תְּפִלָּה שֶׁל חוֹל? לָכֵן לְכַתְּחִלָּה מִתְפַּלְּלִים מִנְחָה לִפְנֵי הַהַדְלָקָה. וּבְדִיעֲבַד – הַמִּנְהָג הָרוֹוֵחַ שֶׁמֻּתָּר לְהִתְפַּלֵּל גַּם אַחֲרֶיהָ.","פֶּרֶק ג׳, הֲלָכָה ה׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["יוֹם שִׁשִּׁי בַּבֹּקֶר. אֵיזֶה מִנְהָג טוֹב לָאִשָּׁה מוּבָא בַּהֲלָכָה?",["לִקְנוֹת אֶת כָּל צָרְכֵי הַשַּׁבָּת לִפְנֵי תְּפִלַּת שַׁחֲרִית","לְכַבֵּס אֶת בִּגְדֵי הַשַּׁבָּת, כְּתַקָּנַת עֶזְרָא הַסּוֹפֵר","לֶאֱפוֹת חַלּוֹת לִכְבוֹד שַׁבָּת וּלְהַפְרִישׁ מֵהֶן חַלָּה","לְהַתְחִיל לְבַשֵּׁל רַק אַחֲרֵי חֲצוֹת הַיּוֹם"],2,"הָרָמָ״א כָּתַב: מִנְהָג טוֹב לָאִשָּׁה לְהַשְׁכִּים בְּיוֹם שִׁשִּׁי וְלֶאֱפוֹת חַלּוֹת לִכְבוֹד שַׁבָּת, וּלְהַפְרִישׁ מֵהֶן חַלָּה. אֶת הַקְּנִיּוֹת לֹא מַקְדִּימִים לִתְפִלַּת שַׁחֲרִית, עֶזְרָא תִּקֵּן לְכַבֵּס בְּיוֹם חֲמִישִׁי, וּמִנְהָג טוֹב הוּא לְסַיֵּם אֶת הַהֲכָנוֹת עַד חֲצוֹת.","פֶּרֶק ב׳, הֲלָכָה ב׳","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["בְּיוֹם שִׁשִּׁי רָבוּ יוֹסִי וְאָחִיו עַל מִשְׂחָק, וְעַכְשָׁו נִכְנֶסֶת הַשַּׁבָּת. מָה כְּדַאי לָהֶם לַעֲשׂוֹת?",["לְחַכּוֹת לְמוֹצָאֵי שַׁבָּת, וְאָז לְהַמְשִׁיךְ אֶת הַוִּכּוּחַ בְּשֶׁקֶט","לְהַשְׁלִים זֶה עִם זֶה, כִּי הַשַּׁבָּת הִיא יוֹם שֶׁל שָׁלוֹם","לֹא לְדַבֵּר זֶה עִם זֶה כָּל הַשַּׁבָּת, כְּדֵי לֹא לָרִיב","לְסַפֵּר לַהוֹרִים בַּסְּעוּדָה מִי צָדַק וּמִי אָשֵׁם בַּמְּרִיבָה"],1,"צָרִיךְ לְהִזָּהֵר שֶׁלֹּא לִפְגֹּם בִּקְדֻשַּׁת הַשַּׁבָּת בִּמְרִיבוֹת. מִי שֶׁיֵּשׁ לוֹ מְרִיבָה עִם מִישֶׁהוּ – מַשְׁלִים אִתּוֹ בְּשַׁבָּת, וּמִי שֶׁיֵּשׁ בְּלִבּוֹ עַצְבוּת – מִשְׁתַּדֵּל לְהָסִיר אוֹתָהּ בְּשַׁבָּת.","פֶּרֶק א׳, הֲלָכָה ט״ז","הַשַּׁבָּת – מַתָּנָה שֶׁל אַהֲבָה"],["הַמְּנוֹרָה בַּסָּלוֹן דּוֹלֶקֶת עוֹד מֵהַצָּהֳרַיִם, וְעוֹד מְעַט מַדְלִיקִים נֵרוֹת שַׁבָּת. מָה הַמְּהֻדָּר?",["לְכַבּוֹת אוֹתָהּ קֹדֶם, וּלְהַדְלִיק אוֹתָהּ שׁוּב יַחַד עִם הַנֵּרוֹת","לְהַשְׁאִיר אוֹתָהּ, וּלְוַתֵּר עַל הַנֵּרוֹת כִּי כְּבָר יֵשׁ אוֹר","לְכַבּוֹת אוֹתָהּ לְגַמְרֵי, כִּי אוֹר חַשְׁמַל אֵינוֹ לִכְבוֹד שַׁבָּת","לְהַדְלִיק נֵרוֹת בְּלִי בְּרָכָה, כִּי כְּבָר יֵשׁ אוֹר בַּחֶדֶר"],0,"לְכַתְּחִלָּה מְכַבִּים אֶת הַחַשְׁמַל לִפְנֵי הַהַדְלָקָה, וּמַדְלִיקִים אוֹתוֹ שׁוּב יַחַד עִם הַנֵּרוֹת – כָּךְ נִכָּר שֶׁהָאוֹר לִכְבוֹד שַׁבָּת. וּמִן הַדִּין אֶפְשָׁר לְבָרֵךְ גַּם כְּשֶׁהַחַשְׁמַל דּוֹלֵק, כִּי הַנֵּרוֹת מוֹסִיפִים אוֹר.","פֶּרֶק ד׳, הֲלָכָה ה׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["יוֹסֵף, בָּחוּר רַוָּק, מִתְאָרֵחַ לְשַׁבָּת אֵצֶל מִשְׁפָּחָה – אוֹכֵל וְיָשֵׁן אֶצְלָם. הַאִם יַדְלִיק נֵרוֹת?",["כֵּן, כִּי כָּל רַוָּק חַיָּב לְהַדְלִיק בְּעַצְמוֹ תָּמִיד","לֹא, כִּי רַק נָשִׁים נְשׂוּאוֹת חַיָּבוֹת בְּנֵרוֹת שַׁבָּת","לֹא, הוּא יוֹצֵא בְּהַדְלָקַת בַּעֲלַת הַבַּיִת","כֵּן, אֲבָל בְּלִי בְּרָכָה וּבְחֶדֶר נִפְרָד"],2,"כְּמוֹ שֶׁבְּנֵי הַבַּיִת יוֹצְאִים בְּהַדְלָקַת בַּעֲלַת הַבַּיִת, כָּךְ גַּם הָאוֹרֵחַ – וּכְבָר יֵשׁ אוֹר בִּמְקוֹם הַסְּעוּדָה. מִצְוַת הַנֵּרוֹת שַׁיֶּכֶת לְכֻלָּם, גַּם לִגְבָרִים.","פֶּרֶק ד׳, הֲלָכָה ז׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["לָמָּה הַמַּפְטִיר קוֹרֵא קֹדֶם כַּמָּה פְּסוּקִים בַּתּוֹרָה, וְרַק אַחַר כָּךְ אֶת הַהַפְטָרָה?",["כִּי בִּזְמַן הַגְּזֵרָה אָסְרוּ לִקְרֹא רַק בַּנְּבִיאִים","כְּדֵי שֶׁלֹּא יֵרָאֶה שֶׁהַנָּבִיא חָשׁוּב כְּמוֹ הַתּוֹרָה","כְּדֵי לְהַשְׁלִים שִׁבְעָה עוֹלִים, כִּי חָסֵר עוֹלֶה","כִּי אֶת הַהַפְטָרָה אָסוּר לִקְרֹא מִסֵּפֶר מֻדְפָּס"],1,"חֲכָמִים רָצוּ שֶׁיִּהְיֶה בָּרוּר שֶׁהַקְּרִיאָה בַּנָּבִיא אֵינָהּ שְׁקוּלָה לְבַדָּהּ כְּנֶגֶד הַתּוֹרָה. הַגְּזֵרָה הָיְתָה דַּוְקָא עַל הַתּוֹרָה, וְשִׁבְעַת הָעוֹלִים כְּבָר סִיְּמוּ אֶת הַפָּרָשָׁה.","פֶּרֶק ה׳, הֲלָכָה ז׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["לָמָּה תִּקֵּן עֶזְרָא לִקְרֹא בַּתּוֹרָה גַּם בְּמִנְחָה שֶׁל שַׁבָּת?",["כְּדֵי לְהַשְׁלִים אֶת מָה שֶׁלֹּא הִסְפִּיקוּ בַּבֹּקֶר","כְּדֵי לִקְרֹא שׁוּב אֶת הַהַפְטָרָה שֶׁל אוֹתָהּ שַׁבָּת","כִּי בַּבֹּקֶר אֵין מַסְפִּיק אֲנָשִׁים לְכָל הָעוֹלִים","כְּדֵי שֶׁגַּם הָעֲסוּקִים יִשְׁמְעוּ אֶת הַפָּרָשָׁה הַבָּאָה"],3,"בְּמִנְחָה קוֹרְאִים שְׁלֹשָׁה עוֹלִים אֶת תְּחִלַּת הַפָּרָשָׁה הַבָּאָה. מִי שֶׁעָסוּק בַּחֲנוּתוֹ וְלֹא בָּא בְּשֵׁנִי וּבַחֲמִישִׁי – שׁוֹמֵעַ אוֹתָהּ לְפָחוֹת פַּעַם אַחַת, בְּשַׁבָּת, כְּשֶׁכֻּלָּם פְּנוּיִים.","פֶּרֶק ה׳, הֲלָכָה ח׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["דָּנִי לֹא סִיֵּם ״שְׁנַיִם מִקְרָא וְאֶחָד תַּרְגּוּם״ עַד סְעוּדַת שַׁבָּת בַּבֹּקֶר. מָה יַעֲשֶׂה?",["יַשְׁלִים עַד מִנְחָה, וְאִם לֹא – עַד יוֹם שְׁלִישִׁי","הִפְסִיד אֶת הַפָּרָשָׁה הַזֹּאת, וְיַתְחִיל אֶת הַפָּרָשָׁה שֶׁל הַשָּׁבוּעַ הַבָּא","יַשְׁלִים בַּשָּׁנָה הַבָּאָה, כְּשֶׁיַּגִּיעוּ שׁוּב לְאוֹתָהּ פָּרָשָׁה","יִקְרָא אוֹתָהּ פַּעַם אַחַת בְּלִי תַּרְגּוּם, וְדַי בְּכָךְ"],0,"מִי שֶׁלֹּא הִסְפִּיק עַד הַסְּעוּדָה – מַשְׁלִים עַד מִנְחָה, וְאַחַר כָּךְ עַד סוֹף יוֹם שְׁלִישִׁי, כִּי שְׁלֹשֶׁת הַיָּמִים הָרִאשׁוֹנִים קְשׁוּרִים לַשַּׁבָּת שֶׁעָבְרָה. וּבְכָל מִקְרֶה מַשְׁלִימִים עַד שִׂמְחַת תּוֹרָה.","פֶּרֶק ה׳, הֲלָכָה ט׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["בְּלֵיל שַׁבָּת הִתְחִיל מֹשֶׁה בְּטָעוּת אֶת הַבְּרָכָה ״אַתָּה חוֹנֵן״ שֶׁל יְמֵי הַחוֹל. מָה יַעֲשֶׂה?",["יַפְסִיק מִיָּד בְּאֶמְצַע, וְיַתְחִיל אֶת בִּרְכַּת הַשַּׁבָּת","יַמְשִׁיךְ אֶת כָּל בִּרְכוֹת הַחוֹל עַד סוֹף הַתְּפִלָּה","יְסַיֵּם אֶת הַבְּרָכָה, וְאָז יַעֲבֹר לְנֹסַח הַשַּׁבָּת","יַחֲזֹר לִתְחִלַּת הַתְּפִלָּה וְיִתְפַּלֵּל הַכֹּל מֵחָדָשׁ"],2,"מֵעִקַּר הַדִּין אֶפְשָׁר הָיָה לוֹמַר בְּשַׁבָּת גַּם אֶת בִּרְכוֹת הַחוֹל, וְלָכֵן מִי שֶׁהִתְחִיל בְּרָכָה – מְסַיֵּם אוֹתָהּ, וְרַק אָז עוֹבֵר לְנֹסַח הַשַּׁבָּת.","פֶּרֶק ה׳, הֲלָכָה י״א","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["בִּפְנִימִיַּת בָּנוֹת אַחַת הַבָּנוֹת מַדְלִיקָה נֵרוֹת בַּחֲדַר הָאֹכֶל בִּשְׁבִיל כֻּלָּן. מָה עִם שְׁאָר הַבָּנוֹת?",["הָרוֹצוֹת רַשָּׁאִיּוֹת לְהַדְלִיק בַּחֲדָרִים בִּבְרָכָה, אִם מֻתָּר שָׁם","כָּל אַחַת חַיֶּבֶת לְהַדְלִיק בַּחֲדַר הָאֹכֶל, לְיַד הַנֵּרוֹת","אָסוּר לָהֶן לְהַדְלִיק, כִּי רַק נָשִׁים נְשׂוּאוֹת מַדְלִיקוֹת","מַדְלִיקוֹת בַּחֲדָרִים, אֲבָל תָּמִיד בְּלִי בְּרָכָה"],0,"בַּהַדְלָקָה שֶׁבַּחֲדַר הָאֹכֶל כֻּלָּן יוֹצְאוֹת. אֲבָל בָּנוֹת שֶׁרוֹצוֹת לִזְכּוֹת בַּמִּצְוָה רַשָּׁאִיּוֹת לְהַדְלִיק בַּחֲדָרִים בִּבְרָכָה. וְאִם אוֹסְרִים שָׁם לְהַדְלִיק מֵחֲשַׁשׁ שְׂרֵפָה – כֻּלָּן יוֹצְאוֹת בַּהַדְלָקָה שֶׁבַּחֲדַר הָאֹכֶל.","פֶּרֶק ד׳, הֲלָכָה ח׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["בְּשַׁבָּת אַחַת שָׁכְחָה אִשָּׁה לְהַדְלִיק נֵרוֹת, וְהַבַּיִת הָיָה חָשׁוּךְ כָּל הַלַּיְלָה. מָה נָהֲגוּ?",["מֵעַכְשָׁו תַּדְלִיק בְּכָל שַׁבָּת נֵר אֶחָד נוֹסָף","תַּדְלִיק בְּמוֹצָאֵי שַׁבָּת שְׁנֵי נֵרוֹת כְּדֵי לְהַשְׁלִים","תִּתְעַנֶּה בְּיוֹם שֵׁנִי שֶׁאַחֲרֵי הַשַּׁבָּת, לְכַפָּרָה","בַּשַּׁבָּת הַבָּאָה תַּדְלִיק פִּי שְׁנַיִם, וְאַחַר כָּךְ כָּרָגִיל"],0,"נָהֲגוּ שֶׁאִשָּׁה שֶׁשָּׁכְחָה לְהַדְלִיק מוֹסִיפָה מֵאָז נֵר אֶחָד בְּכָל הַשַּׁבָּתוֹת – כְּדֵי לִזְכֹּר אֶת חֲשִׁיבוּת הַמִּצְוָה. וְאִם בְּאוֹתָהּ שַׁבָּת דָּלַק אוֹר חַשְׁמַל, וְלֹא נִתְבַּטֵּל עֹנֶג הַשַּׁבָּת – אֵינָהּ צְרִיכָה לְהוֹסִיף.","פֶּרֶק ד׳, הֲלָכָה ג׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["רִבְקָה שׁוֹאֶלֶת: ״הַאִם גַּם לְבָנוֹת יֵשׁ מִצְוָה לִלְמֹד תּוֹרָה בְּשַׁבָּת?״ מָה עוֹנִים לָהּ?",["כֵּן, הַלִּמּוּד הוּא עֹנֶג שַׁבָּת, וְרָאוּי לִקְבֹּעַ לִמּוּד","לֹא, בְּשַׁבָּת בָּנוֹת עוֹסְקוֹת רַק בַּהֲכָנַת הַסְּעוּדוֹת","כֵּן, וְהֵן חַיָּבוֹת לְהַקְדִּישׁ לַלִּמּוּד אֶת חֲצִי הַשַּׁבָּת","לֹא, כִּי נָשִׁים פְּטוּרוֹת לְגַמְרֵי מִלִּמּוּד הֲלָכָה וֶאֱמוּנָה"],0,"נָשִׁים אֵינָן חַיָּבוֹת לְהַקְדִּישׁ לַלִּמּוּד חֲצִי שַׁבָּת כְּמוֹ הַגְּבָרִים. אֲבָל הַתּוֹרָה מְשַׂמַּחַת גַּם אוֹתָן, וְהֵן חַיָּבוֹת לָדַעַת הֲלָכָה וֶאֱמוּנָה – וְהַשַּׁבָּת, שֶׁבָּהּ נִתְּנָה הַתּוֹרָה, הִיא הַזְּמַן הַמַּתְאִים לִלְמֹד וְלָלֶכֶת לְשִׁעוּר.","פֶּרֶק ה׳, הֲלָכָה ה׳","נֵרוֹת שֶׁל שָׁלוֹם וְיוֹם שֶׁל תּוֹרָה"],["אַבָּא סִיֵּם אֶת בִּרְכַּת הַקִּדּוּשׁ. שְׁמוּאֵל רוֹצֶה לְסַפֵּר מָה לָמַד בַּחֵדֶר. מֵאֵיזֶה רֶגַע מֻתָּר לוֹ לְדַבֵּר?",["אַחֲרֵי שֶׁאַבָּא שָׁתָה מְלֹא לוּגְמָיו מִן הַכּוֹס","מִיָּד כְּשֶׁאַבָּא גּוֹמֵר לוֹמַר אֶת הַבְּרָכָה","רַק אַחֲרֵי שֶׁכֻּלָּם אָכְלוּ כְּבָר מִן הַחַלָּה","גַּם בְּאֶמְצַע הַקִּדּוּשׁ, אִם הוּא מְדַבֵּר בְּשֶׁקֶט"],0,"הַקִּדּוּשׁ נִגְמָר רַק כְּשֶׁהַמְקַדֵּשׁ שׁוֹתֶה ״מְלֹא לוּגְמָיו״. עַד אָז הַשּׁוֹמְעִים שׁוֹתְקִים, וְאַחַר כָּךְ אֶפְשָׁר לְסַפֵּר.","פֶּרֶק ו׳, הֲלָכָה ז׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["אַבָּא שָׁתָה מִכּוֹס הַקִּדּוּשׁ וְרוֹצֶה לִמְזֹג מִמֶּנָּה לַיְלָדִים. מָה יַעֲשֶׂה לִפְנֵי שֶׁהוּא מוֹזֵג?",["יְקַדֵּשׁ שׁוּב עַל כּוֹס חֲדָשָׁה וּמְלֵאָה, בִּשְׁבִיל הַיְּלָדִים","יִשְׁטֹף אֶת הַכּוֹסוֹת הַקְּטַנּוֹת בְּמַיִם חַמִּים","יוֹסִיף מְעַט יַיִן מִן הַבַּקְבּוּק לְתוֹךְ הַכּוֹס","יַשְׁאִיר אֶת הַכּוֹס עַל הַשֻּׁלְחָן לְכַמָּה רְגָעִים"],2,"יַיִן שֶׁשָּׁתוּ מִמֶּנּוּ נִקְרָא ״פָּגוּם״. כְּשֶׁמּוֹסִיפִים לְתוֹכוֹ יַיִן מִן הַבַּקְבּוּק – הוּא נַעֲשֶׂה מְתֻקָּן, וְאֶפְשָׁר לִמְזֹג מִמֶּנּוּ לְכֻלָּם.","פֶּרֶק ו׳, הֲלָכוֹת ו׳–ז׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["אַבָּא שֶׁל יוֹנָתָן שָׁמַע קִדּוּשׁ בְּבֵית הַכְּנֶסֶת, שָׁתָה מְעַט מִיץ וְטָעַם פֵּרוּר עוּגָה. מָה הַדִּין?",["יָצָא, כִּי שָׁמַע אֶת הַקִּדּוּשׁ וְעָנָה ״אָמֵן״ בְּכַוָּנָה","לֹא יָצָא, כִּי לֹא אָכַל כְּזַיִת מְזוֹנוֹת שָׁם","יָצָא, כִּי שָׁתָה מִן הַמִּיץ מִיָּד אַחֲרֵי הַקִּדּוּשׁ","יָצָא, אִם יֹאכַל אֶת הַסְּעוּדָה בַּבַּיִת עַד חֲצוֹת"],1,"צָרִיךְ לְקַדֵּשׁ בִּמְקוֹם סְעוּדָה – לֶאֱכֹל שָׁם לְפָחוֹת כְּזַיִת לֶחֶם אוֹ מְזוֹנוֹת. מִי שֶׁטָּעַם פָּחוֹת – לֹא יָצָא, וִיקַדֵּשׁ שׁוּב בַּבַּיִת לִפְנֵי הַסְּעוּדָה.","פֶּרֶק ו׳, הֲלָכָה י׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["שְׁמוּלִיק בֶּן הָעֶשֶׂר יוֹדֵעַ לְקַדֵּשׁ יָפֶה מְאוֹד. הַאִם הוּא יָכוֹל לְקַדֵּשׁ בִּשְׁבִיל אַבָּא שֶׁלּוֹ?",["כֵּן, אִם הוּא מְקַדֵּשׁ בְּקוֹל רָם וּבְכַוָּנָה שְׁלֵמָה","כֵּן, כִּי בַּקִּדּוּשׁ כֻּלָּם חַיָּבִים בְּאֹפֶן שָׁוֶה","כֵּן, אִם אַבָּא יַחֲזִיק בְּעַצְמוֹ אֶת הַכּוֹס","לֹא, כִּי אַבָּא חַיָּב יוֹתֵר מִמֶּנּוּ – מִן הַתּוֹרָה"],3,"יֶלֶד שֶׁלֹּא הִגִּיעַ לְמִצְווֹת חַיָּב בַּקִּדּוּשׁ רַק מִדִּבְרֵי חֲכָמִים, וְאַבָּא חַיָּב מִן הַתּוֹרָה – וְלָכֵן הַיֶּלֶד אֵינוֹ מוֹצִיא אוֹתוֹ. אֲבָל לְעַצְמוֹ שְׁמוּלִיק יָכוֹל לְקַדֵּשׁ – וְזֶה חִנּוּךְ יָפֶה לְמִצְווֹת.","פֶּרֶק ו׳, הֲלָכָה א׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["לַמִּשְׁפָּחָה יֵשׁ בַּקְבּוּק יַיִן מְשֻׁבָּח אֶחָד וַעֲנָבִים מְיֻחָדִים. לְאֵיזוֹ סְעוּדָה רָאוּי לִשְׁמֹר אוֹתָם?",["לִסְעוּדַת לֵיל שַׁבָּת, כִּי קִדּוּשׁ הַלַּיְלָה חָשׁוּב יוֹתֵר","לִסְעוּדַת הַיּוֹם, כִּי הִיא חֲשׁוּבָה מִסְּעוּדַת הַלַּיְלָה","לִמְלַוֶּה מַלְכָּה, כְּדֵי לְלַוּוֹת אֶת הַשַּׁבָּת בְּכָבוֹד","לִסְעוּדָה שְׁלִישִׁית, כִּי הִיא הַסְּעוּדָה הָאַחֲרוֹנָה"],1,"לְעִנְיַן הַקִּדּוּשׁ – הַלַּיְלָה קוֹדֵם. אֲבָל לְעִנְיַן כְּבוֹד הַשַּׁבָּת – כְּבוֹד הַיּוֹם קוֹדֵם לִכְבוֹד הַלַּיְלָה, וְלָכֵן אֶת הַמַּאֲכָלִים הַטּוֹבִים שׁוֹמְרִים לַסְּעוּדָה הַשְּׁנִיָּה.","פֶּרֶק ז׳, הֲלָכָה ד׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["בִּסְעוּדָה שְׁלִישִׁית אָכַל אַהֲרֹן לֶחֶם, וּבְבִרְכַּת הַמָּזוֹן שָׁכַח ״רְצֵה״. הוּא נִזְכַּר אַחֲרֵי שֶׁהִתְחִיל ״הַטּוֹב וְהַמֵּטִיב״. מָה יַעֲשֶׂה?",["יַחֲזֹר לְרֹאשׁ בִּרְכַּת הַמָּזוֹן, כְּמוֹ בְּכָל סְעוּדַת שַׁבָּת","יֹאמַר עַכְשָׁו אֶת הַבְּרָכָה הַקְּצָרָה ״שֶׁנָּתַן שַׁבָּתוֹת לִמְנוּחָה״","לֹא יַחֲזֹר, כִּי בִּסְעוּדָה שְׁלִישִׁית לֶחֶם אֵינוֹ חוֹבָה","יַחֲזֹר לְבִרְכַּת ״וּבְנֵה יְרוּשָׁלַיִם״ וְיֹאמַר שָׁם ״רְצֵה״"],2,"בִּשְׁתֵּי הַסְּעוּדוֹת הָרִאשׁוֹנוֹת חוֹבָה לֶאֱכֹל לֶחֶם, וּמִי שֶׁשָּׁכַח ״רְצֵה״ וְהִתְחִיל ״הַטּוֹב וְהַמֵּטִיב״ – חוֹזֵר. אֲבָל אֶת הַסְּעוּדָה הַשְּׁלִישִׁית אֶפְשָׁר בְּדִיעֲבַד לְקַיֵּם גַּם בִּמְזוֹנוֹת – וְלָכֵן אֵינוֹ חוֹזֵר.","פֶּרֶק ז׳, הֲלָכָה ו׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["אַבָּא חוֹלֶה וְאֵינוֹ יָכוֹל לְקַדֵּשׁ. אֲחוֹתוֹ שֶׁל דָּנִי, בַּת שֵׁשׁ עֶשְׂרֵה, יוֹדַעַת לְקַדֵּשׁ. הַאִם הִיא יְכוֹלָה לְהוֹצִיא אֶת כָּל הַמִּשְׁפָּחָה?",["לֹא, כִּי נָשִׁים פְּטוּרוֹת מִמִּצְוָה שֶׁהַזְּמַן גְּרָמָהּ","כֵּן, כִּי נָשִׁים חַיָּבוֹת בַּקִּדּוּשׁ בְּדִיּוּק כְּמוֹ גְּבָרִים","כֵּן, אֲבָל רַק אֶת הַנָּשִׁים וְהַיְּלָדִים שֶׁבַּמִּשְׁפָּחָה","לֹא, כִּי רַק מִי שֶׁהִגִּיעַ לְגִיל שְׁלֹשׁ עֶשְׂרֵה מוֹצִיא"],1,"נָשִׁים פְּטוּרוֹת בְּדֶרֶךְ כְּלָל מִמִּצְווֹת עֲשֵׂה שֶׁהַזְּמַן גְּרָמָן – אֲבָל ״זָכוֹר״ וְ״שָׁמוֹר״ נֶאֶמְרוּ בְּדִבּוּר אֶחָד, וּמִי שֶׁחַיָּב בִּשְׁמִירַת שַׁבָּת חַיָּב גַּם בַּקִּדּוּשׁ. לָכֵן בַּת שֶׁהִגִּיעָה לְמִצְווֹת מוֹצִיאָה גַּם גְּבָרִים. נָהֲגוּ שֶׁהָאַבָּא מְקַדֵּשׁ – אֲבָל כְּשֶׁאֵינוֹ יָכוֹל, הִיא מְקַדֶּשֶׁת לְכֻלָּם.","פֶּרֶק ו׳, הֲלָכוֹת א׳, ח׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["אִמָּא הִדְלִיקָה נֵרוֹת וְקִבְּלָה שַׁבָּת, וְהִיא צְמֵאָה מְאוֹד. אַבָּא עוֹד בְּבֵית הַכְּנֶסֶת. מָה הַדִּין?",["מֻתָּר לָהּ לִשְׁתּוֹת מַיִם, כִּי עוֹד לֹא יָצְאוּ הַכּוֹכָבִים","מֻתָּר לָהּ לִשְׁתּוֹת, כִּי הַחִיּוּב חָל רַק אַחֲרֵי עַרְבִית","אָסוּר לָהּ לִשְׁתּוֹת עַד שֶׁתְּקַיֵּם אֶת מִצְוַת הַקִּדּוּשׁ","מֻתָּר לָהּ לִשְׁתּוֹת, רַק אִם עוֹד לֹא שָׁקְעָה הַחַמָּה"],2,"אִסּוּר אֲכִילָה וּשְׁתִיָּה לִפְנֵי הַקִּדּוּשׁ מַתְחִיל בָּרֶגַע שֶׁהַשַּׁבָּת נִכְנֶסֶת אֵצֶל הָאָדָם. אִמָּא קִבְּלָה שַׁבָּת בְּהַדְלָקַת הַנֵּרוֹת – וּמֵאָז אָסוּר לָהּ לִשְׁתּוֹת, אֲפִלּוּ מַיִם, עַד שֶׁתְּקַיֵּם אֶת מִצְוַת הַקִּדּוּשׁ.","פֶּרֶק ו׳, הֲלָכָה ט׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["בַּת מִצְוָה רְגִילָה לְהִתְפַּלֵּל שַׁחֲרִית בְּשַׁבָּת. הַאִם מֻתָּר לָהּ לִשְׁתּוֹת תֵּה לִפְנֵי הַתְּפִלָּה?",["כֵּן, כִּי חוֹבַת הַקִּדּוּשׁ חָלָה רַק אַחֲרֵי הַתְּפִלָּה","לֹא, כִּי אִשָּׁה מִתְחַיֶּבֶת בַּקִּדּוּשׁ מִיָּד כְּשֶׁהִיא קָמָה","לֹא, כִּי בְּשַׁבָּת אָסוּר לִשְׁתּוֹת לִפְנֵי הַתְּפִלָּה בִּכְלָל","כֵּן, אֲבָל רַק אִם תְּקַדֵּשׁ קֹדֶם עַל כּוֹס יַיִן"],0,"גַּם אִשָּׁה שֶׁרְגִילָה לְהִתְפַּלֵּל שַׁחֲרִית – כָּל זְמַן שֶׁלֹּא הִתְפַּלְּלָה, עוֹד לֹא חָלָה עָלֶיהָ חוֹבַת הַקִּדּוּשׁ, כְּמוֹ הַגְּבָרִים. לָכֵן מֻתָּר לָהּ לִשְׁתּוֹת לִפְנֵי הַתְּפִלָּה, וְאִם הִיא צְרִיכָה – גַּם לֶאֱכֹל. אַחֲרֵי הַתְּפִלָּה – אָסוּר לֶאֱכֹל וְלִשְׁתּוֹת עַד הַקִּדּוּשׁ.","פֶּרֶק ו׳, הֲלָכָה ט׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["אֵיזֶה מִשְׁפָּט נָכוֹן לְגַבֵּי בָּנוֹת וְנָשִׁים בִּסְעוּדוֹת הַשַּׁבָּת?",["גַּם הֵן חַיָּבוֹת בְּשָׁלֹשׁ סְעוּדוֹת וּבְלֶחֶם מִשְׁנֶה","הֵן חַיָּבוֹת רַק בִּסְעוּדַת לֵיל שַׁבָּת, עִם הַקִּדּוּשׁ","הֵן פְּטוּרוֹת מִסְּעוּדָה שְׁלִישִׁית, כִּי זְמַנָּהּ אַחַר הַצָּהֳרַיִם","הֵן אוֹכְלוֹת לֶחֶם, אֲבָל אֵינָן צְרִיכוֹת שְׁתֵּי חַלּוֹת"],0,"גַּם נָשִׁים וּבָנוֹת חַיָּבוֹת בְּשָׁלֹשׁ סְעוּדוֹת וּבְלֶחֶם מִשְׁנֶה, כִּי גַּם הֵן הָיוּ בְּנֵס הַמָּן הַכָּפוּל. וְגַם סְעוּדַת מְלַוֶּה מַלְכָּה שַׁיֶּכֶת לִגְבָרִים וּלְנָשִׁים כְּאֶחָד. בְּדֶרֶךְ כְּלָל הֵן יוֹצְאוֹת בִּבְרָכַת הַמְבָרֵךְ עַל שְׁתֵּי הַחַלּוֹת.","פֶּרֶק ז׳, הֲלָכוֹת ב׳–ג׳, ח׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["בְּשַׁבָּת אַחַר הַצָּהֳרַיִם יָשַׁב אָבִי וְנִשְׁנֵשׁ עוּגִיּוֹת וּמִיץ, וְהִנֵּה שָׁקְעָה הַחַמָּה. מָה הַדִּין?",["מַמְשִׁיךְ לְנַשְׁנֵשׁ עַד הַהַבְדָּלָה, כִּי הוּא הִתְחִיל לִפְנֵי הַשְּׁקִיעָה","מַפְסִיק לֶאֱכֹל, כִּי לֹא בֵּרַךְ ״הַמּוֹצִיא״ לִפְנֵי הַשְּׁקִיעָה","מַמְשִׁיךְ, כִּי בַּסְּעוּדָה הַשְּׁלִישִׁית אֵין שׁוּם הַגְבָּלַת זְמַן","מַפְסִיק רַק אֶת הַמִּיץ, אֲבָל הָעוּגִיּוֹת מֻתָּרוֹת עַד הַלַּיְלָה"],1,"מִי שֶׁבֵּרַךְ ״הַמּוֹצִיא״ לִפְנֵי הַשְּׁקִיעָה – קָבַע סְעוּדָה, וּמֻתָּר לוֹ לְהַמְשִׁיךְ גַּם אַחֲרֵי צֵאת הַכּוֹכָבִים. אֲבָל מִי שֶׁאָכַל לִפְנֵי הַשְּׁקִיעָה רַק מְזוֹנוֹת, פֵּרוֹת אוֹ מַשְׁקִים – מַפְסִיק כְּשֶׁהַחַמָּה שׁוֹקַעַת.","פֶּרֶק ז׳, הֲלָכָה ה׳","קִדּוּשׁ וּסְעוּדוֹת שֶׁל עֹנֶג"],["יָצְאוּ הַכּוֹכָבִים. אֵיתָן כְּבָר הִתְפַּלֵּל עַרְבִית וְאָמַר ״אַתָּה חוֹנַנְתָּנוּ״, אֲבָל עוֹד לֹא שָׁמַע הַבְדָּלָה עַל הַכּוֹס. מָה מֻתָּר לוֹ?",["גַּם לֶאֱכֹל, כִּי כְּבָר הִבְדִּיל בַּתְּפִלָּה","שׁוּם דָּבָר, עַד שֶׁיִּשְׁמַע הַבְדָּלָה עַל הַכּוֹס","לֶאֱכֹל, אֲבָל לֹא לְהַדְלִיק אוֹר עַד הַהַבְדָּלָה","לְהַדְלִיק אוֹר, אֲבָל לֹא לֶאֱכֹל עַד הַהַבְדָּלָה"],3,"אַחֲרֵי הַבְדָּלָה בְּדִבּוּר – בַּתְּפִלָּה – מֻתָּר לַעֲשׂוֹת מְלָאכָה. אֲבָל לֶאֱכֹל וְלִשְׁתּוֹת מֻתָּר רַק אַחֲרֵי הַהַבְדָּלָה עַל הַכּוֹס, מִפְּנֵי חֲשִׁיבוּתָהּ.","פֶּרֶק ח׳, הֲלָכָה ח׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["חַיָּל הָיָה בְּמִבְצָע בְּמוֹצָאֵי שַׁבָּת וְלֹא הִבְדִּיל. בְּיוֹם רִאשׁוֹן בַּבֹּקֶר, עוֹד לִפְנֵי שֶׁאָכַל, הוּא חוֹזֵר לַבָּסִיס. מָה יַעֲשֶׂה?",["יַבְדִּיל עַל הַכּוֹס, בְּלִי בְּשָׂמִים וּבְלִי נֵר","יַבְדִּיל עַל הַכּוֹס כָּרָגִיל, עִם כָּל אַרְבַּע הַבְּרָכוֹת","הִפְסִיד, כִּי הַבְדָּלָה אֶפְשָׁר רַק בְּמוֹצָאֵי שַׁבָּת","יְחַכֶּה לְמוֹצָאֵי הַשַּׁבָּת הַבָּאָה וְיַבְדִּיל פַּעֲמַיִם"],0,"מִי שֶׁלֹּא הִבְדִּיל – מַשְׁלִים אַחַר כָּךְ עַל הַכּוֹס. אֲבָל הַבְּשָׂמִים בָּאִים לְהָשִׁיב אֶת הַנֶּפֶשׁ בְּצֵאת הַשַּׁבָּת, וְהַנֵּר – לְזֵכֶר הָאֵשׁ שֶׁל מוֹצָאֵי שַׁבָּת; לָכֵן מְבָרְכִים עֲלֵיהֶם רַק בְּמוֹצָאֵי שַׁבָּת.","פֶּרֶק ח׳, הֲלָכָה ז׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["לָמָּה אָסְרוּ חֲכָמִים לְטַפֵּס עַל עֵץ בְּשַׁבָּת?",["כִּי הַטִּפּוּס עַצְמוֹ הוּא אַחַת מִל״ט הַמְּלָאכוֹת","שֶׁמָּא יִשְׁכַּח וְיִקְטֹף עָנָף מִן הָעֵץ","שֶׁמָּא יִפֹּל וְיִפָּצַע, וְיִצְטָרְכוּ לְחַלֵּל שַׁבָּת","כִּי עֵצִים הֵם מֻקְצֶה, וְאָסוּר לָגַעַת בָּהֶם"],1,"זוֹ אַחַת מִגְּזֵרוֹת חֲכָמִים – ״גָּדֵר״ סְבִיב אִסּוּר תּוֹרָה: מִי שֶׁמְּטַפֵּס עַל עֵץ עָלוּל לִשְׁכֹּחַ וְלִקְטֹף עָנָף.","פֶּרֶק ט׳, הֲלָכָה ד׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["רוֹנִי כּוֹתֵב תָּמִיד בְּיַד יָמִין. הוּא אוֹמֵר: ״בְּשַׁבָּת אֶכְתֹּב בְּיַד שְׂמֹאל, וְזֶה לֹא נֶחְשָׁב״. מָה נָכוֹן?",["מֻתָּר, כִּי בְּיַד שְׂמֹאל זוֹ אֵינָהּ מְלֶאכֶת מַחֲשֶׁבֶת","מֻתָּר, אִם יִכְתֹּב רַק אוֹת אַחַת קְטַנָּה","אָסוּר, כִּי חֲכָמִים גָּזְרוּ גַּם עַל שִׁנּוּי","אָסוּר מִן הַתּוֹרָה, בְּדִיּוּק כְּמוֹ בְּיַד יָמִין"],2,"בְּשִׁנּוּי אֵין אִסּוּר תּוֹרָה, אֲבָל חֲכָמִים אָסְרוּ – כְּדֵי שֶׁלֹּא יָבוֹאוּ לַעֲשׂוֹת כְּדַרְכָּם, וּכְדֵי שֶׁהַשַּׁבָּת תִּהְיֶה שְׁבִיתָה אֲמִתִּית.","פֶּרֶק ט׳, הֲלָכָה ג׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["בֶּחָצֵר יֵשׁ דֶּשֶׁא. הַאִם מֻתָּר לָלֶכֶת עָלָיו בְּשַׁבָּת, אַף שֶׁאוּלַי יֵעָקְרוּ עֲשָׂבִים?",["מֻתָּר, כִּי אֵין מִתְכַּוְּנִים וְאֵין וַדָּאוּת שֶׁיֵּעָקְרוּ","אָסוּר, כִּי כָּל דָּבָר שֶׁאוּלַי יִגְרֹם מְלָאכָה – אָסוּר","מֻתָּר, רַק אִם הוֹלְכִים לְאַט וּבִזְהִירוּת רַבָּה","אָסוּר, כִּי הַדֶּשֶׁא מֻקְצֶה וְאָסוּר לִדְרֹךְ עָלָיו"],0,"זֶה ״דָּבָר שֶׁאֵינוֹ מִתְכַּוֵּן״ – וּמֻתָּר. אֲבָל אִם בָּרוּר שֶׁהַהֲלִיכָה תַּעֲקֹר עֲשָׂבִים – אָסוּר, כְּמוֹ מִי שֶׁסּוֹגֵר דֶּלֶת כְּשֶׁיֵּשׁ צְבִי בַּבַּיִת.","פֶּרֶק ט׳, הֲלָכָה ה׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["שְׂרוֹךְ הַנַּעַל שֶׁל יְהוּדָה נִפְתַּח בְּשַׁבָּת. מָה מֻתָּר לוֹ לַעֲשׂוֹת?",["לִקְשֹׁר קֶשֶׁר כָּפוּל וְחָזָק, שֶׁיַּחֲזִיק כָּל הַשָּׁבוּעַ","שׁוּם קֶשֶׁר, כִּי כָּל קְשִׁירָה אֲסוּרָה מִן הַתּוֹרָה","לִקְשֹׁר עֲנִיבָה רְגִילָה, שֶׁפּוֹתְחִים אוֹתָהּ בְּקַלּוּת","רַק קֶשֶׁר חָזָק, כִּי עֲנִיבָה נִפְתַּחַת מִיָּד"],2,"אָסוּר לִקְשֹׁר קֶשֶׁר שֶׁמִּתְקַיֵּם. עֲנִיבָה רְגִילָה – שֶׁפּוֹתְחִים בְּקַלּוּת – אֵינָהּ מִתְקַיֶּמֶת, וְלָכֵן מֻתָּר לִקְשֹׁר אוֹתָהּ.","פֶּרֶק ט׳, הֲלָכָה ח׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["מוֹצָאֵי שַׁבָּת. שִׁירָה לֹא הִתְפַּלְּלָה עַרְבִית, וְרוֹצָה לְהַדְלִיק אוֹר לִפְנֵי שֶׁאַבָּא מַבְדִּיל. מָה תַּעֲשֶׂה?",["תַּדְלִיק מִיָּד, כִּי הַשַּׁבָּת כְּבָר יָצְאָה בְּצֵאת הַכּוֹכָבִים","תֹּאמַר קֹדֶם ״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל״","תֹּאמַר ״שָׁבוּעַ טוֹב״, וְזֶה מַסְפִּיק כְּדֵי לַעֲשׂוֹת מְלָאכָה","תְּחַכֶּה עַד שֶׁתִּשְׁתֶּה בְּעַצְמָהּ מִכּוֹס הַהַבְדָּלָה"],1,"אַחֲרֵי צֵאת הַשַּׁבָּת אָסוּר לַעֲשׂוֹת מְלָאכָה עַד שֶׁמַּבְדִּילִים בְּדִבּוּר – בַּתְּפִלָּה, אוֹ בַּאֲמִירַת ״בָּרוּךְ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל״. מִי שֶׁלֹּא הִתְפַּלְּלָה עַרְבִית אוֹמֶרֶת אֶת הַמִּשְׁפָּט הַזֶּה, וְאָז מֻתָּר לָהּ לְהַדְלִיק. לֶאֱכֹל – רַק אַחֲרֵי הַהַבְדָּלָה עַל הַכּוֹס.","פֶּרֶק ח׳, הֲלָכוֹת א׳, ח׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["מוֹצָאֵי שַׁבָּת. אַבָּא בַּמִּלּוּאִים, וְאֵין בַּבַּיִת גֶּבֶר. מָה תַּעֲשֶׂה אִמָּא?",["תְּוַתֵּר עַל הַהַבְדָּלָה, כִּי נָשִׁים פְּטוּרוֹת מִמֶּנָּה לְגַמְרֵי","תַּבְדִּיל לְעַצְמָהּ, וּתְבָרֵךְ אֶת כָּל אַרְבַּע הַבְּרָכוֹת","תְּחַכֶּה שֶׁאַבָּא יַחֲזֹר בְּעוֹד שָׁבוּעַ, וְאָז יַבְדִּיל בִּשְׁבִילָהּ","תַּבְדִּיל לְעַצְמָהּ, אֲבָל בְּלִי בִּרְכַּת הַנֵּר וְהַבְּשָׂמִים"],1,"נָשִׁים חַיָּבוֹת בַּהַבְדָּלָה. לְכַתְּחִלָּה הֵן נוֹהֲגוֹת לִשְׁמֹעַ אוֹתָהּ מִגֶּבֶר, כִּי יֵשׁ מִי שֶׁאוֹמֵר שֶׁהֵן פְּטוּרוֹת – אֲבָל כְּשֶׁאֵין גֶּבֶר, חוֹבָה עַל הָאִשָּׁה לְהַבְדִּיל לְעַצְמָהּ וּלְבָרֵךְ אֶת כָּל אַרְבַּע הַבְּרָכוֹת.","פֶּרֶק ח׳, הֲלָכָה א׳","הַבְדָּלָה וּמְלֶאכֶת מַחֲשֶׁבֶת"],["יוֹסֵף רוֹצֶה שֶׁבַּקְבּוּק הַמַּיִם הַקָּרִים לֹא יִהְיֶה קַר כָּל כָּךְ. אֵיפֹה מֻתָּר לְהַנִּיחַ אוֹתוֹ?",["עַל הַפְּלָטָה, וְיַשְׁגִּיחַ שֶׁלֹּא יִתְחַמֵּם יוֹתֵר מִדַּי","בְּמָקוֹם שֶׁגַּם אַחֲרֵי יוֹם שָׁלֵם לֹא יִתְחַמֵּם הַרְבֵּה","לְיַד הַפְּלָטָה, רַק לְכַמָּה דַּקּוֹת וְלֹא יוֹתֵר","בְּשׁוּם מָקוֹם, כִּי כָּל חִמּוּם שֶׁל מַיִם אָסוּר"],1,"חֲכָמִים אָסְרוּ לְהַנִּיחַ מַיִם בְּמָקוֹם שֶׁיְּכוֹלִים לְהַגִּיעַ לְחֹם שֶׁהַיָּד סוֹלֶדֶת בּוֹ – גַּם אִם מַשְׁגִּיחִים, שֶׁמָּא יַסִּיחַ אֶת דַּעְתּוֹ. בְּמָקוֹם שֶׁלֹּא יַגִּיעוּ לְחֹם כָּזֶה – מֻתָּר.","פֶּרֶק י׳, הֲלָכָה ד׳","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["בְּשַׁבָּת בַּבֹּקֶר הַדּוּד הַחַשְׁמַלִּי דּוֹלֵק וּמְחַמֵּם. מָה הַדִּין בִּפְתִיחַת בֶּרֶז הַמַּיִם הַחַמִּים?",["אָסוּר, כִּי נִכְנָסִים לַדּוּד מַיִם קָרִים וּמִתְבַּשְּׁלִים","מֻתָּר, כִּי הַמַּיִם הַחַמִּים הִתְחַמְּמוּ מֵעַצְמָם בְּלִי מַעֲשֶׂה","מֻתָּר, אִם פּוֹתְחִים רַק מְעַט וְלֹא אֶת כָּל הַבֶּרֶז","אָסוּר, רַק אִם הַמַּיִם יוֹצְאִים חַמִּים יוֹתֵר מִן הָרָגִיל"],0,"כָּל עוֹד גּוּף הַחִמּוּם שֶׁבַּדּוּד פּוֹעֵל, הַמַּיִם הַקָּרִים שֶׁנִּכְנָסִים בִּמְקוֹם הַחַמִּים מִתְבַּשְּׁלִים – וּמִי שֶׁפּוֹתֵחַ אֶת הַבֶּרֶז גּוֹרֵם לְבִשּׁוּלָם.","פֶּרֶק י׳, הֲלָכָה כ״ד","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["מֹשֶׁה נוֹהֵג כַּשֻּׁלְחָן עָרוּךְ. הוּא מִתְאָרֵחַ בְּשַׁבָּת אֵצֶל מִשְׁפָּחָה תֵּימָנִית, שֶׁחִמְּמָה מָרָק לְפִי מִנְהָגָהּ. מָה יַעֲשֶׂה?",["לֹא יֹאכַל מִן הַמָּרָק, כִּי לְפִי מִנְהָגוֹ הוּא אָסוּר","יֹאכַל, כִּי הַמְּאָרְחִים חִמְּמוּ אוֹתוֹ כַּהֲלָכָה לְפִי מִנְהָגָם","יְבַקֵּשׁ מִן הַמְּאָרְחִים לְחַמֵּם לוֹ עוֹד צַלַּחַת מָרָק","יֹאכַל רַק אִם יְחַכֶּה שֶׁהַמָּרָק יִתְקָרֵר לְגַמְרֵי"],1,"מִי שֶׁחִמֵּם לְפִי מִנְהָגוֹ – נָהַג כַּהֲלָכָה, וּמֻתָּר לְכָל יְהוּדִי לֶאֱכֹל מִתַּבְשִׁילוֹ. אֲבָל לְבַקֵּשׁ מִמֶּנּוּ לְחַמֵּם בִּשְׁבִילוֹ – אָסוּר, כִּי לְפִי מִנְהַג הַמְּבַקֵּשׁ הַדָּבָר אָסוּר.","פֶּרֶק י׳, הֲלָכָה ו׳","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["דָּוִד הוֹרִיד מִן הַפְּלָטָה סִיר שֶׁל תַּבְשִׁיל מְבֻשָּׁל, וְרוֹצֶה לְהַחְזִיר אוֹתוֹ. אֵיךְ יַעֲשֶׂה כְּדֵי לָצֵאת יְדֵי כָּל הַדֵּעוֹת?",["יַנִּיחַ אֶת הַסִּיר עַל הָרִצְפָּה, וְאַחַר כָּךְ יַחְזִיר אוֹתוֹ","יַחְזִיק אֶת הַסִּיר בְּיָדוֹ עַד שֶׁיַּחְזִיר אוֹתוֹ לַפְּלָטָה","יַחְזִיר אוֹתוֹ רַק אַחֲרֵי שֶׁיִּתְקָרֵר לְגַמְרֵי עַל הַשַּׁיִשׁ","יַעֲבִיר אֶת הַתַּבְשִׁיל לְסִיר נָקִי, וְאוֹתוֹ יַנִּיחַ עַל הַפְּלָטָה"],1,"כְּדֵי שֶׁיִּהְיֶה בָּרוּר שֶׁזּוֹ הַחְזָרָה וְלֹא הַנָּחָה חֲדָשָׁה: מִתְכַּוְּנִים לְהַחְזִיר, לֹא מַנִּיחִים עַל הָרִצְפָּה, וּמַחְזִיקִים בַּיָּד. סִיר שֶׁהִתְקָרֵר, אוֹ סִיר אַחֵר – זוֹ כְּבָר הַנָּחָה חֲדָשָׁה.","פֶּרֶק י׳, הֲלָכָה י״ט","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["אַבָּא פָּתַח אֶת מִכְסֵה הַסִּיר שֶׁעַל הַפְּלָטָה, וְרָאָה שֶׁהַתַּבְשִׁיל עוֹד לֹא מוּכָן. מָה הַדִּין?",["מֻתָּר לִסְגֹּר, כִּי הַסִּיר הָיָה סָגוּר מֵעֶרֶב שַׁבָּת","מֻתָּר לִסְגֹּר, אִם יַנִּיחַ גַּם מַגֶּבֶת עַל הַמִּכְסֶה","אָסוּר לִסְגֹּר, כִּי הַכִּסּוּי מְקָרֵב אֶת בִּשּׁוּלוֹ","מֻתָּר לִסְגֹּר, אִם יַעֲבִיר אוֹתוֹ קֹדֶם לְצַד הַפְּלָטָה"],2,"כָּל זְמַן שֶׁהַתַּבְשִׁיל אֵינוֹ מְבֻשָּׁל כָּל צָרְכּוֹ, כָּל פְּעֻלָּה שֶׁמְּזָרֶזֶת אֶת בִּשּׁוּלוֹ – כְּמוֹ סְגִירַת הַמִּכְסֶה אוֹ מַגֶּבֶת עָלָיו – אֲסוּרָה מִן הַתּוֹרָה.","פֶּרֶק י׳, הֲלָכָה ג׳","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["בְּעֶרֶב שַׁבָּת שָׂמוּ סִיר חַמִּין עַל הַפְּלָטָה. מָה מֻתָּר לַעֲשׂוֹת כְּדֵי לִשְׁמֹר עַל חֻמּוֹ?",["לַעֲטֹף רַק חֵלֶק מִן הַסִּיר בְּמַגֶּבֶת יְבֵשָׁה","לַעֲטֹף אֶת כָּל הַסִּיר בִּשְׂמִיכָה עָבָה, מִכָּל צְדָדָיו","לְהַנִּיחַ עַל הַסִּיר מַגֶּבֶת רְטֻבָּה שֶׁתִּתְיַבֵּשׁ מֵהַחֹם","לַעֲטֹף אֶת כֻּלּוֹ, אִם עוֹשִׂים זֹאת לִפְנֵי שַׁבָּת"],0,"סִיר שֶׁעַל הַפְּלָטָה מְקַבֵּל מִמֶּנָּה חֹם, וְלָכֵן עֲטִיפָה שֶׁל כֻּלּוֹ הִיא הַטְמָנָה אֲסוּרָה – אֲפִלּוּ לִפְנֵי שַׁבָּת. חֵלֶק מִן הַסִּיר – מֻתָּר. וּמַגֶּבֶת רְטֻבָּה – אָסוּר לְיַבֵּשׁ בְּחֹם.","פֶּרֶק י׳, הֲלָכָה כ״ג","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["מֵעֶרֶב שַׁבָּת הֵכִינוּ תַּמְצִית תֵּה נוֹזְלִית. אֵיךְ מְכִינִים מִמֶּנָּה כּוֹס תֵּה בְּשַׁבָּת, בַּדֶּרֶךְ הַמְּהֻדֶּרֶת?",["שׁוֹפְכִים אֶת הַתַּמְצִית לְתוֹךְ הַמֵּיחַם שֶׁעַל הַפְּלָטָה","שָׂמִים תַּמְצִית בַּכּוֹס, וְשׁוֹפְכִים עָלֶיהָ מִכְּלִי שֵׁנִי","מְחַמְּמִים אֶת הַתַּמְצִית עַל הַפְּלָטָה, וְאָז מוֹסִיפִים מַיִם","מְעַרְבְּבִים תַּמְצִית וּמַיִם קָרִים, וּמַנִּיחִים עַל הַמֵּיחַם"],1,"הַתַּמְצִית כְּבָר מְבֻשֶּׁלֶת, וְאֶפְשָׁר לִשְׁפֹּךְ אוֹתָהּ לְמַיִם חַמִּים שֶׁבִּכְלִי שֵׁנִי. הַמְהַדְּרִים שָׂמִים קֹדֶם אֶת הַתַּמְצִית בַּכּוֹס, וְעָלֶיהָ שׁוֹפְכִים אֶת הַמַּיִם – כְּדֵי שֶׁלֹּא יֵרָאֶה שֶׁצּוֹבְעִים אֶת הַמַּיִם. לְתוֹךְ הַמֵּיחַם, שֶׁהוּא כְּלִי רִאשׁוֹן, אָסוּר לִשְׁפֹּךְ; וּמַיִם קָרִים עַל הָאֵשׁ – זֶה בִּשּׁוּל.","פֶּרֶק י׳, הֲלָכָה ח׳; פֶּרֶק י״ב, הֲלָכָה י׳","אֹכֶל חַם וְחַמִּין שֶׁל שַׁבָּת"],["לִפְנֵי סְעוּדַת לֵיל שַׁבָּת אַבָּא מוֹצִיא שְׁקֵדִים מִתּוֹךְ תַּעֲרֹבֶת שֶׁל שְׁקֵדִים וּבוֹטְנִים, כְּדֵי לְהַגִּישׁ אוֹתָם בְּסוֹף הַסְּעוּדָה. מָה הַדִּין?",["אָסוּר, כִּי הֵם יֻגְּשׁוּ רַק אַחֲרֵי כַּמָּה שָׁעוֹת","מֻתָּר, כִּי כָּךְ רְגִילִים לְהָכִין לִפְנֵי סְעוּדָה","מֻתָּר, רַק אִם יוֹצִיא אֶת הַבּוֹטְנִים מִן הַקְּעָרָה","אָסוּר, כִּי מֻתָּר לִבְרֹר רַק בִּשְׁבִיל עַצְמוֹ"],1,"מֻתָּר לְהָכִין אֶת כָּל הַמַּאֲכָלִים סָמוּךְ לִתְחִלַּת הַסְּעוּדָה, גַּם אִם יֻגְּשׁוּ בְּסוֹפָהּ – וּבִשְׁבִיל כָּל הַמְּסֻבִּים. אֲבָל אֶת הַבּוֹטְנִים, שֶׁהֵם הַפְּסֹלֶת כָּאן, אָסוּר לְהוֹצִיא.","פֶּרֶק י״א, הֲלָכָה ו׳","בּוֹרְרִים אֶת הַטּוֹב"],["נֹעַם פָּתַח קֻפְסַת טוּנָה בְּשֶׁמֶן, וְרוֹצֶה לְהַגִּישׁ לַסְּעוּדָה טוּנָה בְּלִי שֶׁמֶן. מָה יַעֲשֶׂה?",["יִשְׁפֹּךְ אֶת הַשֶּׁמֶן לַכִּיּוֹר, וְיַשְׁאִיר אֶת הַטּוּנָה בַּקֻּפְסָה","יוֹצִיא אֶת הַטּוּנָה בְּכַף אֶל צַלַּחַת אַחֶרֶת","יִלְחַץ עַל הַמִּכְסֶה כְּדֵי שֶׁהַשֶּׁמֶן יֵצֵא לְבַד","יְסַנֵּן אֶת הַכֹּל בִּמְסַנֶּנֶת קְטַנָּה, וְיַגִּישׁ מִיָּד"],1,"הַטּוּנָה קְטַנָּה וּמְעֹרֶבֶת בַּשֶּׁמֶן. שְׁפִיכַת הַשֶּׁמֶן הִיא הוֹצָאַת פְּסֹלֶת, וּמְסַנֶּנֶת הִיא כְּלִי בֵּרוּר. כְּשֶׁלּוֹקְחִים אֶת הַטּוּנָה בְּכַף – לוֹקְחִים אֹכֶל מִתּוֹךְ פְּסֹלֶת.","פֶּרֶק י״א, הֲלָכָה י״ג","בּוֹרְרִים אֶת הַטּוֹב"],["לָמָּה מֻתָּר לְפַצֵּחַ אֱגוֹזִים בְּשַׁבָּת, וְזֶה אֵינוֹ נֶחְשָׁב מְלֶאכֶת דָּשׁ?",["כִּי רְגִילִים לְפַצֵּחַ אוֹתָם רַק בִּשְׁעַת הָאֲכִילָה","כִּי הַקְּלִפָּה שֶׁלָּהֶם קָשָׁה מְאוֹד, וְאִי אֶפְשָׁר לְאָכְלָהּ","כִּי מְפַצְּחִים אוֹתָם בַּיָּד, וְלֹא בִּכְלִי מְיֻחָד","כִּי אֱגוֹזִים אֵינָם תְּבוּאָה, וְדָשׁ הוּא רַק בְּחִטָּה"],0,"דָּשׁ הִיא מְלָאכָה שֶׁל שָׂדֶה אוֹ מִפְעָל, כְּשֶׁמּוֹצִיאִים הַרְבֵּה אֹכֶל מִקְּלִפָּתוֹ לִקְרַאת מְכִירָה. אֱגוֹזִים מְפַצְּחִים רַק לִקְרַאת הָאֲכִילָה – וְזוֹ דֶּרֶךְ אֲכִילָה. אֲבָל אֲפוּנָה מִתַּרְמִילִים יְבֵשִׁים – זֶה כְּבָר דָּשׁ.","פֶּרֶק י״א, הֲלָכוֹת י״ז–י״ח","בּוֹרְרִים אֶת הַטּוֹב"],["אַבְקַת ג׳ֶלִי עִם מַיִם הִיא בְּהַתְחָלָה נוֹזֵל. לָמָּה בְּכָל זֹאת אָסוּר לְהָכִין ג׳ֶלִי בְּשַׁבָּת?",["כִּי צְרִיכִים לְהַרְתִּיחַ אֶת הַמַּיִם בִּשְׁבִיל הַג׳ֶלִי","כִּי הַצֶּבַע שֶׁבָּאַבְקָה צוֹבֵעַ אֶת הַמַּיִם","כִּי בַּסּוֹף הוּא מִתְקַשֶּׁה וְנַעֲשֶׂה כְּמוֹ עִסָּה","כִּי אָסוּר לְעַרְבֵּב שׁוּם אַבְקָה בְּמַיִם בְּשַׁבָּת"],2,"הַמְּעָרֵב מַיִם בְּאַבְקַת ג׳ֶלִי עוֹבֵר עַל מְלֶאכֶת לָשׁ, כִּי בַּסּוֹף הַתַּעֲרֹבֶת מִתְקַשָּׁה. צֶבַע בְּמַאֲכָלִים אֵינוֹ אָסוּר, וְקָפֶה אוֹ סֻכָּר בְּמַיִם – מֻתָּרִים.","פֶּרֶק י״ב, הֲלָכוֹת ג׳, ז׳, י׳","בּוֹרְרִים אֶת הַטּוֹב"],["בְּשַׁבָּת חַמָּה רוֹצֶה אֲרִיאֵל לְקָרֵר אֶת הַמַּיִם שֶׁבַּכּוֹס. מָה מֻתָּר?",["לְרַסֵּק קֶרַח בְּיָדָיו כְּדֵי שֶׁיֵּצְאוּ מִמֶּנּוּ מַיִם","לִסְחֹט קֻבִּיַּת קֶרַח לְתוֹךְ הַכּוֹס, טִפָּה אַחַר טִפָּה","לָשִׂים קֻבִּיּוֹת קֶרַח בַּכּוֹס, וְהֵן נָמַסּוֹת מֵעַצְמָן","לִכְתֹּשׁ שֶׁלֶג בְּכַף, וְלִשְׁתּוֹת אֶת הַמַּיִם שֶׁיּוֹצְאִים"],2,"רִסּוּק קֶרַח אוֹ שֶׁלֶג בַּיָּדַיִם כְּדֵי לַעֲשׂוֹת מֵהֶם מַיִם אָסוּר, כִּי הוּא דּוֹמֶה לִסְחִיטַת פֵּרוֹת. כְּשֶׁהַקֶּרַח נָמֵס מֵעַצְמוֹ – אֵין עוֹשִׂים מַעֲשֶׂה, וּמֻתָּר.","פֶּרֶק י״ב, הֲלָכָה י״ב","בּוֹרְרִים אֶת הַטּוֹב"],["שְׁלֹמֹה מֵכִין סָלַט בֵּיצִים לִסְעוּדַת שַׁבָּת. אֵיךְ יַעֲשֶׂה זֹאת?",["יָכִין אוֹתוֹ בַּבֹּקֶר, וְיַשְׁאִיר בַּמְּקָרֵר עַד הַסְּעוּדָה","יְרַסֵּק בְּמַזְלֵג, וִיעַרְבֵּב בְּשִׁנּוּי סָמוּךְ לָאֲכִילָה","יְרַסֵּק אֶת הַבֵּיצִים בְּפוּמְפִּיָּה, כְּדֵי שֶׁיִּהְיֶה חָלָק","יְעַרְבֵּב בְּסִבּוּב מָהִיר, כְּמוֹ שֶׁעוֹשִׂים בִּימֵי הַחֹל"],1,"סָלַט בֵּיצִים נַעֲשֶׂה כְּמוֹ עִסָּה אַחַת, וְלָכֵן מְכִינִים אוֹתוֹ סָמוּךְ לָאֲכִילָה וּמְעַרְבְּבִים בְּשִׁנּוּי. רִסּוּק בְּמַזְלֵג – מֻתָּר, אֲבָל פּוּמְפִּיָּה נוֹעֲדָה לִטְחִינָה.","פֶּרֶק י״ב, הֲלָכוֹת ב׳, ז׳","בּוֹרְרִים אֶת הַטּוֹב"],["נֹעָה מְכִינָה בְּשַׁבָּת כּוֹס מִיץ פֶּטֶל מִתַּרְכִּיז. מָה עָדִיף לְכַתְּחִלָּה?",["לָשִׂים קֹדֶם תַּרְכִּיז, וְעָלָיו לִשְׁפֹּךְ אֶת הַמַּיִם","לָשִׂים קֹדֶם מַיִם, וַעֲלֵיהֶם לְטַפְטֵף אֶת הַתַּרְכִּיז לְאַט","לֹא לְהָכִין כְּלָל, כִּי צְבִיעַת מַשְׁקִים אֲסוּרָה מִן הַתּוֹרָה","לְעַרְבֵּב בְּשִׁנּוּי, בְּקַוִּים יְשָׁרִים, כְּמוֹ בְּעִסָּה רַכָּה"],0,"לְפִי רֹב הַפּוֹסְקִים אֵין אִסּוּר צְבִיעָה בְּמַשְׁקִים, אֲבָל לְכַתְּחִלָּה חוֹשְׁשִׁים לְדַעַת הָאוֹסְרִים. כְּשֶׁשָּׂמִים קֹדֶם אֶת הַתַּרְכִּיז, הַמַּיִם נִבְלָעִים בּוֹ – וְלֹא נִרְאֶה שֶׁצּוֹבְעִים אוֹתָם.","פֶּרֶק י״ב, הֲלָכָה י׳","בּוֹרְרִים אֶת הַטּוֹב"],["אֶלְיָשִׁיב רוֹצֶה לִשְׁתּוֹת בְּשַׁבָּת מִיץ תַּפּוּזִים עִם חֲתִיכוֹת פְּרִי, וְהוּא לֹא אוֹהֵב אֶת הַחֲתִיכוֹת. מֻתָּר לוֹ לְסַנֵּן אוֹתוֹ בִּמְסַנֶּנֶת?",["מֻתָּר, כִּי אֶפְשָׁר לִשְׁתּוֹת אוֹתוֹ גַּם בְּלִי סִנּוּן","אָסוּר, כִּי כָּל סִנּוּן בְּשַׁבָּת הוּא בּוֹרֵר","מֻתָּר, רַק אִם יְסַנֵּן דֶּרֶךְ מַפִּית נְיָר","אָסוּר, אֶלָּא אִם כֵּן הוּא חוֹלֶה וְצָמֵא"],0,"רֹב הָאֲנָשִׁים שׁוֹתִים מִיץ תַּפּוּזִים עִם הַחֲתִיכוֹת. כֵּיוָן שֶׁהוּא רָאוּי לִשְׁתִיָּה גַּם בְּלִי סִנּוּן, הַסִּנּוּן לֹא נֶחְשָׁב מְלָאכָה – וּמֻתָּר.","פֶּרֶק י״א, הֲלָכָה י״א","בּוֹרְרִים אֶת הַטּוֹב"],["בִּסְעוּדַת הַבֹּקֶר שֶׁל שַׁבָּת רוֹצֶה רוֹנִי מַשֶּׁהוּ מָתוֹק עִם קָקָאוֹ. מָה מֻתָּר לוֹ?",["לְעָרֵב קָקָאוֹ וְסֻכָּר בְּתוֹךְ גְּבִינָה לְבָנָה רַכָּה","לָלוּשׁ חֶמְאָה, קָקָאוֹ וְסֻכָּר לְמִמְרָח עָבֶה, בְּשִׁנּוּי","לָלוּשׁ אֱגוֹזִים וְשֻׁמְשְׁמִין עִם דְּבַשׁ לְעִסָּה עָבָה","לְעָרֵב חֶמְאָה וְקָקָאוֹ, אִם אוֹכְלִים אֶת הַמִּמְרָח מִיָּד"],0,"הַמּוֹסִיף קָקָאוֹ וְסֻכָּר לִגְבִינָה – אֵינוֹ מְגַבֵּשׁ אוֹתָם לְגוּשׁ אֶחָד, אֶלָּא רַק מַטְעִים אֶת הַגְּבִינָה, וְזֶה מֻתָּר. אֲבָל חֶמְאָה, קָקָאוֹ וְסֻכָּר נַעֲשִׂים עִסָּה עָבָה, וְאוֹתָהּ אָסוּר לָלוּשׁ אֲפִלּוּ בְּשִׁנּוּי וְלַאֲכִילָה מִיָּד.","פֶּרֶק י״ב, הֲלָכוֹת ה׳–ו׳","בּוֹרְרִים אֶת הַטּוֹב"],["דָּנִי אוֹכֵל דָּג בִּסְעוּדַת שַׁבָּת, וּמַרְגִּישׁ בּוֹ עֲצָמוֹת קְטַנּוֹת. מָה מֻתָּר לוֹ?",["לִבְלֹעַ אֶת הַדָּג עִם הָעֲצָמוֹת, כִּי אָסוּר לִבְרֹר בְּשַׁבָּת","לְהוֹצִיא אֶת הָעֲצָמוֹת בַּיָּד אוֹ בַּמַּזְלֵג תּוֹךְ כְּדֵי אֲכִילָה","לְהוֹצִיא אֶת כָּל הָעֲצָמוֹת, וּלְהַשְׁאִיר אֶת הַדָּג לְמָחָר","לְהַשְׁאִיר אֶת כָּל הַדָּג בַּצַּלַּחַת, כִּי דָּג עִם עֲצָמוֹת אָסוּר"],1,"הָאוֹכֵל דָּג רַשַּׁאי לְהוֹצִיא אֶת הָעֲצָמוֹת תּוֹךְ כְּדֵי אֲכִילָתוֹ, בַּיָּד אוֹ בַּמַּזְלֵג, וְכָךְ גַּם בְּבָשָׂר. וּלְיֶלֶד קָטָן מֻתָּר לְהוֹצִיא אֶת הָעֲצָמוֹת קֹדֶם, וְאַחַר כָּךְ לְהַאֲכִיל אוֹתוֹ.","פֶּרֶק י״א, הֲלָכָה ט׳","בּוֹרְרִים אֶת הַטּוֹב"],["זְבוּב נָפַל לְכוֹס הַמִּיץ שֶׁל יוֹסִי בְּשַׁבָּת. מָה נָכוֹן לַעֲשׂוֹת?",["לְהוֹצִיא אֶת הַזְּבוּב לְבַדּוֹ בִּשְׁתֵּי אֶצְבָּעוֹת, בְּלִי מִיץ","לְהוֹצִיא אוֹתוֹ בְּכַף, יַחַד עִם מְעַט מִן הַמִּיץ","לְסַנֵּן אֶת כָּל הַמִּיץ בִּמְסַנֶּנֶת לְכוֹס אַחֶרֶת וּנְקִיָּה","לְהַשְׁאִיר אֶת הַזְּבוּב בַּכּוֹס עַד מוֹצָאֵי שַׁבָּת"],1,"הוֹצָאַת הַזְּבוּב לְבַדּוֹ הִיא הוֹצָאַת פְּסֹלֶת מִתּוֹךְ אֹכֶל. לָכֵן נָכוֹן לְהוֹצִיא אוֹתוֹ בְּכַף יַחַד עִם מְעַט מִן הַמַּשְׁקֶה, אוֹ לְהַטּוֹת אֶת הַכּוֹס וְלִשְׁפֹּךְ מְעַט מִן הַמִּיץ עִם הַזְּבוּב.","פֶּרֶק י״א, הֲלָכָה ט״ו","בּוֹרְרִים אֶת הַטּוֹב"],["הַמְּעִיל שֶׁל אֵיתָן נִרְטַב בַּגֶּשֶׁם בַּדֶּרֶךְ לְבֵית הַכְּנֶסֶת. מָה יַעֲשֶׂה כְּשֶׁיַּגִּיעַ הַבַּיְתָה?",["יִתְלֶה אוֹתוֹ עַל חֶבֶל הַכְּבִיסָה בַּמִּרְפֶּסֶת, שֶׁיִּתְיַבֵּשׁ","יִסְחֹט אוֹתוֹ בַּעֲדִינוּת מֵעַל הַכִּיּוֹר, וְיִתְלֶה בָּאָרוֹן","יַנִּיחַ אוֹתוֹ צָמוּד לְתַנּוּר הַחִמּוּם, שֶׁיִּתְיַבֵּשׁ מַהֵר","יַנִּיחַ אוֹתוֹ עַל כִּסֵּא אוֹ קוֹלָב, וְלֹא יִסְחֹט"],3,"סְחִיטָה הִיא חֵלֶק מִן הַכִּבּוּס. עַל חֶבֶל כְּבִיסָה לֹא תּוֹלִים, כְּדֵי שֶׁלֹּא יַחְשְׁבוּ שֶׁכִּבֵּס בְּשַׁבָּת. וְיִבּוּשׁ צָמוּד לְתַנּוּר, בְּחֹם גָּדוֹל, הוּא לִבּוּן הַבֶּגֶד – וְאָסוּר.","פֶּרֶק י״ג, הֲלָכָה ג׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["אַחֲרֵי תְּפִלַּת שַׁחֲרִית בְּשַׁבָּת רוֹצֶה אַבָּא לְקַפֵּל אֶת טַלִּיתוֹ. מָה הַדֶּרֶךְ שֶׁרֹב הַפּוֹסְקִים מַתִּירִים?",["לְקַפֵּל בְּדִיּוּק לְפִי הַקְּפָלִים הַמְגֻהָצִים, כְּמוֹ בְּחֹל","לְקַפֵּל אוֹתָהּ, אֲבָל לֹא בְּדִיּוּק לְפִי קְפָלֶיהָ","לְהַשְׁאִיר אוֹתָהּ פְּרוּשָׂה עַל הַסַּפְסָל עַד מוֹצָאֵי שַׁבָּת","לְבַקֵּשׁ מֵחָבֵר שֶׁיַּחֲזִיק צַד אֶחָד, וּלְקַפֵּל יַחַד"],1,"הָאִסּוּר הוּא לְקַפֵּל לְפִי הַקְּפָלִים הַקְּבוּעִים, כִּי זֶה נִרְאֶה כְּתִקּוּן הַבֶּגֶד. קִפּוּל שֶׁאֵינוֹ מְדֻיָּק – מֻתָּר, וְכָךְ שׁוֹמְרִים גַּם עַל כְּבוֹד הַטַּלִּית.","פֶּרֶק י״ג, הֲלָכָה ט׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["לְאוּרִי יֵשׁ עוֹר יָבֵשׁ בַּיָּדַיִם. מָה מֻתָּר לוֹ לִמְרֹחַ בְּשַׁבָּת?",["קְרֶם סָמִיךְ מִן הַשְּׁפוֹפֶרֶת, אִם יִמְרַח רַק מְעַט","מִשְׁחָה עָבָה, אִם יַבְלִיעַ אוֹתָהּ מַהֵר בָּעוֹר","שֶׁמֶן, אוֹ תַּכְשִׁיר נוֹזְלִי שֶׁמִּתְפַּשֵּׁט עַל מִשְׁטָח","קְרֶם סָמִיךְ, אִם יִמְרַח אוֹתוֹ בְּגַב הַיָּד"],2,"מְרִיחַת חֹמֶר סָמִיךְ עַל הָעוֹר הִיא מְמָרֵחַ – גַּם כְּשֶׁרוֹצִים שֶׁיִּבָּלַע, כִּי חֵלֶק נִשְׁאָר וּמַחְלִיק אֶת הָעוֹר. בְּשֶׁמֶן וּבְתַכְשִׁיר נוֹזְלִי – אֵין מְמָרֵחַ.","פֶּרֶק י״ד, הֲלָכָה ה׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["שְׁנֵי אַחִים קְטַנִּים רוֹצִים לִבְנוֹת בַּסָּלוֹן אֹהֶל מִשְּׂמִיכָה וּמִכִּסְאוֹת. אֵיךְ יַעֲשׂוּ?",["יַעֲמִידוּ אֶת הַכִּסְאוֹת, וְאַחַר כָּךְ יִפְרְשׂוּ עֲלֵיהֶם אֶת הַשְּׂמִיכָה","יַחְזִיקוּ קֹדֶם אֶת הַשְּׂמִיכָה בָּאֲוִיר, וְאָז יַכְנִיסוּ כִּסְאוֹת","יִפְרְשׂוּ אֶת הַשְּׂמִיכָה עַל הָרִצְפָּה, וְיָשִׂימוּ עָלֶיהָ כִּסְאוֹת","לֹא יִבְנוּ בִּכְלָל, כִּי כָּל אֹהֶל אָסוּר בְּשַׁבָּת"],1,"חֲכָמִים אָסְרוּ לְהָקִים אֹהֶל זְמַנִּי כְּסֵדֶר הָרָגִיל – קֹדֶם קִירוֹת וְאַחַר כָּךְ גַּג. בְּשִׁנּוּי הַסֵּדֶר – קֹדֶם גַּג בָּאֲוִיר וְאַחַר כָּךְ קִירוֹת – הִתִּירוּ.","פֶּרֶק ט״ו, הֲלָכָה ה׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["הַכַּדּוּר שֶׁל דָּנִי, שֶׁנֻּפַּח כְּבָר פְּעָמִים רַבּוֹת, הִתְרוֹקֵן בְּשַׁבָּת. מָה הַדִּין?",["אָסוּר לְנַפֵּחַ, כִּי זֶה תִּקּוּן שֶׁל כְּלִי","מֻתָּר לְנַפֵּחַ, אֲבָל רַק בַּפֶּה וְלֹא בְּמַשְׁאֵבָה","מֻתָּר לְנַפֵּחַ שׁוּב, גַּם בְּמַשְׁאֵבָה יָדָנִית","מֻתָּר לְנַפֵּחַ, וּמֻתָּר גַּם לְנַפֵּחַ בַּלּוֹן חָדָשׁ"],2,"כַּדּוּר שֶׁכְּבָר נֻפַּח פַּעַם אַחַת הוּא כְּבָר כְּלִי, וְנִפּוּחַ נוֹסָף אֵינוֹ עוֹשֶׂה אוֹתוֹ כְּלִי. בַּלּוֹן – אָסוּר לְנַפֵּחַ, שֶׁמָּא יִקְשְׁרוּ אוֹתוֹ.","פֶּרֶק ט״ו, הֲלָכָה ח׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["בְּאֶמְצַע הַסְּעוּדָה הִתְעַקְּמָה מְעַט כַּפִּית. מָה הַדִּין?",["מֻתָּר לְיַשֵּׁר אוֹתָהּ בַּיָּד, כִּי אֵין צֹרֶךְ בְּפַטִּישׁ","אָסוּר לְיַשֵּׁר, כִּי זוֹ מְלֶאכֶת מַכֶּה בְּפַטִּישׁ","מֻתָּר לְיַשֵּׁר, אִם יַעֲשֶׂה זֹאת לְאַט וּבַעֲדִינוּת","אָסוּר לְהִשְׁתַּמֵּשׁ בָּהּ כְּלָל, עַד מוֹצָאֵי שַׁבָּת"],1,"יִשּׁוּר כְּלִי שֶׁהִתְעַקֵּם הוּא תִּקּוּן שֶׁל כְּלִי – מְלֶאכֶת מַכֶּה בְּפַטִּישׁ, גַּם כְּשֶׁעוֹשִׂים זֹאת בַּיָּד. אֲבָל לְהִשְׁתַּמֵּשׁ בַּכַּפִּית כְּמוֹ שֶׁהִיא – מֻתָּר.","פֶּרֶק ט״ו, הֲלָכָה ח׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["לִכְבוֹד סְעוּדַת שַׁבָּת רוֹצָה רִבְקָה לְסַדֵּר אֶת שְׂעָרָהּ. מָה מֻתָּר לָהּ לַעֲשׂוֹת בְּשַׁבָּת עַצְמָהּ?",["לִקְלֹעַ צַמָּה קְטַנָּה, וּלְפָרֵק אוֹתָהּ רַק בְּמוֹצָאֵי שַׁבָּת","לֶאֱסֹף אֶת הַשֵּׂעָר בְּגוּמִיָּה, בְּלִי לִקְלֹעַ צַמָּה","לַעֲשׂוֹת שְׁבִיל יָשָׁר בָּאֶמְצַע הַשֵּׂעָר בְּמַסְרֵק דַּק","לְרַסֵּס סְפְּרֵי עַל הַתִּסְרֹקֶת, כְּדֵי שֶׁתַּחְזִיק יָפֶה"],1,"חֲכָמִים אָסְרוּ לִקְלֹעַ צַמָּה וּלְפָרֵק אוֹתָהּ, וְאָסוּר לְקַבֵּעַ תִּסְרֹקֶת בִּסְפְּרֵי. שְׁבִיל מֻתָּר לַעֲשׂוֹת רַק בַּיָּדַיִם, כִּי הַמַּסְרֵק תּוֹלֵשׁ שְׂעָרוֹת. לֶאֱסֹף אֶת הַשֵּׂעָר בְּגוּמִיָּה – מֻתָּר, כִּי אֵין בָּזֶה בִּנְיָן.","פֶּרֶק י״ד, הֲלָכָה ג׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["יַעֲלָה רוֹצָה לִמְרֹחַ בְּשַׁבָּת לַכָּה שְׁקוּפָה עַל צִפָּרְנֶיהָ, בְּלִי שׁוּם צֶבַע. מָה הַדִּין?",["מֻתָּר, כִּי לַכָּה שְׁקוּפָה אֵינָהּ מְשַׁנָּה אֶת הַצֶּבַע","מֻתָּר, אִם תָּסִיר אוֹתָהּ מִיָּד בְּמוֹצָאֵי שַׁבָּת","אָסוּר, כִּי גַּם הַבָּרָק נֶחְשָׁב צֶבַע","מֻתָּר, כִּי זֶה טִפּוּל בַּגּוּף וְלֹא בִּכְלִי"],2,"לַכָּה, שְׂפָתוֹן וְצֶבַע סְבִיב הָעֵינַיִם – הֵם צְבִיעָה, וַחֲכָמִים אָסְרוּ גַּם צֶבַע שֶׁאֵינוֹ מִתְקַיֵּם זְמַן רַב. גַּם לַכָּה שְׁקוּפָה אֲסוּרָה, כִּי הַבָּרָק נֶחְשָׁב צֶבַע. לִפְנֵי שַׁבָּת – מֻתָּר וְאַף רָאוּי לְהִתְיַפּוֹת לִכְבוֹדָהּ.","פֶּרֶק י״ד, הֲלָכָה ד׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["שַׁבָּת בַּבֹּקֶר, וְאֵיתָן הוֹלֵךְ לְצַחְצֵחַ שִׁנַּיִם. מָה נָכוֹן לַעֲשׂוֹת לְכַתְּחִלָּה?",["לֹא לְצַחְצֵחַ כְּלָל, כִּי אָסוּר לְהַרְטִיב מִבְרֶשֶׁת","לְצַחְצֵחַ עִם הַרְבֵּה מִשְׁחָה, וְלֹא לִשְׁטֹף אֶת הַמִּבְרֶשֶׁת","לְצַחְצֵחַ בְּמִבְרֶשֶׁת, וּבְלִי מִשְׁחַת שִׁנַּיִם","לְצַחְצֵחַ חָזָק, גַּם כְּשֶׁבָּרוּר שֶׁיֵּצֵא דָּם"],2,"מֻתָּר לְצַחְצֵחַ שִׁנַּיִם בְּשַׁבָּת, וְאַחַר כָּךְ לִשְׁטֹף אֶת הַמִּבְרֶשֶׁת כָּרָגִיל. נָכוֹן שֶׁלֹּא לְהִשְׁתַּמֵּשׁ בְּמִשְׁחַת שִׁנַּיִם, כְּמוֹ שֶׁלֹּא מִשְׁתַּמְּשִׁים בְּסַבּוֹן סָמִיךְ, וּבִשְׁעַת הַצֹּרֶךְ אֶפְשָׁר לְהָקֵל. וְאִם כִּמְעַט וַדַּאי שֶׁיֵּצֵא דָּם – לֹא מְצַחְצְחִים.","פֶּרֶק י״ד, הֲלָכָה ז׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["בִּסְעוּדַת שַׁבָּת פּוֹתְחִים בַּקְבּוּק מַיִם חָדָשׁ, שֶׁיֵּשׁ לוֹ פְּקַק פְּלַסְטִיק. מָה הַדִּין?",["אָסוּר, כִּי בַּפְּתִיחָה הָרִאשׁוֹנָה נַעֲשֶׂה פְּקָק חָדָשׁ","מֻתָּר, וְגַם רֹב הַמַּחְמִירִים מַסְכִּימִים לְכָךְ","מֻתָּר, רַק אִם יַעֲשׂוּ קֹדֶם נֶקֶב בַּפְּקָק","מֻתָּר, רַק אִם יִזְרְקוּ אֶת הַפְּקָק לַפַּח"],1,"פְּקַק פְּלַסְטִיק הָיָה פְּקָק גַּם לִפְנֵי הַפְּתִיחָה הָרִאשׁוֹנָה, וְהַפְּתִיחָה לֹא עוֹשָׂה אוֹתוֹ כְּלִי חָדָשׁ – לָכֵן גַּם רֹב הַמַּחְמִירִים מַתִּירִים, וְכָךְ נוֹהֲגִים. אֶת הַנֶּקֶב וְאֶת הַזְּרִיקָה לַפַּח עוֹשִׂים הַחוֹשְׁשִׁים בִּפְקַק מַתֶּכֶת.","פֶּרֶק ט״ו, הֲלָכָה י״ג","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["בְּשַׁבָּת נִדְבַּק לְנֹעַם בּוֹץ עַל הַנַּעַל בַּדֶּרֶךְ לְבֵית הַכְּנֶסֶת. מָה מֻתָּר לוֹ לַעֲשׂוֹת?",["לְהַכּוֹת נַעַל בְּנַעַל, כְּדֵי שֶׁהַבּוֹץ יִפֹּל","לְגָרֵד אֶת הַבּוֹץ חָזָק בְּמַקֵּל קָטָן","לִשְׁטֹף וּלְשַׁפְשֵׁף אֶת הַנַּעַל בְּמִבְרֶשֶׁת וּבְמַיִם","לִמְרֹחַ מִשְׁחַת נַעֲלַיִם כְּדֵי לְכַסּוֹת אֶת הַכֶּתֶם"],0,"הַמֵּסִיר בּוֹץ וּמְפוֹרֵר אוֹתוֹ עוֹבֵר עַל אִסּוּר טוֹחֵן מִדִּבְרֵי חֲכָמִים. אֲבָל בִּשְׁעַת הַצֹּרֶךְ מֻתָּר לְהָסִיר אוֹתוֹ בְּשִׁנּוּי: לְהַכּוֹת נַעַל בְּנַעַל.","פֶּרֶק י״ג, הֲלָכָה ו׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["בְּשַׁבָּת נִשְׂרַט יְהוֹנָתָן בָּרֶגֶל בְּאֶמְצַע מִשְׂחָק, וְרוֹצִים לְהַדְבִּיק לוֹ פְּלַסְטֶר. מָה נָכוֹן?",["מֻתָּר, כִּי הַדְבָּקָה עַל הַגּוּף אֵינָהּ תְּפִירָה","אָסוּר, כִּי הַדְבָּקָה הִיא תָּמִיד מְלֶאכֶת תּוֹפֵר","מֻתָּר, רַק אִם הַפְּלַסְטֶר נִפְתַּח מֵעֶרֶב שַׁבָּת","אָסוּר, וְצָרִיךְ לְחַכּוֹת עַד מוֹצָאֵי שַׁבָּת"],0,"פְּלַסְטֶר נִדְבָּק לַגּוּף, וְהַדְבָּקָה עַל הַגּוּף לֹא נֶחְשֶׁבֶת תְּפִירָה. לָכֵן בִּשְׁעַת הַצֹּרֶךְ מֻתָּר לְהַדְבִּיק פְּלַסְטֶר בְּשַׁבָּת.","פֶּרֶק י״ג, הֲלָכָה י״ב","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["בְּשַׁבָּת בַּבֹּקֶר גִּלָּה אִיתָן שֶׁאֵין שְׂרוֹכִים בַּנַּעֲלַיִם הַחֲדָשׁוֹת שֶׁלּוֹ. מָה נָכוֹן?",["לֹא נוֹגְעִים בַּנַּעֲלַיִם כְּלָל, כִּי הֵן מֻקְצֶה בְּשַׁבָּת","מַשְׁחִילִים אֶת הַשְּׂרוֹךְ כָּרָגִיל, בְּכָל הַחוֹרִים, וְקוֹשְׁרִים קֶשֶׁר כָּפוּל","מַשְׁחִילִים בְּצוּרָה מְשֻׁנָּה, לְמָשָׁל רַק בַּחוֹרִים הָעֶלְיוֹנִים","מְבַקְּשִׁים מֵאָחִיו הַקָּטָן לְהַשְׁחִיל, כִּי לוֹ מֻתָּר"],2,"כְּדֵי לָצֵאת יְדֵי כָּל הַדֵּעוֹת, מַשְׁחִילִים בְּשַׁבָּת שְׂרוֹךְ לְנַעַל חֲדָשָׁה בְּצוּרָה מְשֻׁנָּה – בְּדִלּוּג עַל חוֹרִים, אוֹ רַק בַּחוֹרִים הָעֶלְיוֹנִים. כָּךְ בְּמוֹצָאֵי שַׁבָּת עוֹד צָרִיךְ לְהַשְׁחִיל כָּרָאוּי, וְאֵין זֶה תִּקּוּן כְּלִי.","פֶּרֶק י״ג, הֲלָכָה ט״ז","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["בִּסְעוּדַת שַׁבָּת מְחַלֵּק אַבָּא עוּגָה לַיְּלָדִים. מָה הַדִּין?",["מֻתָּר לַחְתֹּךְ חֲתִיכוֹת שָׁווֹת, כִּי מְחַתֵּךְ אֵינוֹ חָל עַל מַאֲכָל","אָסוּר לִמְדֹּד, וְלָכֵן חוֹתְכִים חֲתִיכוֹת בְּגָדְלִים שׁוֹנִים בְּכַוָּנָה","אָסוּר לַחְתֹּךְ בְּסַכִּין, וְלָכֵן כָּל אֶחָד שׁוֹבֵר בַּיָּדַיִם","מֻתָּר לַחְתֹּךְ רַק אִם הַחֲתִיכוֹת יוֹצְאוֹת לֹא שָׁווֹת"],0,"מְלֶאכֶת מְחַתֵּךְ הִיא חִתּוּךְ בְּמִדָּה כְּדֵי לִבְנוֹת אוֹ לַעֲשׂוֹת כְּלִי. עַל מַאֲכָלִים הִיא אֵינָהּ חָלָה, וְלָכֵן מֻתָּר לִפְרֹס עוּגָה לַחֲתִיכוֹת שָׁווֹת. אֲבָל קֵיסָם מֵעָנָף קָשֶׁה – אָסוּר לַעֲשׂוֹת.","פֶּרֶק ט״ו, הֲלָכָה י׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["לִפְנֵי הַתְּפִלָּה רָאָה אִיתָן נוֹצָה קְטַנָּה וְאָבָק עַל חֻלְצַת הַשַּׁבָּת שֶׁלּוֹ. מָה מֻתָּר לוֹ?",["לְהָסִיר אֶת הַנּוֹצָה בַּיָּד, אֲבָל לֹא לְנַעֵר אֶת הַחֻלְצָה","לְנַעֵר אֶת הַחֻלְצָה הֵיטֵב, כְּדֵי שֶׁיִּפְּלוּ גַּם הַנּוֹצָה וְהָאָבָק","לְשַׁפְשֵׁף אֶת הָאָבָק בְּמַטְלִית לַחָה, וּלְהַשְׁאִיר אֶת הַנּוֹצָה","לֹא לָגַעַת בְּכָלוּם, כִּי כָּל נִקּוּי שֶׁל בֶּגֶד אָסוּר"],0,"נוֹצָה, חוּט אוֹ סִיבִים שֶׁמֻּנָּחִים עַל הַבֶּגֶד – מֻתָּר לְהָסִיר, כִּי הֵם לֹא דְּבוּקִים בּוֹ. אֲבָל לְנַעֵר אֶת הַבֶּגֶד אוֹ לְשַׁפְשֵׁף אוֹתוֹ מֵאָבָק – אָסוּר. מֻתָּר רַק לְהַכּוֹת עָלָיו בָּאֶצְבַּע.","פֶּרֶק י״ג, הֲלָכָה ח׳","בֶּגֶד, גּוּף וּבַיִת בְּשַׁבָּת"],["בְּשַׁבָּת פָּרְצָה שְׂרֵפָה גְּדוֹלָה בְּבִנְיַן מְגוּרִים. נִרְאֶה שֶׁכָּל הַדַּיָּרִים כְּבָר יָצְאוּ. מָה עוֹשִׂים?",["מְחַכִּים לְמוֹצָאֵי שַׁבָּת, כִּי כֻּלָּם כְּבָר בַּחוּץ","שׁוֹאֲלִים קֹדֶם רַב, וְרַק אַחַר כָּךְ מַזְעִיקִים עֶזְרָה","מַזְעִיקִים מִיָּד, כִּי אוּלַי נִשְׁאַר שָׁם אָדָם","מַצִּילִים רַק אֶת הַחֲפָצִים הַיְּקָרִים, וְלֹא מְכַבִּים"],2,"גַּם סָפֵק סַכָּנָה דּוֹחֶה שַׁבָּת, וּשְׂרֵפָה גְּדוֹלָה בְּבֵית מְגוּרִים נֶחְשֶׁבֶת סָפֵק סַכָּנָה. בְּשָׁעָה כָּזוֹ לֹא שׁוֹאֲלִים רַב – מְמַהֲרִים לְהַצִּיל וּלְהַזְעִיק כַּבָּאִים.","פֶּרֶק ט״ז, הֲלָכָה ז׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["הַשָּׁעוֹן הַמְּעוֹרֵר הַחַשְׁמַלִּי הִתְחִיל לְצַלְצֵל בְּשַׁבָּת בַּבֹּקֶר, וְלֹא מַפְסִיק. מָה יַעֲשֶׂה יְהוּדָה?",["יִלְחַץ עַל הַכַּפְתּוֹר כְּדֵי לְהַפְסִיק אֶת הַצִּלְצוּל","יַעֲטֹף אֶת הַשָּׁעוֹן בִּשְׂמִיכָה, בְּמָקוֹם שֶׁלֹּא יַפְרִיעַ","יוֹצִיא אֶת הַסּוֹלְלָה, כִּי זֶה אֵינוֹ כִּבּוּי מַמָּשׁ","יְבַקֵּשׁ מֵאָחִיו הַקָּטָן לְהַפְסִיק אוֹתוֹ בִּשְׁבִילוֹ"],1,"הַפְסָקַת הַצִּלְצוּל הִיא נִתּוּק שֶׁל פְּעֻלָּה חַשְׁמַלִּית, וַאֲסוּרָה – גַּם בְּיָדֵי אָח קָטָן. אֲבָל מֻתָּר לַעֲטֹף אֶת הַשָּׁעוֹן בִּשְׂמִיכוֹת, כְּדֵי שֶׁהָרַעַשׁ לֹא יַפְרִיעַ.","פֶּרֶק י״ז, הֲלָכָה י״ז","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["אַבָּא וּבָנָיו מִתְאָרְחִים בְּשַׁבָּת בְּמָלוֹן, וּבַכְּנִיסָה יֵשׁ דֶּלֶת חַשְׁמַלִּית. גּוֹי נִגָּשׁ לַדֶּלֶת כְּדֵי לְהִכָּנֵס. מָה מֻתָּר לָהֶם?",["לְהִצְטָרֵף אֵלָיו וּלְהִכָּנֵס יַחַד אִתּוֹ","לְהִתְקָרֵב לַדֶּלֶת לְבַד, כִּי זֶה אֵינוֹ מַעֲשֶׂה","לְהִכָּנֵס רַק אַחֲרֵי יְהוּדִי שֶׁפָּתַח אוֹתָהּ קֹדֶם","לְחַכּוֹת בַּחוּץ, כִּי אָסוּר לְהִכָּנֵס בְּדֶלֶת חַשְׁמַלִּית"],0,"הַגּוֹי פּוֹתֵחַ אֶת הַדֶּלֶת בִּשְׁבִיל עַצְמוֹ, וּמֻתָּר לְהִצְטָרֵף אֵלָיו. אֲבָל הַמִּתְקָרֵב בְּעַצְמוֹ מַפְעִיל אֶת הַדֶּלֶת, וְאַחֲרֵי יְהוּדִי שֶׁחִלֵּל שַׁבָּת – אָסוּר לְהִכָּנֵס.","פֶּרֶק י״ז, הֲלָכָה י״א","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["לְסָבָא יֵשׁ מַכְשִׁיר שְׁמִיעָה חַשְׁמַלִּי. מָה הַדִּין בְּשַׁבָּת?",["אָסוּר לְגַמְרֵי, כְּמוֹ כָּל מַכְשִׁיר חַשְׁמַלִּי בְּשַׁבָּת","מֻתָּר, וְיָכוֹל לְהַגְבִּיר אוֹ לְהַנְמִיךְ לְפִי הַצֹּרֶךְ","מֻתָּר, אִם הִפְעִיל אוֹתוֹ לִפְנֵי שַׁבָּת וְלֹא יְשַׁנֶּה","מֻתָּר, רַק אִם יַדְלִיק אוֹתוֹ מֵחָדָשׁ בְּכָל בֹּקֶר"],2,"מַכְשִׁיר שְׁמִיעָה שֶׁהֻפְעַל לִפְנֵי שַׁבָּת – מֻתָּר, כִּי הַקּוֹל שֶׁל הַמְּדַבְּרִים מַפְעִיל אוֹתוֹ רַק בַּעֲקִיפִין, וְאֵין בּוֹ הַשְׁמָעַת קוֹל לָרַבִּים. אֲבָל לְהַגְבִּיר, לְהַנְמִיךְ אוֹ לְהַדְלִיק – אָסוּר.","פֶּרֶק י״ז, הֲלָכָה ג׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["רוֹפֵא בְּבֵית חוֹלִים צָרִיךְ לִכְתֹּב בְּשַׁבָּת הוֹרָאוֹת לְחוֹלֶה מְסֻכָּן, וְעִכּוּב קָצָר לֹא יְסַכֵּן. מָה עָדִיף?",["יִכְתֹּב כָּרָגִיל, כִּי פִּקּוּחַ נֶפֶשׁ דּוֹחֶה אֶת כָּל הַשַּׁבָּת","יִכְתֹּב בְּשִׁנּוּי, בַּיָּד הַשְּׁנִיָּה אוֹ בְּעֵט שַׁבָּת","יְחַכֶּה עִם הַכְּתִיבָה עַד מוֹצָאֵי שַׁבָּת, אַף שֶׁהַחוֹלֶה מְסֻכָּן","יַקְלִיט אֶת הַהוֹרָאוֹת בַּטֶּלֶפוֹן, כִּי זוֹ לֹא כְּתִיבָה"],1,"כְּשֶׁאֵין סַכָּנָה בָּעִכּוּב, מְמַעֲטִים בָּאִסּוּר: כְּתִיבָה בְּשִׁנּוּי אוֹ בְּעֵט שַׁבָּת אֲסוּרָה רַק מִדִּבְרֵי חֲכָמִים. וְגַם הַקְלָטָה אֲסוּרָה בְּשַׁבָּת.","פֶּרֶק י״ח, הֲלָכוֹת א׳–ב׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["בָּרְחוֹב שֶׁבּוֹ הוֹלֵךְ אֵלִי לְבֵית הַכְּנֶסֶת יֵשׁ מַצְלֵמַת אַבְטָחָה. מָה הַדִּין?",["אָסוּר לַעֲבֹר שָׁם, כִּי הַמַּצְלֵמָה מְצַלֶּמֶת אוֹתוֹ","מֻתָּר רַק אִם יְכַסֶּה אֶת פָּנָיו בְּטַלִּית","מֻתָּר לַעֲבֹר, כִּי הוּא אֵינוֹ רוֹצֶה לְהִצְטַלֵּם","מֻתָּר, אֲבָל רַק אִם יָרוּץ מַהֵר לְיַד הַמַּצְלֵמָה"],2,"הַהוֹלֵךְ לְתֻמּוֹ אֵינוֹ מְעֻנְיָן שֶׁיְּצַלְּמוּ אוֹתוֹ, וְלָכֵן אֵינוֹ אַחְרַאי לְכָךְ שֶׁדְּמוּתוֹ נִקְלֶטֶת. כָּךְ גַּם בְּחַיְשָׁנִים בָּרְחוֹב.","פֶּרֶק י״ז, הֲלָכָה י״ד","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["לְאָבִי יֵשׁ שְׁעוֹן יָד דִּיגִיטָלִי, שֶׁהַמָּסָךְ שֶׁלּוֹ נִדְלָק רַק כְּשֶׁמַּזִּיזִים אֶת הַיָּד. מָה הַדִּין בְּשַׁבָּת?",["מֻתָּר לַעֲנֹד, כִּי הוּא אֵינוֹ לוֹחֵץ עַל שׁוּם כַּפְתּוֹר","אָסוּר לַעֲנֹד, כִּי תְּנוּעַת הַיָּד מַדְלִיקָה אֶת הַמָּסָךְ","מֻתָּר לַעֲנֹד, אִם יַזִּיז אֶת הַיָּד לְאַט מְאוֹד","מֻתָּר, אִם הִדְלִיק אֶת הַשָּׁעוֹן מֵעֶרֶב שַׁבָּת"],1,"שָׁעוֹן שֶׁהַמָּסָךְ שֶׁלּוֹ נִדְלָק מִתְּנוּעַת הַיָּד – כָּל תְּנוּעָה מַפְעִילָה בּוֹ פְּעֻלָּה חַשְׁמַלִּית, וְלָכֵן אָסוּר לַעֲנֹד אוֹתוֹ בְּשַׁבָּת. שָׁעוֹן שֶׁרוֹאִים בּוֹ אֶת הַשָּׁעָה תָּמִיד, בְּלִי שׁוּם פְּעֻלָּה – מֻתָּר.","פֶּרֶק י״ז, הֲלָכָה י״ז","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["בְּיוֹם שִׁשִּׁי כָּתַב נֹעַם עַל כַּף יָדוֹ בְּעֵט ״לְהָבִיא סִדּוּר״. בְּשַׁבָּת הוּא רוֹצֶה לִטֹּל יָדַיִם לַסְּעוּדָה. מָה הַדִּין?",["אָסוּר לוֹ לִשְׁטֹף, כִּי הַמַּיִם יִמְחֲקוּ אֶת הָאוֹתִיּוֹת","נוֹטֵל יָדַיִם וּמְנַגֵּב כְּדַרְכּוֹ, כִּי אֵינוֹ מִתְכַּוֵּן לִמְחֹק","נוֹטֵל רַק יָד אַחַת, וְאֶת הַיָּד הַכְּתוּבָה מְכַסֶּה","מְשַׁפְשֵׁף בְּסַבּוֹן חָזָק עַד שֶׁהָאוֹתִיּוֹת יִמָּחֲקוּ לְגַמְרֵי"],1,"מִי שֶׁכָּתַב עַל יָדוֹ בְּעֵט – רַשַּׁאי לִשְׁטֹף אֶת יָדוֹ וּלְנַגֵּב אוֹתָהּ כְּדַרְכּוֹ, כִּי בְּדֶרֶךְ כְּלָל הָאוֹתִיּוֹת אֵינָן נִמְחָקוֹת בִּשְׁטִיפָה וְנִגּוּב שֶׁל פַּעַם אַחַת. וּמִי שֶׁרוֹצֶה לִמְחֹק – שׁוֹטֵף וּמְנַגֵּב בְּנַחַת.","פֶּרֶק י״ח, הֲלָכָה ג׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["שַׁבָּת בַּבֹּקֶר, וְהַנַּעֲלַיִם שֶׁל אִיתָן מְאֻבָּקוֹת וְלֹא מַבְרִיקוֹת. מָה מֻתָּר לוֹ לַעֲשׂוֹת?",["לְהָסִיר אֶת הָאָבָק בַּיָּד אוֹ בְּמַטְלִית, בְּלִי לְהַבְרִיק","לְמָרֵחַ מְעַט מִשְׁחָה וּלְהַבְרִיק אוֹתָן בְּמַטְלִית רַכָּה","לְשַׁפְשֵׁף בְּמִבְרֶשֶׁת יְבֵשָׁה, כִּי אֵין בָּזֶה מִשְׁחָה","לִשְׁטֹף אוֹתָן בְּמַיִם וְסַבּוֹן כְּדֵי שֶׁיִּהְיוּ נְקִיּוֹת"],0,"אָבָק עַל נַעֲלֵי עוֹר – מֻתָּר לְהָסִיר בַּיָּד אוֹ בְּמַטְלִית, כִּי הוּא רַק מֻנָּח עֲלֵיהֶן. אֲבָל אָסוּר לְצַחְצֵחַ בְּמִשְׁחָה, וְגַם בְּלִי מִשְׁחָה אָסוּר לְשַׁפְשֵׁף בְּמִבְרֶשֶׁת אוֹ בְּמַטְלִית כְּדֵי לְהַבְרִיק.","פֶּרֶק י״ח, הֲלָכָה ו׳; פֶּרֶק י״ג, הֲלָכָה ו׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["יוֹם קַיִץ חַם בְּשַׁבָּת, וְהַמַּזְגָן פּוֹעֵל מֵעֶרֶב שַׁבָּת. מֹשֶׁה רוֹצֶה לְהוֹרִיד אֶת הַטֶּמְפֶּרָטוּרָה בַּשַּׁלָּט. מָה הַדִּין?",["מֻתָּר, כִּי הוּא לֹא נוֹגֵעַ בַּמַּזְגָן עַצְמוֹ אֶלָּא בַּשַּׁלָּט","אָסוּר, כִּי הַלְּחִיצָה כּוֹתֶבֶת מִסְפָּר עַל הַצָּג וּמַפְעִילָה חַשְׁמַל","מֻתָּר, כִּי הַמַּזְגָן כְּבָר דּוֹלֵק וְהוּא רַק מְקָרֵר יוֹתֵר","אָסוּר רַק לְהַדְלִיק, אֲבָל לְשַׁנּוֹת מַעֲלוֹת מֻתָּר תָּמִיד"],1,"כְּמוֹ שֶׁאָסוּר לְהַפְעִיל מַכְשִׁיר בְּכַפְתּוֹר, כָּךְ אָסוּר בְּשַׁלָּט. וְשִׁנּוּי מַעֲלוֹת בִּלְחָצָנִים שֶׁכּוֹתְבִים אֶת הַמִּסְפָּר עַל צָג – אָסוּר מִשּׁוּם ״כּוֹתֵב״, וְגַם מִפְּנֵי שֶׁכָּל לְחִיצָה מְחוֹלֶלֶת מִיָּד פְּעֻלָּה חַשְׁמַלִּית.","פֶּרֶק י״ז, הֲלָכָה ז׳","אוֹר, אֵשׁ וְאוֹתִיּוֹת בְּשַׁבָּת"],["תַּפּוּחִים שֶׁנָּשְׁרוּ לִפְנֵי שַׁבָּת מְפֻזָּרִים בְּכָל הֶחָצֵר, אֶחָד כָּאן וְאֶחָד שָׁם. מָה מֻתָּר לְאֵלִיָּהוּ לַעֲשׂוֹת?",["מֻתָּר לֶאֱסֹף אֶת כֻּלָּם לְסַל, כִּי הֵם כְּבָר תְּלוּשִׁים","אָסוּר לֶאֱסֹף לְסַל, אֲבָל מֻתָּר לְהָרִים מְעַט וְלֶאֱכֹל","אָסוּר לָגַעַת בָּהֶם, כִּי כָּל פְּרִי שֶׁנָּפַל הוּא מֻקְצֶה","מֻתָּר לֶאֱסֹף לְסַל רַק אִם יֹאכְלוּ אוֹתָם בְּשַׁבָּת"],1,"אִסּוּף פֵּרוֹת מְפֻזָּרִים בֶּחָצֵר נִרְאֶה כְּמַעֲשֶׂה שֶׁל חֹל, וְלָכֵן אָסוּר. לְהָרִים מְעַט וְלֶאֱכֹל – מֻתָּר. בְּתוֹךְ הַבַּיִת מֻתָּר גַּם לֶאֱסֹף.","פֶּרֶק י״ט, הֲלָכָה י״א","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["לָמָּה אָסוּר לָצֵאת בְּמִשְׁקְפֵי שֶׁמֶשׁ לִרְחוֹב שֶׁאֵין בּוֹ עֵרוּב, וּבְמִשְׁקְפֵי רְאִיָּה מֻתָּר?",["כִּי הֵם יְקָרִים, וְלָכֵן הֵם מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס","כִּי מִשְׁקָפַיִם מֻתָּרִים רַק לְמִי שֶׁאֵינוֹ רוֹאֶה בְּלִי מִשְׁקָפַיִם","כִּי הָעֲדָשׁוֹת הַכֵּהוֹת נֶחְשָׁבוֹת מַשָּׂא נוֹסָף עַל הָעֵינַיִם","כִּי בַּצֵּל הוּא עָלוּל לְהוֹרִיד אוֹתָם וּלְטַלְטֵל בַּיָּד"],3,"מַה שֶּׁמְּשַׁמֵּשׁ אֶת הַגּוּף טָפֵל לוֹ. אֶת מִשְׁקְפֵי הַשֶּׁמֶשׁ מוֹרִידִים כְּשֶׁמַּגִּיעִים לַצֵּל, וְיֵשׁ חֲשָׁשׁ שֶׁיִּשָּׂא אוֹתָם בַּיָּד אוֹ בַּכִּיס.","פֶּרֶק כ״א, הֲלָכָה י״ב","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["יַתּוּשׁ נָחַת עַל זְרוֹעוֹ שֶׁל יוֹנָתָן בְּשַׁבָּת. מָה מֻתָּר לוֹ לַעֲשׂוֹת?",["מֻתָּר לְהַרְחִיקוֹ מֵהָעוֹר, וְאָסוּר לִמְעֹךְ אוֹתוֹ","מֻתָּר לְהָרְגוֹ, כִּי הוּא מַזִּיק וְעוֹקֵץ","אָסוּר לָגַעַת בּוֹ כְּלָל, כִּי זוֹ צֵידָה","מֻתָּר לְהָרְגוֹ רַק אִם כְּבָר עָקַץ פַּעַם"],0,"עֲקִיצַת יַתּוּשׁ אֵינָהּ מְסֻכֶּנֶת, וְלָכֵן אָסוּר לְהָרְגוֹ. כְּדֵי לְהָסִיר צַעַר הִתִּירוּ לְהַרְחִיק אוֹתוֹ מִן הָעוֹר, וּבִלְבַד שֶׁלֹּא יִמְעַךְ אוֹתוֹ.","פֶּרֶק כ׳, הֲלָכָה י׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["אֵין עֵרוּב. יוֹסֵף עוֹמֵד בַּבַּיִת, וּמוֹשִׁיט סֵפֶר דֶּרֶךְ הַחַלּוֹן לְחָבֵר שֶׁעוֹמֵד בָּרְחוֹב. מָה הַדִּין?",["מֻתָּר, כִּי אַף אֶחָד לֹא עָשָׂה מְלָאכָה שְׁלֵמָה","אָסוּר מִן הַתּוֹרָה, כְּאִלּוּ יָצָא בְּעַצְמוֹ עִם הַסֵּפֶר","אָסוּר מִדִּבְרֵי חֲכָמִים, אַף שֶׁכָּל אֶחָד עָשָׂה רַק חֵלֶק","מֻתָּר, אִם הֶחָבֵר יַחְזִיר אֶת הַסֵּפֶר לִפְנֵי צֵאת הַשַּׁבָּת"],2,"יוֹסֵף עָקַר וְהֶעֱבִיר, וְהֶחָבֵר הִנִּיחַ – וְלָכֵן אֵין כָּאן אִסּוּר תּוֹרָה. אֲבָל חֲכָמִים אָסְרוּ, שֶׁלֹּא יָבוֹאוּ לְזַלְזֵל בִּמְלֶאכֶת הוֹצָאָה.","פֶּרֶק כ״א, הֲלָכָה ה׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["מֹשֶׁה מִתְאָרֵחַ בְּשַׁבָּת בְּיִשּׁוּב שֶׁאֵין בּוֹ עֵרוּב, וְרוֹצֶה לִנְעֹל אֶת הַדֶּלֶת כְּשֶׁהוּא יוֹצֵא לְבֵית הַכְּנֶסֶת. מָה יַעֲשֶׂה?",["יַחְזִיק אֶת הַמַּפְתֵּחַ בְּכִיס הַמְּעִיל, כִּי הַכִּיס טָפֵל לַבֶּגֶד","יַשְׁאִיר אֶת הַדֶּלֶת פְּתוּחָה, כִּי אֵין שׁוּם עֵצָה אַחֶרֶת","יִקְשֹׁר אֶת הַמַּפְתֵּחַ עַל שְׂרוֹךְ, כְּאַבְזָם שֶׁל חֲגוֹרָה","יִתְלֶה אֶת הַמַּפְתֵּחַ עַל צַוָּארוֹ כְּמוֹ קִשּׁוּט"],2,"הַכִּיס טָפֵל לַבֶּגֶד, אֲבָל הַמַּפְתֵּחַ שֶׁבְּתוֹכוֹ הוּא מַשָּׂא. כְּשֶׁהַמַּפְתֵּחַ מְשַׁמֵּשׁ אַבְזָם בַּחֲגוֹרָה – הוּא חֵלֶק מִן הַלְּבוּשׁ.","פֶּרֶק כ״א, הֲלָכָה ט״ו","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["בְּשַׁבָּת נָפַל עָצִיץ, וְחֵלֶק מִן הָאֲדָמָה שֶׁבּוֹ נִשְׁפַּךְ עַל הָרִצְפָּה. מָה נָכוֹן?",["מַחֲזִירִים אֶת הָאֲדָמָה בַּיָּד, כְּדֵי שֶׁהַצֶּמַח לֹא יָמוּת","מַחֲזִירִים בְּכַף, כִּי כָּךְ זֶה בְּשִׁנּוּי וּמֻתָּר","מַחֲזִירִים רַק אִם זֶה עָצִיץ שֶׁאֵין בּוֹ נֶקֶב","לֹא מַחֲזִירִים, כִּי זֶה מֵיטִיב עִם הַצֶּמַח וְהָאֲדָמָה מֻקְצֶה"],3,"הַחְזָרַת הָאֲדָמָה עוֹזֶרֶת לַצֶּמַח, וְזֶה כְּמוֹ חוֹרֵשׁ וְזוֹרֵעַ. וְחוּץ מִזֶּה הָאֲדָמָה עַצְמָהּ מֻקְצֶה, וְאָסוּר לְטַלְטֵל אוֹתָהּ.","פֶּרֶק י״ט, הֲלָכָה י׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["לָמָּה אָסְרוּ חֲכָמִים בַּמָּקוֹר לָצֵאת בְּתַכְשִׁיטִים לִרְשׁוּת הָרַבִּים, אַף שֶׁהֵם טְפֵלִים לַגּוּף?",["כִּי תַּכְשִׁיטִים הֵם מַשָּׂא, כְּמוֹ תִּיק אוֹ סֵפֶר","שֶׁמָּא תּוֹרִיד תַּכְשִׁיט לְהַרְאוֹתוֹ לַחֲבֶרְתָּהּ, וְתִשָּׂא אוֹתוֹ בַּיָּד","כִּי לֹא רָאוּי לְהִתְקַשֵּׁט בְּשַׁבָּת, יוֹם שֶׁל צְנִיעוּת","שֶׁמָּא תַּכְשִׁיט יִשָּׁבֵר, וְתִצְטָרֵךְ לְתַקֵּן אוֹתוֹ בְּשַׁבָּת"],1,"תַּכְשִׁיט עַל הַגּוּף טָפֵל לַגּוּף, כְּמוֹ בֶּגֶד. הַחֲשָׁשׁ הָיָה שֶׁאִשָּׁה תּוֹרִיד אוֹתוֹ כְּדֵי לְהַרְאוֹתוֹ לַחֲבֶרְתָּהּ, תִּשְׁכַּח וְתֵלֵךְ אִתּוֹ אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים. כְּבָר בִּימֵי הָרִאשׁוֹנִים נָהֲגוּ הַנָּשִׁים לָצֵאת בְּתַכְשִׁיטֵיהֶן, וְהַפּוֹסְקִים לִמְּדוּ זְכוּת עַל מִנְהָגָן.","פֶּרֶק כ״א, הֲלָכָה י״ד","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["אֵין עֵרוּב בַּיִּשּׁוּב. נוֹעָה רוֹצָה לְהָבִיא לְסָבְתָא, שֶׁגָּרָה בְּבַיִת אַחֵר, שְׂמִיכָה חַמָּה. אֵיךְ תַּעֲשֶׂה זֹאת?",["תִּתְעַטֵּף בַּשְּׂמִיכָה כְּמוֹ בְּבֶגֶד, וְתֵלֵךְ בָּהּ","תְּקַפֵּל אוֹתָהּ קָטָן מְאוֹד, וְתִשָּׂא אוֹתָהּ בַּיָּד","תֵּלֵךְ פָּחוֹת מֵאַרְבַּע אַמּוֹת, תַּעֲמֹד, וְשׁוּב תֵּלֵךְ","תִּשָּׂא אוֹתָהּ בַּיָּד, אִם תֵּלֵךְ בְּלִי לַעֲצֹר בַּדֶּרֶךְ"],0,"דָּבָר שֶׁאֵינוֹ בֶּגֶד – מִי שֶׁמִּתְעַטֵּף בּוֹ כְּדֶרֶךְ לְבוּשׁ, יָכוֹל לָצֵאת בּוֹ לִרְשׁוּת הָרַבִּים, כִּי הוּא טָפֵל לַגּוּף. לָשֵׂאת אוֹתוֹ בַּיָּד – אָסוּר. וְלָלֶכֶת בְּכָל פַּעַם פָּחוֹת מֵאַרְבַּע אַמּוֹת וְלַעֲמֹד – אָסְרוּ חֲכָמִים, שֶׁמָּא יֵלֵךְ בְּבַת אַחַת יוֹתֵר.","פֶּרֶק כ״א, הֲלָכוֹת ו׳, י׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["בְּשַׁבָּת יֵשׁ לְאוּרִי פֶּצַע קָטָן בַּבֶּרֶךְ, וְהוּא מְגָרֵד לוֹ מְאוֹד. מָה נָכוֹן?",["לֹא יְגָרֵד בְּאֹפֶן שֶׁיּוֹצִיא דָּם, כִּי זֶה חוֹבֵל","מֻתָּר לוֹ לְגָרֵד חָזָק, כִּי זֶה הַגּוּף שֶׁלּוֹ","מֻתָּר לוֹ לְגָרֵד, רַק בְּצִפֹּרֶן וְלֹא בִּכְלִי","אָסוּר לוֹ אֲפִלּוּ לָגַעַת בַּפֶּצַע כָּל הַשַּׁבָּת"],0,"אָסוּר מִן הַתּוֹרָה לְהוֹצִיא דָּם בְּשַׁבָּת, כִּי ״הַדָּם הוּא הַנֶּפֶשׁ״. לָכֵן לֹא מְגָרְדִים פֶּצַע בְּאֹפֶן שֶׁיּוֹצִיא דָּם.","פֶּרֶק כ׳, הֲלָכָה ט׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["דַּג זָהָב קָפַץ בְּשַׁבָּת מִן הָאַקְוַרְיוּם אֶל הַשֻּׁלְחָן, וְהוּא מְפַרְפֵּר. מָה עוֹשִׂים?",["מַחֲזִירִים אוֹתוֹ לַמַּיִם מִיָּד, מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים","לֹא נוֹגְעִים בּוֹ, כִּי דָּג הוּא מֻקְצֶה בְּכָל מַצָּב","מְחַכִּים לְמוֹצָאֵי שַׁבָּת, וְאָז מַחֲזִירִים אוֹתוֹ לָאַקְוַרְיוּם","מְכַסִּים אוֹתוֹ בְּמַגֶּבֶת רְטֻבָּה עַד צֵאת הַשַּׁבָּת"],0,"אַף שֶׁהַדָּג מֻקְצֶה, בִּשְׁעַת הַדְּחָק – כְּשֶׁאֵין פִּתְרוֹן אַחֵר – מֻתָּר לְטַלְטֵל מֻקְצֶה מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים. לָכֵן מַחֲזִירִים אֶת הַדָּג לָאַקְוַרְיוּם, אִם יֵשׁ לְהַנִּיחַ שֶׁיִּחְיֶה.","פֶּרֶק כ׳, הֲלָכָה ה׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["בַּגִּנָּה רָאָה אֶלְיָה פַּרְפַּר יָפֶה, וְהוּא רוֹצֶה לִתְפֹּס אוֹתוֹ בְּצִנְצֶנֶת. מָה הַדִּין?",["מֻתָּר, כִּי פַּרְפַּר אֵינוֹ חַיָּה שֶׁרְגִילִים לָצוּד","אָסוּר מִדִּבְרֵי חֲכָמִים, כִּי זוֹ צֵידָה שֶׁל חֶרֶק","מֻתָּר, אִם מְשַׁחְרְרִים אוֹתוֹ לִפְנֵי צֵאת הַשַּׁבָּת","אָסוּר רַק אִם סוֹגְרִים אֶת הַצִּנְצֶנֶת בְּמִכְסֶה"],1,"הַצָּד מִינִים שֶׁאֵין רְגִילִים לָצוּד, כְּמוֹ זְבוּבִים וַחֲרָקִים – עוֹבֵר בְּאִסּוּר מִדִּבְרֵי חֲכָמִים. וְצֵידַת צִפּוֹרִים וְדָגִים – אֲסוּרָה מִן הַתּוֹרָה.","פֶּרֶק כ׳, הֲלָכָה ו׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["הֶחָצֵר שֶׁל סָבָא הִיא אֲדָמָה וְעָפָר, וְאַחֲרֵי הַסְּעוּדָה נִשְׁפְּכוּ בָּהּ פֵּרוּרִים. מָה עוֹשִׂים?",["מְטַאטְאִים בְּמַטְאֲטֵא רַךְ, כִּי זֶה רַק נִקָּיוֹן לִכְבוֹד שַׁבָּת","לֹא מְטַאטְאִים אֶת הֶעָפָר, כִּי זֶה עָלוּל לְהַשְׁווֹת גֻּמּוֹת","מְטַאטְאִים רַק אִם מְפַזְּרִים קֹדֶם מַיִם עַל הֶעָפָר","מְכַסִּים אֶת הַפֵּרוּרִים בְּעָפָר, בְּעִזְרַת הָרַגְלַיִם"],1,"חֲכָמִים אָסְרוּ לְטַאטֵא אֶת קַרְקַע הֶחָצֵר, שֶׁמָּא יַשְׁווּ גֻּמּוֹת. וְכֵן אָסוּר לִבְעֹט אוֹ לְהָזִיז בָּרֶגֶל אֲדָמָה אוֹ חוֹל. אֲבָל מָקוֹם מְרֻצָּף בֶּחָצֵר – מֻתָּר לְטַאטֵא.","פֶּרֶק י״ט, הֲלָכָה א׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["בְּשַׁבָּת אָכְלוּ אֲבוֹקָדוֹ, וְאֵיתָן רוֹצֶה לָשִׂים אֶת הַגַּלְעִין בְּכוֹס מַיִם, שֶׁיַּכֶּה שָׁרָשִׁים. מָה הַדִּין?",["אָסוּר, כִּי זוֹ פְּעֻלָּה שֶׁגּוֹרֶמֶת לַצֶּמַח לִצְמֹחַ","מֻתָּר, כִּי הַגַּלְעִין אֵינוֹ נָטוּעַ בָּאֲדָמָה","מֻתָּר, אִם מִשְׁתַּמְּשִׁים בְּמַיִם שֶׁנִּשְׁאֲרוּ מִן הַסְּעוּדָה","אָסוּר, כִּי הַגַּלְעִין הוּא פְּסֹלֶת שֶׁל אֹכֶל וּמֻקְצֶה"],0,"כָּל פְּעֻלָּה שֶׁגּוֹרֶמֶת לְצֶמַח לִצְמֹחַ – אֲסוּרָה מִשּׁוּם זוֹרֵעַ. לָכֵן אָסוּר לְהַשְׁקוֹת עֲצִיצִים, וְאָסוּר לָשִׂים גַּלְעִין שֶׁל אֲבוֹקָדוֹ אוֹ עָנָף בְּמַיִם כְּדֵי שֶׁיַּכּוּ שָׁרָשִׁים.","פֶּרֶק י״ט, הֲלָכָה ג׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["בְּחֹרֶף, בִּשְׁכוּנָה שֶׁאֵין בָּהּ עֵרוּב, רוֹצֶה שְׁמוּאֵל לָצֵאת בְּשַׁבָּת עִם הַכֶּלֶב שֶׁלּוֹ. מָה נָכוֹן?",["יוֹצְאִים עִם רְצוּעָה, וְלֹא נוֹתְנִים לָהּ לְהִשְׁתַּלְשֵׁל לְיַד הָאָרֶץ","מַלְבִּישִׁים לַכֶּלֶב מְעִיל חַם, כְּדֵי שֶׁלֹּא יִצְטַעֵר בַּקֹּר","אָסוּר לָצֵאת עִם הַכֶּלֶב, כִּי הָרְצוּעָה נֶחְשֶׁבֶת מַשָּׂא","תּוֹלִים פַּעֲמוֹן קָטָן עַל הַקּוֹלָר, כְּדֵי לִשְׁמֹעַ אוֹתוֹ"],0,"מֻתָּר לְהוֹצִיא כֶּלֶב בִּרְצוּעָה שֶׁבְּצַוָּארוֹ. תּוֹפְסִים אֶת הַחֶבֶל בְּסוֹפוֹ, שֶׁלֹּא יֵצֵא מִן הַיָּד טֶפַח, וּמַקְפִּידִים שֶׁלֹּא יִשְׁתַּלְשֵׁל עַד קָרוֹב לָאָרֶץ. אֲבָל כֶּלֶב בְּבֶגֶד שֶׁעוֹטֵף אֶת גּוּפוֹ – אָסוּר לְהוֹצִיא.","פֶּרֶק כ׳, הֲלָכָה ב׳","הַגִּנָּה, הַחַיּוֹת וְהָרְחוֹב"],["דָּן הִנִּיחַ מַטְבְּעוֹת עַל שֻׁלְחָן קָטָן לִפְנֵי שַׁבָּת, כְּדֵי שֶׁיִּהְיוּ שָׁם. בְּשַׁבָּת הֵן נָפְלוּ. הַאִם מֻתָּר עַכְשָׁו לְהָזִיז אֶת הַשֻּׁלְחָן?",["כֵּן, כִּי עַכְשָׁו אֵין עָלָיו שׁוּם דָּבָר מֻקְצֶה","כֵּן, כִּי שֻׁלְחָן הוּא כְּלִי שֶׁמְּלַאכְתּוֹ לְהֶתֵּר","לֹא, כִּי כָּל שֻׁלְחָן נַעֲשֶׂה מֻקְצֶה בְּשַׁבָּת","לֹא, כִּי בְּבֵין הַשְּׁמָשׁוֹת הוּא הָיָה בָּסִיס"],3,"מָה שֶׁהָיָה מֻקְצֶה בְּבֵין הַשְּׁמָשׁוֹת נִשְׁאָר מֻקְצֶה כָּל הַשַּׁבָּת. דָּן הִנִּיחַ אֶת הַמַּטְבְּעוֹת בְּכַוָּנָה, וְהַשֻּׁלְחָן נַעֲשָׂה בָּסִיס לְדָבָר הָאָסוּר.","פֶּרֶק כ״ג, הֲלָכוֹת ה׳, י׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["הַשָּׁעוֹן הַמְּעוֹרֵר בַּטֶּלֶפוֹן הִתְחִיל לְצַלְצֵל בְּשַׁבָּת וּמַפְרִיעַ לַמִּשְׁפָּחָה לָנוּחַ. מָה מֻתָּר?",["לְכַבּוֹת אֶת הַצִּלְצוּל בִּלְחִיצָה קַלָּה, כִּי זֶה רַק רֶגַע","לְהַרְחִיק אֶת הַטֶּלֶפוֹן, בְּלִי לִלְחֹץ עַל כְּלוּם","אָסוּר לָגַעַת, כִּי טֶלֶפוֹן מֻקְצֶה מֵחֲמַת חֶסְרוֹן כִּיס","לְהַרְחִיק רַק בָּרֶגֶל, כִּי בַּיָּד אָסוּר לְגַמְרֵי"],1,"טֶלֶפוֹן הוּא כְּלִי שֶׁמְּלַאכְתּוֹ לְאִסּוּר: אָסוּר לִלְחֹץ עָלָיו, אֲבָל מֻתָּר לְהָזִיז אוֹתוֹ לְצֹרֶךְ מְקוֹמוֹ – כְּדֵי שֶׁהַצִּלְצוּל לֹא יַפְרִיעַ.","פֶּרֶק כ״ג, הֲלָכוֹת ז׳–ח׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["מִיכָאֵל מְדַבֵּר עִם חָבֵר בְּשַׁבָּת. אֵיזֶה מִשְׁפָּט מֻתָּר לוֹ לְהַגִּיד?",["מָחָר אֲדַבֵּר עִם סַבָּא וְאֶשְׁאַל מָה שְׁלוֹמוֹ","מָחָר אֲטַלְפֵּן לְסַבָּא וְאֶשְׁאַל מָה שְׁלוֹמוֹ","בְּבַקָּשָׁה תִּקְנֶה לִי מָחָר מַחְבֶּרֶת חֲדָשָׁה בַּחֲנוּת","בְּמוֹצָאֵי שַׁבָּת אֶכְתֹּב לְסַבָּא מִכְתָּב אָרֹךְ וְיָפֶה"],0,"דִּבּוּר עַל מְלָאכָה אֲסוּרָה – טֶלֶפוֹן, קְנִיָּה, כְּתִיבָה – אָסוּר בְּשַׁבָּת. \"אֲדַבֵּר\" הוּא רַק רֶמֶז, וְהוּא מֻתָּר אַף שֶׁהֶחָבֵר מֵבִין שֶׁהַכַּוָּנָה לַטֶּלֶפוֹן.","פֶּרֶק כ״ב, הֲלָכָה י׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["אֲרִיאֵל עָבַד בְּשַׁבָּת כְּמֶלְצַר בִּסְעוּדָה, וְסִכְּמוּ מֵרֹאשׁ שֶׁיְּשַׁלְּמוּ לוֹ רַק עַל הַשַּׁבָּת. מָה הַדִּין?",["מֻתָּר לְקַבֵּל, כִּי מֶלְצָרוּת הִיא עֲבוֹדָה מֻתֶּרֶת בְּשַׁבָּת","מֻתָּר לְקַבֵּל, אִם יִקַּח אֶת הַכֶּסֶף רַק בְּמוֹצָאֵי שַׁבָּת","אָסוּר לְקַבֵּל שָׂכָר כָּזֶה, גַּם אַחֲרֵי שֶׁיָּצְאָה הַשַּׁבָּת","אָסוּר לְקַבֵּל, אֲבָל מֻתָּר לְבַקֵּשׁ אֶת הַכֶּסֶף כְּהַלְוָאָה"],2,"שְׂכַר שַׁבָּת אָסוּר גַּם עַל עֲבוֹדָה מֻתֶּרֶת, וְגַם בְּדִיעֲבַד. אִלּוּ סִכְּמוּ שֶׁיַּעֲבֹד גַּם בְּמוֹצָאֵי שַׁבָּת, הַשָּׂכָר הָיָה \"מֻבְלָע\" בִּשְׂכַר חֹל.","פֶּרֶק כ״ב, הֲלָכָה י״ד","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["אַחֲרֵי סְעוּדָה שְׁלִישִׁית, דַּקּוֹת סְפוּרוֹת לִפְנֵי צֵאת הַשַּׁבָּת, כֻּלָּם יוֹצְאִים מִן הַחֶדֶר. מֻתָּר לְסַדֵּר עַכְשָׁו אֶת הַשֻּׁלְחָן?",["כֵּן, כִּי מִצְוָה שֶׁהַבַּיִת יִהְיֶה תָּמִיד מְסֻדָּר","כֵּן, אִם יְפַנֶּה בְּשִׁנּוּי, בְּיַד שְׂמֹאל","לֹא, כִּי כָּל הַכֵּלִים הַמְּלֻכְלָכִים הֵם מֻקְצֶה","לֹא, זוֹ הֲכָנָה מִשַּׁבָּת לְיוֹם חֹל"],3,"כָּל עוֹד הַסִּדּוּר מוֹעִיל לַשַּׁבָּת – מֻתָּר. אֲבָל כְּשֶׁהוּא מוֹעִיל רַק לְמוֹצָאֵי שַׁבָּת, זוֹ הֲכָנָה מִשַּׁבָּת לְחֹל, וַאֲסוּרָה.","פֶּרֶק כ״ב, הֲלָכָה ט״ו","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["אֵיזוֹ קְרִיאָה מֻתֶּרֶת לְאֵלִי בְּשַׁבָּת?",["עַלּוֹן פִּרְסֹמוֹת שֶׁל חֲנוּת צַעֲצוּעִים, כְּדֵי לִבְחֹר מַתָּנָה","רְשִׁימַת הַמְּחִירִים שֶׁבְּחַלּוֹן הָרַאֲוָה שֶׁל הַחֲנוּת","חֶשְׁבּוֹן הַחַשְׁמַל שֶׁהִגִּיעַ לַבַּיִת בְּיוֹם שִׁשִּׁי","סֵפֶר עַל חַיּוֹת וּצְמָחִים, שֶׁמְּלַמֵּד חָכְמָה"],3,"פִּרְסֹמוֹת לִקְנִיָּה, מְחִירִים וְחֶשְׁבּוֹנוֹת הֵם עִסְקֵי חֹל. סֵפֶר שֶׁמְּלַמֵּד חָכְמָה – מֻתָּר לִקְרֹא, וְהוּא אַף מְגַלֶּה אֶת גְּדֻלַּת הַבּוֹרֵא.","פֶּרֶק כ״ב, הֲלָכָה י״ב","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["בִּסְעוּדַת שַׁבָּת כֻּלָּם שָׁרִים, וְיוֹסִי רוֹצֶה לִמְחֹא כַּף בְּאֹפֶן שֶׁמֻּתָּר לְכָל הַדֵּעוֹת. אֵיךְ יַעֲשֶׂה?",["יִמְחָא כַּף רָגִיל, אֲבָל רַק בְּשִׁיר שֶׁל שַׁבָּת","יִמְחָא כַּף בְּשִׁנּוּי – בְּגַב הַיָּד עַל כַּף הַיָּד","יִתּוֹפֵף בְּאֶצְבְּעוֹתָיו עַל הַשֻּׁלְחָן, בִּמְקוֹם לִמְחֹא כַּף","יִמְחָא כַּף בְּשֶׁקֶט מְאוֹד, כְּדֵי שֶׁלֹּא יִשְׁמְעוּ אוֹתוֹ בַּחוּץ"],1,"חֲכָמִים אָסְרוּ לִמְחֹא כַּף וְלִרְקֹד בִּזְמַן שִׁירָה, שֶׁמָּא יָבוֹאוּ לְנַגֵּן וּלְתַקֵּן כְּלִי נְגִינָה. אֲבָל בְּשִׁנּוּי – בְּגַב הַיָּד עַל כַּף הַיָּד – מֻתָּר, כִּי הַשִּׁנּוּי מַזְכִּיר שֶׁשַּׁבָּת הַיּוֹם. וְלִתְפֹּף עַל הַשֻּׁלְחָן – גַּם הַמְּקִלִּים אוֹמְרִים שֶׁרָאוּי שֶׁלֹּא.","פֶּרֶק כ״ב, הֲלָכָה י״ח","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["יוֹנָתָן מַצִּיעַ לְכַוֵּן בְּעֶרֶב שַׁבָּת שְׁעוֹן שַׁבָּת, שֶׁיַּדְלִיק אֶת הַטֵּלֶוִיזְיָה בְּשַׁבָּת לְסֶרֶט. מָה הַדִּין?",["מֻתָּר, כִּי שְׁעוֹן הַשַּׁבָּת מַדְלִיק לְבַד וְאִישׁ לֹא נוֹגֵעַ","אָסוּר, גַּם כְּשֶׁהֻפְעַל מֵרֹאשׁ, כִּי זֶה מַעֲשֵׂה חֹל","מֻתָּר, אִם מְכַוְּנִים אֶת הַקּוֹל נָמוּךְ וְלֹא מְשַׁנִּים אוֹתוֹ","מֻתָּר, אִם בּוֹחֲרִים בְּסֶרֶט שֶׁעוֹסֵק בְּפָרָשַׁת הַשָּׁבוּעַ"],1,"אָסוּר לִשְׁמֹעַ רַדְיוֹ וְלִצְפּוֹת בְּטֵלֶוִיזְיָה בְּשַׁבָּת, גַּם כְּשֶׁהִפְעִילוּ אוֹתָם בְּעֶרֶב שַׁבָּת. וְכֵן אָסוּר לְהַפְעִיל בִּשְׁעוֹן שַׁבָּת טֵיפּ אוֹ וִידֵאוֹ. בָּזֶה מַסְכִּימִים כָּל הַפּוֹסְקִים.","פֶּרֶק כ״ב, הֲלָכָה י״ט","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["בְּשַׁבָּת שָׁלְחָה אִמָּא אֶת יוֹסִי לַשְּׁכֵנִים לְבַקֵּשׁ שָׁלֹשׁ בֵּיצִים. אֵיךְ נָכוֹן לְבַקֵּשׁ?",["״תַּלְווּ לָנוּ שָׁלֹשׁ בֵּיצִים, וּנְשַׁלֵּם לָכֶם בְּיוֹם רִאשׁוֹן״","בִּלְשׁוֹן ״תַּשְׁאִילוּ לָנוּ״, בְּלִי לְהַזְכִּיר הַלְוָאָה אוֹ תַּשְׁלוּם","״תִּמְכְּרוּ לָנוּ שָׁלֹשׁ בֵּיצִים, וְנַחְזִיר אֶת הַכֶּסֶף מָחָר״","אָסוּר לְבַקֵּשׁ דָּבָר מִן הַשְּׁכֵנִים בְּשַׁבָּת, גַּם לֹא בֵּיצִים"],1,"בְּשַׁבָּת אָסוּר לְהַלְווֹת וְלִפְרֹעַ חוֹב. מִי שֶׁצָּרִיךְ מֵחֲבֵרוֹ מַאֲכָל, בֶּגֶד אוֹ כִּסֵּא לְצֹרֶךְ שַׁבָּת – מְבַקֵּשׁ בִּלְשׁוֹן ״הַשְׁאָלָה״, אוֹ ״תֵּן לִי״. וְאִם בִּקֵּשׁ בִּלְשׁוֹן הַלְוָאָה – עוֹנִים לוֹ שֶׁאָסוּר לְהַלְווֹת, אֲבָל אֶפְשָׁר לְהַשְׁאִיל.","פֶּרֶק כ״ב, הֲלָכָה ד׳","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["מִיכָאֵל שָׁפַךְ מִיץ עַל הָרִצְפָּה בְּשַׁבָּת, וְאֵין לְיָדוֹ מַטְלִית. מָה נָכוֹן?",["לִסְפֹּג אֶת הַמִּיץ בְּחֻלְצָה יְשָׁנָה מִן הָאָרוֹן","לְהָבִיא סְמַרְטוּט מִן הַמִּטְבָּח, וְלִסְפֹּג בְּלִי לִסְחֹט","לְנַגֵּב בַּמַּגֶּבֶת הַנְּקִיָּה שֶׁל הָאוֹרְחִים, כִּי הִיא קְרוֹבָה","לִזְרֹק עַל הַמִּיץ כָּרִית יְשָׁנָה, שֶׁתִּסְפֹּג אֶת הַכֹּל"],1,"מַשְׁקֶה שֶׁנִּשְׁפַּךְ עַל הָרִצְפָּה – אָסוּר לִסְפֹּג בִּבְגָדִים, וְאָסוּר לְהַרְטִיב כָּרִים, כִּי מְקַלְקְלִים אוֹתָם מִלְּהִיּוֹת רְאוּיִים לְתַפְקִידָם. אֲבָל מֻתָּר לִסְפֹּג בִּסְמַרְטוּט, שֶׁנּוֹעַד לְכָךְ, וּבִלְבַד שֶׁלֹּא סוֹחֲטִים אוֹתוֹ.","פֶּרֶק כ״ג, הֲלָכָה י״א","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["כּוֹס זְכוּכִית נִשְׁבְּרָה בְּשַׁבָּת עַל הָרִצְפָּה, וְהַתִּינוֹק זוֹחֵל בַּסָּלוֹן. מָה עוֹשִׂים?",["לֹא נוֹגְעִים בַּשְּׁבָרִים, כִּי הֵם מֻקְצֶה, וּמְחַכִּים לְמוֹצָאֵי שַׁבָּת","מְפַנִּים אֶת הַשְּׁבָרִים, כִּי יֵשׁ סַכָּנָה שֶׁמִּישֶׁהוּ יִפָּצַע","מְפַנִּים רַק שְׁבָרִים גְּדוֹלִים, וְאֶת הַקְּטַנִּים מַשְׁאִירִים","מְדַבְּקִים אֶת הַשְּׁבָרִים, כְּדֵי שֶׁהַכּוֹס לֹא תִּהְיֶה מֻקְצֶה"],1,"כְּלִי שֶׁנִּשְׁבַּר בְּשַׁבָּת, וְאֵין סִכּוּי שֶׁיִּשְׁתַּמְּשׁוּ בַּשְּׁבָרִים – הֵם מֻקְצֶה. אֲבָל כְּשֶׁיֵּשׁ סַכָּנָה שֶׁבְּנֵי הַבַּיִת יִפָּצְעוּ מֵהֶם – מֻתָּר לְפַנּוֹת אוֹתָם בַּיָּדַיִם.","פֶּרֶק כ״ג, הֲלָכָה י״ג","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["בְּשַׁבָּת הֵרִים אֲרִיאֵל עֵט מִן הָרִצְפָּה, וְרַק אָז נִזְכַּר שֶׁהוּא מֻקְצֶה. מָה יַעֲשֶׂה?",["יַחֲזִיק אוֹתוֹ עַד שֶׁיַּגִּיעַ לַשֻּׁלְחָן שֶׁבְּחַדְרוֹ, וְשָׁם יַנִּיחַ","יַשְׁמִיט אוֹתוֹ מִיָּד מִיָּדוֹ, בַּמָּקוֹם שֶׁבּוֹ הוּא עוֹמֵד","יַעֲבִיר אוֹתוֹ לְיָדוֹ הַשְּׂמָאלִית, וְכָךְ הַטִּלְטוּל קַל יוֹתֵר","יַחְזִיר אוֹתוֹ בְּדִיּוּק לַמָּקוֹם שֶׁמִּמֶּנּוּ הֵרִים אוֹתוֹ"],1,"הַשּׁוֹכֵחַ וְנוֹטֵל בְּיָדוֹ מֻקְצֶה – צָרִיךְ לְהַשְׁמִיט אוֹתוֹ מִיָּד. אֲבָל מָה שֶׁהִגִּיעַ לַיָּד בְּהֶתֵּר, כְּמוֹ קְלִפּוֹת שֶׁנִּשְׁאֲרוּ אַחֲרֵי אֲכִילַת פְּרִי – מֻתָּר לְהַמְשִׁיךְ לְטַלְטֵל עַד הַמָּקוֹם שֶׁרוֹצִים.","פֶּרֶק כ״ג, הֲלָכָה ט״ו","יוֹם שֶׁל מְנוּחָה וּקְדֻשָּׁה"],["בְּשַׁבָּת כָּבָה הָאוֹר בַּסָּלוֹן, וְהַשָּׁכֵן הַגּוֹי גָּר מִמּוּל. מָה מֻתָּר לְאַבָּא לַעֲשׂוֹת?",["לְבַקֵּשׁ מֵהַשָּׁכֵן הַגּוֹי בִּמְפֹרָשׁ שֶׁיַּדְלִיק לָהֶם אֶת הָאוֹר","לְהַזְמִין אֶת הַשָּׁכֵן לֶאֱכֹל, וְהוּא יַדְלִיק לְעַצְמוֹ","לְהַצְבִּיעַ לַשָּׁכֵן עַל הַמְּנוֹרָה, בְּלִי לוֹמַר אַף מִלָּה","לְבַקֵּשׁ מִיֶּלֶד קָטָן שֶׁיַּדְלִיק, כִּי הוּא אֵינוֹ חַיָּב"],1,"הַגּוֹי שֶׁבָּא לֶאֱכֹל רוֹאֶה שֶׁחָשׁוּךְ וּמַדְלִיק אוֹר בִּשְׁבִיל עַצְמוֹ, וְאָז מֻתָּר לְכֻלָּם לֵהָנוֹת. הַצְבָּעָה הִיא רֶמֶז שֶׁל צִוּוּי, וְיֶלֶד אָסוּר לְהַעֲבִיד.","פֶּרֶק כ״ה, הֲלָכוֹת ב׳–ג׳; פֶּרֶק כ״ד, הֲלָכָה ד׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["יְהוּדִי הִדְלִיק בְּשַׁבָּת אוֹר בַּחֲדַר הַמַּדְרֵגוֹת. מָה מֻתָּר לְנֹעַם לַעֲשׂוֹת?",["לַעֲלוֹת כָּרָגִיל, כִּי גַּם בַּחֹשֶׁךְ אֶפְשָׁר לַעֲלוֹת","לַעֲלוֹת בְּרִיצָה מְהִירָה, כָּל עוֹד הָאוֹר דּוֹלֵק","אָסוּר לַעֲלוֹת כְּלָל, עַד שֶׁהָאוֹר יִכְבֶּה מֵעַצְמוֹ","לִקְרֹא סֵפֶר לְאוֹר הַמְּנוֹרָה, כִּי הָאוֹר כְּבָר דָּלַק"],0,"מָה שֶׁאֶפְשָׁר הָיָה לַעֲשׂוֹת גַּם בְּלִי הָאוֹר – מֻתָּר. אֲבָל לֹא רָצִים וְלֹא קוֹרְאִים בִּזְכוּת הָאוֹר, כִּי זוֹ הֲנָאָה מִמְּלֶאכֶת שַׁבָּת.","פֶּרֶק כ״ו, הֲלָכָה ב׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["אָדָם בִּשֵּׁל בְּשַׁבָּת בְּמֵזִיד. מָה דִּין הָאֹכֶל?",["כֻּלָּם רַשָּׁאִים לֶאֱכֹל כְּבָר בְּשַׁבָּת, כִּי זֶה עֹנֶג שַׁבָּת","אֲחֵרִים מֻתָּרִים בְּמוֹצָאֵי שַׁבָּת, וְהַמְּבַשֵּׁל אָסוּר לְעוֹלָם","אָסוּר לְכֻלָּם לְעוֹלָם, כִּי הוּא נַעֲשָׂה בְּחִלּוּל שַׁבָּת","רַק הַמְּבַשֵּׁל רַשַּׁאי לֶאֱכֹל, אַחֲרֵי שֶׁיַּעֲשֶׂה תְּשׁוּבָה"],1,"בְּשַׁבָּת אָסוּר לְכֻלָּם לֶאֱכֹל, גַּם לְשֵׁם עֹנֶג שַׁבָּת. בְּמוֹצָאֵי שַׁבָּת מֻתָּר לַאֲחֵרִים, וּמִי שֶׁבִּשֵּׁל בְּמֵזִיד – לֹא יֵהָנֶה מִזֶּה לְעוֹלָם.","פֶּרֶק כ״ו, הֲלָכוֹת ב׳, ז׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["בְּשַׁבָּת נִשְׁעַן אֵלִי עַל הַקִּיר, וּבְלִי לָשִׂים לֵב לָחַץ עַל הַמֶּתֶג וְהִדְלִיק אוֹר. מָה הַדִּין?",["אָסוּר לֵהָנוֹת, כְּמוֹ מִי שֶׁהִדְלִיק מִתּוֹךְ הֶרְגֵּל","צָרִיךְ מִיָּד לְכַבּוֹת אֶת הָאוֹר, כְּדֵי לְתַקֵּן","מֻתָּר לֵהָנוֹת רַק אִם גּוֹי יְכַבֶּה אַחַר כָּךְ","מֻתָּר לֵהָנוֹת, כִּי לֹא הָיְתָה שׁוּם כַּוָּנָה"],3,"מִי שֶׁעָשָׂה מְלָאכָה בְּלִי שׁוּם כַּוָּנָה הוּא \"מִתְעַסֵּק\", וּמֻתָּר לֵהָנוֹת. מִי שֶׁהִדְלִיק מִתּוֹךְ הֶרְגֵּל – הִתְכַּוֵּן לְהַדְלִיק, וְהוּא שׁוֹגֵג.","פֶּרֶק כ״ו, הֲלָכָה ג׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["אָחִיו הַקָּטָן שֶׁל דָּוִד הִדְלִיק בְּטָעוּת מְנוֹרָה בַּחֶדֶר, כְּדֵי לְשַׂחֵק לְעַצְמוֹ. הַאִם מֻתָּר לְדָוִד לִקְרֹא לְאוֹרָהּ?",["לֹא, כִּי אָסוּר לֵהָנוֹת מִכָּל אוֹר שֶׁהֻדְלַק בְּשַׁבָּת","לֹא, אֶלָּא אִם כֵּן הַקָּטָן עוֹד לֹא בֶּן שָׁלֹשׁ","כֵּן, כִּי הַקָּטָן הִדְלִיק לְצָרְכֵי עַצְמוֹ","כֵּן, אֲבָל רַק אַחֲרֵי שֶׁיִּגְעֲרוּ בַּקָּטָן"],2,"קָטָן שֶׁעָשָׂה מְלָאכָה לְצֹרֶךְ עַצְמוֹ – מֻתָּר לַגָּדוֹל לֵהָנוֹת מִמֶּנָּה. רַק כְּשֶׁהִדְלִיק בִּשְׁבִיל גָּדוֹל – אָסוּר.","פֶּרֶק כ״ד, הֲלָכָה ד׳; פֶּרֶק כ״ו, הֲלָכָה א׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["בַּחֶדֶר דּוֹלֵק אוֹר חַלָּשׁ שֶׁמַּסְפִּיק בְּקֹשִׁי לְסַדֵּר, וְשָׁכֵן גּוֹי נִמְצָא שָׁם. מָה מֻתָּר לְאַבָּא לוֹמַר?",["עֲשֵׂה לִי טוֹבָה, אֵין מַסְפִּיק אוֹר בַּחֶדֶר הַזֶּה","קָשֶׁה לִי לְסַדֵּר אֶת הַבַּיִת כְּשֶׁהָאוֹר חַלָּשׁ","אַתָּה יָכוֹל בְּבַקָּשָׁה לְהַדְלִיק אֶת הַמְּנוֹרָה הַשְּׁנִיָּה?","הַדְלֵק אֶת הָאוֹר בְּשִׁנּוּי, עִם הַמַּרְפֵּק שֶׁלְּךָ"],1,"מֻתָּר לִרְמֹז בְּדֶרֶךְ סִפּוּר, וְהַגּוֹי מַחְלִיט לְבַד. אַחַר כָּךְ מֻתָּר לְסַדֵּר לְאוֹר הַנּוֹסָף – כִּי גַּם קֹדֶם אֶפְשָׁר הָיָה – אֲבָל לֹא לִקְרֹא.","פֶּרֶק כ״ה, הֲלָכָה ג׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["בְּשַׁבָּת אַחַר הַצָּהֳרַיִם רוֹצָה שִׁירָה לִקְלֹעַ צְמִיד מֵחוּטִים צִבְעוֹנִיִּים, כְּמוֹ בִּימוֹת הַחֹל. מָה הַדִּין?",["מֻתָּר, כִּי זֶה רַק מִשְׂחָק שֶׁל יְלָדִים קְטַנִּים","אָסוּר, כִּי מִשְׂחָק שֶׁל קְלִיעָה אָסוּר בְּשַׁבָּת","מֻתָּר, אִם תְּפָרֵק אוֹתוֹ לִפְנֵי צֵאת הַשַּׁבָּת","מֻתָּר, אִם הַחוּטִים נֶחְתְּכוּ מֵעֶרֶב שַׁבָּת"],1,"כָּל מִשְׂחָק שֶׁיֵּשׁ בּוֹ כְּתִיבָה, הַדְבָּקָה, גְּזִירָה אוֹ קְלִיעָה – אָסוּר בְּשַׁבָּת, גַּם לִילָדִים. אֶת הַצְּמִיד אֶפְשָׁר לִקְלֹעַ בְּמוֹצָאֵי שַׁבָּת.","פֶּרֶק כ״ד, הֲלָכָה ז׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["מִיכַל מַשְׁחִילָה בְּשַׁבָּת חֲרוּזִים עַל חוּט, לְמַחֲרֹזֶת שֶׁל מִשְׂחָק. אֵיךְ תִּסְגֹּר אֶת הַמַּחֲרֹזֶת?",["בְּקֶשֶׁר כָּפוּל וְחָזָק, כְּדֵי שֶׁהַחֲרוּזִים לֹא יִפְּלוּ","בַּעֲנִיבָה בִּלְבַד, בְּלִי לִקְשֹׁר קֶשֶׁר בְּסוֹף הַחוּט","בְּהַדְבָּקָה שֶׁל קְצוֹת הַחוּט בְּסֶלוֹטֵיְפּ קָטָן","בְּקֶשֶׁר רָגִיל, אִם תַּתִּיר אוֹתוֹ בְּמוֹצָאֵי שַׁבָּת"],1,"מֻתָּר לַעֲשׂוֹת מַחֲרֹזֶת שֶׁל מִשְׂחָק שֶׁאֵינָהּ עוֹמֶדֶת לְהִתְקַיֵּם, וּבִתְנַאי שֶׁלֹּא קוֹשְׁרִים קֶשֶׁר בְּסוֹף הַחוּט, אֶלָּא סוֹגְרִים בַּעֲנִיבָה. גַּם הַדְבָּקָה אֲסוּרָה בְּשַׁבָּת.","פֶּרֶק כ״ד, הֲלָכָה ז׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["יוֹם קַיִץ חַם מְאוֹד בְּשַׁבָּת, וְכָל הַמִּשְׁפָּחָה סוֹבֶלֶת. מָה מֻתָּר לְפִי הָרַב מֶלָמֵד?",["לְבַקֵּשׁ מִגּוֹי לְהַדְלִיק מַזְגָן, וְעָדִיף בְּשִׁנּוּי","לְבַקֵּשׁ מִיֶּלֶד קָטָן לְהַדְלִיק אֶת הַמַּזְגָן","לְהַדְלִיק לְבַד אֶת הַמַּזְגָן, בְּלִחְיצָה בְּכַפִּית","לְחַכּוֹת שֶׁהַגּוֹי יָבִין לְבַד, וְאָסוּר לְבַקֵּשׁ"],0,"לְצֹרֶךְ מִצְטַעֵר מֻתָּר לְבַקֵּשׁ מִגּוֹי מְלָאכָה שֶׁאֲסוּרָה מִדִּבְרֵי חֲכָמִים. יֵשׁ אוֹמְרִים שֶׁהַדְלָקַת מַזְגָן הִיא כָּזוֹ, וְלָכֵן בְּיוֹם חַם מֻתָּר לְבַקֵּשׁ מִגּוֹי לְהַדְלִיקוֹ, וְנָכוֹן שֶׁיַּעֲשֶׂה זֹאת בְּשִׁנּוּי. לְבַקֵּשׁ מִיֶּלֶד – אָסוּר, וּלְהַדְלִיק לְבַד – אָסוּר.","פֶּרֶק כ״ה, הֲלָכָה ה׳; פֶּרֶק כ״ד, הֲלָכָה ד׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["לֵיל שַׁבָּת, וְאַבָּא עוֹד לֹא חָזַר מִבֵּית הַכְּנֶסֶת לְקַדֵּשׁ. אָחִיךָ בֶּן הַשֶּׁבַע רָעֵב מְאֹד. מָה הַדִּין?",["מֻתָּר לָתֵת לוֹ לֶאֱכֹל, כִּי הָאֹכֶל עַצְמוֹ כָּשֵׁר","אָסוּר, כִּי בְּגִיל שֶׁבַע הוּא כְּבָר בְּגִיל חִנּוּךְ","מֻתָּר רַק לִשְׁתּוֹת מַיִם, אֲבָל לֹא לֶאֱכֹל כְּלָל","אָסוּר, אֶלָּא אִם כֵּן הוּא חוֹלֶה וְשׁוֹכֵב בַּמִּטָּה"],0,"אָסוּר לְהַאֲכִיל קָטָן מַאֲכָלִים אֲסוּרִים. אֲבָל כְּשֶׁהַמַּאֲכָל כָּשֵׁר, וְרַק הַזְּמַן אֵינוֹ רָאוּי – לִפְנֵי קִדּוּשׁ אוֹ הַבְדָּלָה, אוֹ בְּתַעֲנִית – מֻתָּר לָתֵת לְקָטָן רָעֵב אוֹ צָמֵא לֶאֱכֹל וְלִשְׁתּוֹת, גַּם אַחֲרֵי שֶׁהִגִּיעַ לְגִיל חִנּוּךְ.","פֶּרֶק כ״ד, הֲלָכָה ב׳","יְלָדִים שׁוֹמְרֵי שַׁבָּת"],["בְּשַׁבָּת קָרַס מַחְסָן יָשָׁן, וְלֹא יָדוּעַ אִם מִישֶׁהוּ הָיָה בְּתוֹכוֹ. מָה עוֹשִׂים?",["מְחַכִּים עַד שֶׁיִּהְיֶה בָּרוּר שֶׁיֵּשׁ שָׁם אָדָם","מְפַנִּים מִיָּד, גַּם כְּשֶׁיֵּשׁ רַק סָפֵק","מְפַנִּים רַק אִם רֹב הַסִּכּוּי שֶׁמִּישֶׁהוּ שָׁם חַי","מְבַקְּשִׁים קֹדֶם מִגּוֹי לְפַנּוֹת, כְּדֵי לְמַעֵט בְּאִסּוּר"],1,"גַּם כְּשֶׁיֵּשׁ סָפֵק אִם יֵשׁ שָׁם אָדָם, וְסָפֵק אִם הוּא חַי – מְפַנִּים מִיָּד. מִכָּאן הַשֵּׁם \"פִּקּוּחַ נֶפֶשׁ\": פִּקּוּחַ הוּא פִּנּוּי הַגַּל.","פֶּרֶק כ״ז, הֲלָכוֹת א׳, ד׳","וָחַי בָּהֶם"],["דּוֹד יוֹסֵף אוֹמֵר שֶׁהוּא מַרְגִּישׁ שֶׁמַּצָּבוֹ מְסֻכָּן, וְהָרוֹפֵא בַּטֶּלֶפוֹן חוֹשֵׁב שֶׁלֹּא. מָה עוֹשִׂים?",["שׁוֹמְעִים לָרוֹפֵא, כִּי הוּא מֵבִין בִּרְפוּאָה יוֹתֵר","שׁוֹאֲלִים רַב, וְעוֹשִׂים בְּדִיּוּק כְּפִי שֶׁהוּא יַגִּיד","מְחַכִּים שָׁעָה, וְרוֹאִים אִם הַמַּצָּב שֶׁלּוֹ מַחְמִיר","בּוֹדְקִים אוֹתוֹ, כִּי לֵב יוֹדֵעַ מָרַּת נַפְשׁוֹ"],3,"לִפְעָמִים רַק הַחוֹלֶה עַצְמוֹ מַרְגִּישׁ אֶת מַצָּבוֹ. כְּשֶׁיֵּשׁ הִגָּיוֹן בִּדְבָרָיו – מְחַלְּלִים שַׁבָּת כְּדֵי לִבְדֹּק אוֹתוֹ, וְלֹא מְעַכְּבִים.","פֶּרֶק כ״ז, הֲלָכָה ב׳","וָחַי בָּהֶם"],["אַבָּא צָרִיךְ לְהַסִּיעַ חוֹלֶה מְסֻכָּן לְבֵית חוֹלִים. אֵיךְ יִנְהַג?",["כְּמוֹ בְּיוֹם חֹל, בַּדֶּרֶךְ הַטּוֹבָה וְהַמְּהִירָה","בְּשִׁנּוּי, גַּם אִם זֶה מְעַכֵּב אֶת הַנְּסִיעָה","לְאַט מְאוֹד, כְּדֵי לְמַעֵט בְּחִלּוּל הַשַּׁבָּת","רַק אַחֲרֵי שֶׁיִּמְצָא נֶהָג גּוֹי בַּשְּׁכוּנָה"],0,"בְּהַצָּלַת נְפָשׁוֹת \"הַזָּרִיז הֲרֵי זֶה מְשֻׁבָּח\". כָּל נִסָּיוֹן לְשַׁנּוֹת אוֹ לְחַפֵּשׂ גּוֹי עָלוּל לְעַכֵּב, וְלָכֵן נוֹסְעִים כְּדֶרֶךְ חֹל.","פֶּרֶק כ״ז, הֲלָכוֹת ד׳–ו׳","וָחַי בָּהֶם"],["לְאַבָּא כּוֹאֵב קְצָת הַגָּרוֹן, וְהוּא מִתְהַלֵּךְ כְּבָרִיא. מָה מֻתָּר לוֹ?",["לִמְצֹץ סֻכָּרִיַּת רְפוּאָה מְיֻחֶדֶת לִכְאֵב גָּרוֹן","לְגַרְגֵּר שֶׁמֶן בַּגָּרוֹן, כְּדֶרֶךְ שֶׁעוֹשִׂים לִרְפוּאָה","לִמְצֹץ סֻכָּרִיָּה רְגִילָה, שֶׁגַּם בְּרִיאִים אוֹכְלִים","לְבַקֵּשׁ מִגּוֹי לִקְנוֹת לוֹ תְּרוּפָה בְּבֵית מִרְקַחַת"],2,"מִי שֶׁיֵּשׁ לוֹ מֵחוּשׁ קַל לֹא מִשְׁתַּמֵּשׁ בִּרְפוּאוֹת. אֲבָל מָה שֶׁגַּם בְּרִיאִים אוֹכְלִים – מֻתָּר, גַּם אִם הוּא מֵקֵל עַל הַכְּאֵב.","פֶּרֶק כ״ח, הֲלָכוֹת ג׳–ד׳","וָחַי בָּהֶם"],["לְיוֹסִי הַקָּטָן יֵשׁ פֶּצַע כּוֹאֵב, וְצָרִיךְ לָשִׂים עָלָיו מִשְׁחָה. אֵיךְ עוֹשִׂים זֹאת בְּשַׁבָּת?",["מוֹרְחִים אוֹתָהּ הֵיטֵב, עַד שֶׁהַשִּׁכְבָה תִּהְיֶה חֲלָקָה","שָׂמִים מִן הַשְּׁפוֹפֶרֶת, בְּלִי לִמְרֹחַ","מוֹרְחִים עַל תַּחְבֹּשֶׁת שֶׁחָתְכוּ עַכְשָׁו בְּמִסְפָּרַיִם","אָסוּר לְהִשְׁתַּמֵּשׁ בְּמִשְׁחָה בְּשַׁבָּת בְּשׁוּם אֹפֶן"],1,"מְרִיחָה שֶׁמַּחֲלִיקָה אֶת הַמִּשְׁחָה הִיא מְלֶאכֶת מְמָרֵחַ, וְחִתּוּךְ תַּחְבֹּשֶׁת – מְחַתֵּךְ. לְקָטָן וּבִמְקוֹם צַעַר מֻתָּר לָשִׂים מִשְׁחָה בְּלִי לִמְרֹחַ.","פֶּרֶק כ״ח, הֲלָכוֹת ח׳–ט׳; פֶּרֶק כ״ד, הֲלָכָה ו׳","וָחַי בָּהֶם"],["מִתְנַדֵּב יָצָא בְּשַׁבָּת מִחוּץ לַתְּחוּם כְּדֵי לְהַצִּיל אָדָם. מָה דִּינוֹ אַחֲרֵי הַהַצָּלָה?",["יֵשׁ לוֹ רַק אַרְבַּע אַמּוֹת, כְּמוֹ כָּל מִי שֶׁיָּצָא","עָלָיו לְהִשָּׁאֵר בְּדִיּוּק בַּמָּקוֹם עַד מוֹצָאֵי שַׁבָּת","עָלָיו לָשׁוּב מִיָּד הַבַּיְתָה, בְּכָל מֶרְחָק שֶׁהוּא","יֵשׁ לוֹ אַלְפַּיִם אַמָּה לְכָל רוּחַ מִמְּקוֹם הַהַצָּלָה"],3,"מִי שֶׁיָּצָא מִן הַתְּחוּם סְתָם – יֵשׁ לוֹ רַק אַרְבַּע אַמּוֹת. אֲבָל לַמַּצִּיל תִּקְּנוּ חֲכָמִים אַלְפַּיִם אַמָּה, כְּדֵי שֶׁאֲנָשִׁים לֹא יְהַסְּסוּ לָצֵאת לְהַצִּיל.","פֶּרֶק ל׳, הֲלָכָה י״א","וָחַי בָּהֶם"],["נֹעַם נָפַל בֶּחָצֵר בְּשַׁבָּת וְנִשְׂרַט בַּבֶּרֶךְ. אֵיךְ מְחַטְּאִים אֶת הַפֶּצַע?",["טוֹבְלִים צֶמֶר גֶּפֶן בְּיוֹד, וּמוֹרְחִים עַל הַפֶּצַע בַּעֲדִינוּת","שׁוֹפְכִים מְעַט יוֹד אוֹ מֵי חַמְצָן יָשָׁר עַל הַפֶּצַע","מְחַכִּים לְמוֹצָאֵי שַׁבָּת, כִּי בְּשַׁבָּת אָסוּר לְחַטֵּא פְּצָעִים","מַרְטִיבִים תַּחְבֹּשֶׁת בְּמֵי חַמְצָן, וּמְנַגְּבִים אִתָּהּ אֶת הַפֶּצַע"],1,"אֶת הַיּוֹד אוֹ מֵי הַחַמְצָן שׁוֹפְכִים יָשָׁר עַל הַמָּקוֹם שֶׁצָּרִיךְ חִטּוּי. לֹא מְחַטְּאִים בְּצֶמֶר גֶּפֶן אוֹ בְּתַחְבֹּשֶׁת, מִשּׁוּם אִסּוּר סְחִיטָה. אֶפְשָׁר גַּם לְהִשְׁתַּמֵּשׁ בְּמַקֵּל אוֹ בְּחֹמֶר סִינְתֶטִי שֶׁאֵינוֹ סוֹפֵג.","פֶּרֶק כ״ח, הֲלָכָה ז׳","וָחַי בָּהֶם"],["יוֹסֵף רָגִיל לַעֲשׂוֹת כָּל בֹּקֶר שְׁכִיבוֹת סְמִיכָה לְאִמּוּן כֹּשֶׁר. מָה יַעֲשֶׂה בְּשַׁבָּת?",["יַמְשִׁיךְ כָּרָגִיל, כִּי שְׁמִירָה עַל הַבְּרִיאוּת הִיא מִצְוָה","לֹא יִתְאַמֵּן, אֲבָל מֻתָּר לוֹ לְהִתְמַתֵּחַ מְעַט כְּדֵי לְהִתְרַעֲנֵן","יִתְאַמֵּן רַק בְּתוֹךְ הַבַּיִת, כְּדֵי שֶׁלֹּא יִרְאוּ אוֹתוֹ","יַעֲשֶׂה חֲצִי מִן הָאִמּוּן, כְּדֵי שֶׁלֹּא יִתְאַמֵּץ בְּשַׁבָּת"],1,"מֻתָּר לַעֲשׂוֹת תְּנוּעוֹת מְעַטּוֹת כְּדֵי לְשַׁחְרֵר אֶת הַגַּב אוֹ הַצַּוָּאר, אוֹ כְּדֵי לְהִתְרַעֲנֵן. אֲבָל תַּרְגִּילֵי הִתְעַמְּלוּת שֶׁנּוֹעֲדוּ לְפַתֵּחַ אֶת הַכֹּשֶׁר אוֹ לִשְׁמֹר עָלָיו – אֲסוּרִים, כִּי הֵם ״עֻבְדִּין דְּחֹל״.","פֶּרֶק כ״ח, הֲלָכָה י״ג","וָחַי בָּהֶם"]]};